const RF_GUIDES=[
  {id:"kolo",panel:"tab-kolo",title:"Jak działa koło wyboru?",html:"      <p class=\"g-lead\">Kapsel ma jeden przycisk, a akcji zwykle potrzeba więcej. Koło wyboru rozwiązuje to bez wymyślania kolejnych gestów: <b>przytrzymaj przycisk</b>, a na ekranie pojawi się koło z wycinkami; <b>pochyl kapsel</b> w stronę wycinka i <b>puść przycisk</b> — pójdzie jego akcja. Jak koło broni w grach.</p>\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 176\" role=\"img\" aria-label=\"Trzy chwile: przytrzymanie przycisku otwiera koło, przechylenie wskazuje wycinek, puszczenie wysyła akcję tego wycinka\">\n          <circle class=\"g-box\" cx=\"106\" cy=\"76\" r=\"44\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M106 76 L137 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M106 76 L137 107\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M106 76 L75 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M106 76 L75 107\"/>\n          <text class=\"g-txt\" x=\"106\" y=\"146\" data-i18n-en=\"1. Hold\">1. Przytrzymaj</text>\n          <text class=\"g-sub\" x=\"106\" y=\"163\" data-i18n-en=\"the capsule button — the wheel opens\">przycisk kapsla — koło się otwiera</text>\n          <circle class=\"g-box\" cx=\"320\" cy=\"76\" r=\"44\"/><path class=\"g-s1\" style=\"fill:var(--pink);fill-opacity:.16\" d=\"M320 76 L351 45 A44 44 0 0 1 351 107 Z\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M320 76 L351 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M320 76 L351 107\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M320 76 L289 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M320 76 L289 107\"/>\n          <path class=\"g-strzalka\" d=\"M320 76 L352 60\"/><path class=\"g-grot\" d=\"M348 52 L360 57 L351 66 Z\"/>\n          <text class=\"g-txt\" x=\"320\" y=\"146\" data-i18n-en=\"2. Lean the capsule\">2. Przechyl kapsel</text>\n          <text class=\"g-sub\" x=\"320\" y=\"163\" data-i18n-en=\"the slice you point at lights up\">wskazany wycinek podświetla się</text>\n          <circle class=\"g-box\" cx=\"534\" cy=\"76\" r=\"44\"/><path class=\"g-s1\" style=\"fill:var(--pink);fill-opacity:.16\" d=\"M534 76 L565 45 A44 44 0 0 1 565 107 Z\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M534 76 L565 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M534 76 L565 107\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M534 76 L503 45\"/><path class=\"g-strzalka\" style=\"stroke-width:1\" d=\"M534 76 L503 107\"/>\n          <path class=\"g-s1\" style=\"stroke-width:1.6\" d=\"M582 76 H598 M574 50 L586 42 M574 102 L586 110\"/>\n          <text class=\"g-txt\" x=\"534\" y=\"146\" data-i18n-en=\"3. Let go\">3. Puść przycisk</text>\n          <text class=\"g-sub\" x=\"534\" y=\"163\" data-i18n-en=\"that slice's action fires\">idzie akcja tego wycinka</text>\n          <path class=\"g-strzalka\" d=\"M160 76 H236\"/><path class=\"g-grot\" d=\"M236 70 L246 76 L236 82 Z\"/>\n          <path class=\"g-strzalka\" d=\"M374 76 H450\"/><path class=\"g-grot\" d=\"M450 70 L460 76 L450 82 Z\"/>\n        </svg>\n        <figcaption data-i18n-en=\"Letting go while the capsule is upright — in the middle of the wheel — sends nothing. That is the emergency exit.\">Puszczenie przycisku, gdy kapsel stoi prosto (czyli w środku koła), nie wysyła nic — to jest wyjście awaryjne.</figcaption>\n      </figure>\n      <h4>Czyje jest koło i co nosi kapsel</h4>\n      <ul>\n        <li><b>Każdy kapsel ma swoje własne koło</b>, a ustawiasz zawsze jedno — tego kapsla, który jest wybrany. Przy dwóch i więcej kapslach mówi to <b>pas kafli na górze ekranu</b>: jeden kafel na kapsel, w środku jego koło w miniaturze, pod spodem sposób sterowania i liczba wycinków, a na kaflu przełącznik, którym włączysz albo wyłączysz koło <i>tamtego</i> kapsla bez przechodzenia na niego. Kliknięcie kafla (albo wybór z listy obok nagłówka) przełącza edycję. Kafel z plakietką <b>ustawiasz teraz</b> i chip kapsla w nagłówku modułu mówią, czyje ustawienia masz pod spodem. Kapsel bez wycinków pisze na kaflu <b>bez wycinków</b>, a jego przełącznik jest nieaktywny: koło zaczyna się od dwóch wycinków.</li>\n        <li><b>Kapsel nosi NAZWANĄ konfigurację</b>, więc nie musisz pamiętać, skąd wzięło się jego koło. Mówi ją PIERWSZA LINIA zakładki „Konfiguracja”, a razem z nią stoją tam przyciski, gdy jest co zrobić: „Zapisz zmiany” (nadpisuje konfigurację tym, co masz teraz) i „Przywróć” (odrzuca zmiany i wraca do zapisanej wersji). Kapsel, którego koło nie ma jeszcze nazwy, dostaje w tym samym miejscu „Utwórz preset”. Reszta porządków siedzi w zakładce „Biblioteka”: zapis pod nową nazwą („+ Zapisz obecne jako…”), wczytanie, „Wczytaj na…” (to samo koło na drugim kapslu), „Pobierz”, zmiana nazwy i usunięcie. Kropka przy nazwie na kaflu kapsla mówi, że koło różni się od zapisanej wersji. Zmiany działają od razu, tak jak w całej aplikacji: nazwa mówi, CZYM to jest, a nie zastępuje zapisywania.\n          <ul>\n            <li><b>Konfiguracja nie niesie przełącznika On</b> ani <b>miejsca wyświetlania</b>. Uzbrojenie wyjścia jest decyzją o tym kapslu w tej chwili, a to, czy koło wyskakuje przy kursorze, czy leży w nakładce nad grą, zależy od stanowiska pracy — nie od tego, jakie masz wycinki. Wczytanie cudzej konfiguracji nie przeniesie Ci więc koła w inne miejsce ekranu.</li>\n            <li><b>Kilka kapsli może nosić tę samą konfigurację.</b> Zapisanie zmian mówi wtedy wprost, kogo jeszcze to dotyczy — ich koła zostają takie, jakie są, i dostaną nową wersję dopiero, gdy je wczytasz.</li>\n          </ul></li>\n        </ul>\n      <h4>Gdzie się to ustawia</h4>\n      <ul>\n        <li><b>Gdzie to ustawisz:</b> własna zakładka <b>Koło wyboru</b>, w nawigacji między Mapowaniem a Myszą. Karta pod pasem kapsli jest podzielona po połowie: po lewej <b>żywy podgląd</b>, po prawej kolumna zwijanych sekcji, w których się edytuje. Dodajesz wycinki (od 2 do 16), każdy dostaje nazwę i akcję — tę samą, co wyzwalacz: klawisz, <code>mouse:left</code>, <code>pad:a</code>. <b>Im więcej wycinków, tym precyzyjniej trzeba celować</b> — rozsądny zakres to 4–8, szesnaście ma sens tylko wtedy, gdy koło jest duże i dobrze znane.</li>\n        <li><b>Podgląd jest żywy i można w nim klikać.</b> Wodzisz myszą po kole, wchodzisz w podmenu, wracasz środkiem; przytrzymanie lewego przycisku stawia koło pod kursorem, tak jak robi to prawdziwe okienko przy kursorze. <b>Nic z podglądu nie idzie do systemu ani do gry</b> — to symulacja w przeglądarce, a jej wyniki lądują tylko w liście „Ostatnie wybory”. Kliknięcie wycinka zaznacza jego wiersz w edytorze i odwrotnie: wiersz, w którym stoisz, podświetla się na kole. Przełącznikiem <b>Myszą / Kapslem</b> przestawiasz podgląd na stan z PRAWDZIWEGO kapsla — trzymasz przycisk, pochylasz i widzisz duże koło zamiast kafelka w rogu. Przyciski <b>⤢ Powiększ</b> (Esc wraca) i <b>⤡ Zwiń</b> oddają miejsce temu, czego akurat potrzeba więcej; układ jest zapamiętywany.</li>\n        <li><b>Presety stoją w zakładce „Biblioteka” i jest to JEDNA lista</b> — Twoje własne i te trzy, które przychodzą z aplikacją (Multimedia z głośnością w podmenu, Zrzuty i schowek, Okna). Fabryczne poznasz po plakietce „z aplikacji”; wolno je wczytać, zapisać pod własną nazwą, pobrać jako plik, wysłać na forum i usunąć — a przycisk „↺ Przywróć fabryczne” w nagłówku listy dokłada z powrotem te, których brakuje: nie rusza Twoich i nie zmienia koła na kapslu. Skasowany przykład nie wraca sam przy aktualizacji: wraca wtedy, kiedy o to poprosisz. Wczytanie presetu NADPISUJE wszystkie wycinki tego kapsla, więc pyta o zgodę; przełącznika On nie rusza.</li>\n        </ul>\n      <h4>Wycinek: podmenu, makro, powtórzenia</h4>\n      <ul>\n        <li><b>Wycinek może otwierać PODMENU</b> zamiast wysyłać akcję — przycisk <b>podmenu</b> w jego wierszu robi listę poziom niżej, a nad listą pojawiają się okruszki, którymi wracasz. Poziomy są trzy i tyle: czwarty pierścień celuje się z pamięci, której nikt nie ma. Wycinek z podmenu nie wysyła nic — to drzwi, nie akcja — więc jego pole akcji jest wtedy nieaktywne.\n          <ul>\n            <li><b>Zastąp koło</b> — dzieci wchodzą w miejsce rodzica, na tym samym pierścieniu. Zawsze się mieści.</li>\n            <li><b>Łuk nad wycinkiem</b> — dzieci wychodzą krótkim łukiem tuż nad rodzicem, reszta pierścienia przygasa. Widać całą drogę naraz.</li>\n            <li><b>Pełna obręcz</b> — dzieci obejmują całe koło drugą obręczą. Duże cele, dla rąk, którym trudno trafić w wąski łuk.</li>\n          </ul>\n          <b>Pochylenie wybiera obręcz:</b> im dalej odchylisz kapsel, tym dalszy pierścień wskazujesz — środek, pierścień główny, dzieci, wnuki. Wycinek, który ma podmenu, ma przy krawędzi trzy kropki, więc widać to, zanim się w niego wejdzie. Wycinek może też dostać <b>ikonę</b> (emoji) i <b>kolor</b>.</li>\n        <li><b>Wycinek może być PUSTY</b> i to jest osobne, celowe ustawienie: pole bez akcji i bez makra. Wybranie go nic nie wysyła, koło po prostu się zamyka, tak samo jak przy anulowaniu. Dodaje je przycisk <b>puste pole</b> pod listą wycinków; nazwa jest nieobowiązkowa, więc możesz je podpisać „odpocznij” albo zostawić bez podpisu. Na kole rysuje się spokojniej od reszty, bez ikony, a w środku koła stoi nad nim zdanie <b>nic nie wysyła</b>. Po co: ręka, która nie utrzyma przycisku równo, potrzebuje miejsca, na którym wolno wylądować bez skutków. W trybie „Pochyl i przytrzymaj” pierścień odliczania na pustym polu w ogóle nie rusza, więc można na nim odpocząć dowolnie długo.</li>\n        <li><b>Wycinek może wykonać MAKRO</b>, a nie tylko jedną akcję: przycisk ⛓ w wierszu wycinka odsłania <b>ten sam edytor makra, co w Mapowaniu</b> — pole na sekwencję (<code>ctrl+c; wait 200; ctrl+v</code>), podgląd kroków, bibliotekę gotowych elementów i przycisk <b>Nagraj makro</b>, który zapisuje naciskane klawisze razem z pauzami (Esc kończy nagranie). Otwarty jest zawsze jeden wiersz naraz, a pozostałe wycinki z makrem pokazują je jednym zdaniem podglądu. Wpisane makro ma pierwszeństwo — pojedyncza akcja tego wycinka jest wtedy pomijana. Składnię opisuje zwijany <b>poradnik pisania makr</b> na dole karty, ten sam, co w edytorze wyzwalacza.</li>\n        <li><b>Wycinek może nacisnąć akcję KILKA RAZY</b> — pole „×” w jego wierszu (od 1 do 20). Klawisz głośności przesuwa suwak Windows o 2%, a koło zamyka się po wyborze, więc „Ciszej” wskazane raz bywa niesłyszalne; przy ×5 jedno wskazanie to jeden wyraźny krok głośności. Zostaw 1 tam, gdzie akcja ma pójść dokładnie raz: przełącznik (wyciszenie, start i pauza) powtórzony sam by się cofnął. Wycinek z podmenu albo z makrem nie ma czego powtarzać, więc pole jest przy nim nieaktywne.</li></ul>\n      <h4>Pięć sposobów sterowania kołem</h4>\n      <p><b>Pięć sposobów sterowania</b> (lista „Sposób” w zwijaku „Sterowanie”), bo „trzymaj przycisk i jednocześnie pochylaj tę samą rękę” nie każdej ręce wychodzi:</p>\n      <table class=\"g-tab\">\n        <thead><tr><th data-i18n-en=\"Way\">Sposób</th><th data-i18n-en=\"What opens the wheel\">Co otwiera koło</th><th data-i18n-en=\"What confirms the choice\">Co zatwierdza wybór</th><th data-i18n-en=\"What cancels\">Co anuluje</th></tr></thead>\n        <tbody>\n          <tr><th scope=\"row\">Trzymaj przycisk i puść</th><td data-i18n-en=\"holding the button down\">przytrzymanie przycisku</td><td data-i18n-en=\"letting the button go\">puszczenie przycisku</td><td data-i18n-en=\"letting go in the middle of the wheel\">puszczenie na środku koła</td></tr>\n          <tr><th scope=\"row\">Pochyl i przytrzymaj</th><td data-i18n-en=\"leaning the capsule hard\">mocne pochylenie kapsla</td><td data-i18n-en=\"waiting on a slice\">odczekanie na wycinku</td><td data-i18n-en=\"bringing the capsule upright\">wyprostowanie kapsla</td></tr>\n          <tr><th scope=\"row\">Pochyl i kliknij</th><td data-i18n-en=\"leaning the capsule hard\">mocne pochylenie kapsla</td><td data-i18n-en=\"a click of the button\">kliknięcie przycisku</td><td data-i18n-en=\"bringing the capsule upright\">wyprostowanie kapsla</td></tr>\n          <tr><th scope=\"row\">Kliknij, pochyl, kliknij</th><td data-i18n-en=\"a click of the button\">kliknięcie przycisku</td><td data-i18n-en=\"a second click\">drugie kliknięcie</td><td data-i18n-en=\"a click with the capsule upright\">kliknięcie przy kapslu prosto</td></tr>\n          <tr><th scope=\"row\">Przełączaj kliknięciami</th><td data-i18n-en=\"a click (which chooses nothing by itself)\">kliknięcie (samo nic nie wybiera)</td><td data-i18n-en=\"waiting on a slice\">odczekanie na wycinku</td><td data-i18n-en=\"holding the button down\">przytrzymanie przycisku</td></tr>\n        </tbody>\n      </table>\n      <h5>Trzymaj przycisk i puść</h5>\n      <figure class=\"g-fig\">\n        <svg class=\"g-anim g-a1\" viewBox=\"0 0 640 170\" role=\"img\" aria-label=\"Animacja: przytrzymany przycisk otwiera koło, przechylenie kapsla wskazuje wycinek, puszczenie przycisku wysyła jego akcję.\">\n          <circle class=\"g-kolo-tlo\" cx=\"76\" cy=\"66\" r=\"46\"/>\n          <g class=\"g-kolo-on\"><circle cx=\"76\" cy=\"66\" r=\"46\"/><circle cx=\"76\" cy=\"66\" r=\"13\"/><path d=\"M76 66 L122 66 M76 66 L99 105.8 M76 66 L53 105.8 M76 66 L30 66 M76 66 L53 26.2 M76 66 L99 26.2\"/></g>\n          <g class=\"g-wsk\"><path class=\"g-klin\" d=\"M76 66 L115.84 43 A46 46 0 0 1 115.84 89 Z\"/><path class=\"g-igla\" d=\"M76 66 L110 66\"/></g>\n          <g class=\"g-btn\"><circle class=\"g-btn-ob\" cx=\"76\" cy=\"140\" r=\"13\"/><circle class=\"g-btn-in\" cx=\"76\" cy=\"140\" r=\"7\"/></g>\n          <text class=\"g-sub\" x=\"76\" y=\"162\" data-i18n-en=\"the capsule button\">przycisk kapsla</text>\n          <g class=\"g-iskra\"><rect x=\"44\" y=\"55\" width=\"64\" height=\"22\" rx=\"8\"/><text x=\"76\" y=\"70\" data-i18n-en=\"action!\">akcja!</text></g>\n          <rect class=\"g-box g-cicho\" x=\"150\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"150\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:0s\"/>\n          <text class=\"g-txt\" x=\"221\" y=\"58\" data-i18n-en=\"1. Press\">1. Naciśnij</text>\n          <text class=\"g-sub\" x=\"221\" y=\"80\" data-i18n-en=\"and hold the button\">i trzymaj przycisk</text>\n          <text class=\"g-sub\" x=\"221\" y=\"97\" data-i18n-en=\"the wheel opens\">koło się otwiera</text>\n          <rect class=\"g-box g-cicho\" x=\"316\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"316\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:2s\"/>\n          <text class=\"g-txt\" x=\"387\" y=\"58\" data-i18n-en=\"2. Lean\">2. Przechyl</text>\n          <text class=\"g-sub\" x=\"387\" y=\"80\" data-i18n-en=\"the capsule towards\">kapsel w stronę</text>\n          <text class=\"g-sub\" x=\"387\" y=\"97\" data-i18n-en=\"the slice you want\">wybranego wycinka</text>\n          <rect class=\"g-box g-cicho\" x=\"482\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"482\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:4s\"/>\n          <text class=\"g-txt\" x=\"553\" y=\"58\" data-i18n-en=\"3. Let go\">3. Puść</text>\n          <text class=\"g-sub\" x=\"553\" y=\"80\" data-i18n-en=\"of the button — the\">przycisk — idzie</text>\n          <text class=\"g-sub\" x=\"553\" y=\"97\" data-i18n-en=\"slice's action fires\">akcja wycinka</text>\n          <path class=\"g-strzalka\" d=\"M297 78 H305\"/><path class=\"g-grot\" d=\"M305 74 L311 78 L305 82 Z\"/>\n          <path class=\"g-strzalka\" d=\"M463 78 H471\"/><path class=\"g-grot\" d=\"M471 74 L477 78 L471 82 Z\"/>\n        </svg>\n        <figcaption data-i18n-en=\"The button stays held for the whole choice. Letting go while the capsule is upright sends nothing.\">Przycisk jest trzymany przez cały wybór. Puszczenie, gdy kapsel stoi prosto, nie wysyła nic.</figcaption>\n      </figure>\n      <p> — sposób pierwotny i domyślny. Przytrzymanie otwiera, puszczenie zatwierdza, puszczenie na środku anuluje.</p>\n      <h5>Pochyl i przytrzymaj</h5>\n      <figure class=\"g-fig\">\n        <svg class=\"g-anim g-a2\" viewBox=\"0 0 640 170\" role=\"img\" aria-label=\"Animacja: mocne pochylenie kapsla otwiera koło, a zatrzymanie wskazania na wycinku domyka pierścień odliczania i wysyła akcję.\">\n          <circle class=\"g-kolo-tlo\" cx=\"76\" cy=\"66\" r=\"46\"/>\n          <g class=\"g-kolo-on\"><circle cx=\"76\" cy=\"66\" r=\"46\"/><circle cx=\"76\" cy=\"66\" r=\"13\"/><path d=\"M76 66 L122 66 M76 66 L99 105.8 M76 66 L53 105.8 M76 66 L30 66 M76 66 L53 26.2 M76 66 L99 26.2\"/></g>\n          <circle class=\"g-odlicz\" cx=\"76\" cy=\"66\" r=\"53\" pathLength=\"100\" transform=\"rotate(-90 76 66)\"/>\n          <g class=\"g-wsk\"><path class=\"g-klin\" d=\"M76 66 L115.84 43 A46 46 0 0 1 115.84 89 Z\"/><path class=\"g-igla\" d=\"M76 66 L110 66\"/></g>\n          <line class=\"g-podloga\" x1=\"56\" y1=\"140.5\" x2=\"96\" y2=\"140.5\"/><g class=\"g-kaps\" style=\"transform-origin:76px 140px\"><rect x=\"62\" y=\"126\" width=\"28\" height=\"11\" rx=\"5\"/></g>\n          <text class=\"g-sub\" x=\"76\" y=\"162\" data-i18n-en=\"leaning, no button\">przechył, bez przycisku</text>\n          <g class=\"g-iskra\"><rect x=\"44\" y=\"55\" width=\"64\" height=\"22\" rx=\"8\"/><text x=\"76\" y=\"70\" data-i18n-en=\"action!\">akcja!</text></g>\n          <rect class=\"g-box g-cicho\" x=\"150\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"150\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:0s\"/>\n          <text class=\"g-txt\" x=\"221\" y=\"58\" data-i18n-en=\"1. Lean\">1. Przechyl</text>\n          <text class=\"g-sub\" x=\"221\" y=\"80\" data-i18n-en=\"hard — the wheel\">mocno — koło</text>\n          <text class=\"g-sub\" x=\"221\" y=\"97\" data-i18n-en=\"opens\">się otwiera</text>\n          <rect class=\"g-box g-cicho\" x=\"316\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"316\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:2s\"/>\n          <text class=\"g-txt\" x=\"387\" y=\"58\" data-i18n-en=\"2. Hold still\">2. Zatrzymaj</text>\n          <text class=\"g-sub\" x=\"387\" y=\"80\" data-i18n-en=\"pointing at one\">wskazanie na</text>\n          <text class=\"g-sub\" x=\"387\" y=\"97\" data-i18n-en=\"slice\">jednym wycinku</text>\n          <rect class=\"g-box g-cicho\" x=\"482\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"482\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:4s\"/>\n          <text class=\"g-txt\" x=\"553\" y=\"58\" data-i18n-en=\"3. Wait\">3. Odczekaj</text>\n          <text class=\"g-sub\" x=\"553\" y=\"80\" data-i18n-en=\"the ring closes and\">pierścień domyka się</text>\n          <text class=\"g-sub\" x=\"553\" y=\"97\" data-i18n-en=\"the action fires\">i idzie akcja</text>\n          <path class=\"g-strzalka\" d=\"M297 78 H305\"/><path class=\"g-grot\" d=\"M305 74 L311 78 L305 82 Z\"/>\n          <path class=\"g-strzalka\" d=\"M463 78 H471\"/><path class=\"g-grot\" d=\"M471 74 L477 78 L471 82 Z\"/>\n        </svg>\n        <figcaption data-i18n-en=\"No button at all. You set the time to confirm with a slider, and straightening the capsule closes the wheel with nothing sent.\">Bez przycisku. Czas do zatwierdzenia ustawiasz suwakiem, a wyprostowanie kapsla zamyka koło bez akcji.</figcaption>\n      </figure>\n      <p> — bez przycisku w ogóle. Mocne pochylenie otwiera koło, utrzymanie wskazania na jednym wycinku przez <b>Czas do zatwierdzenia</b> wysyła je, wyprostowanie kapsla zamyka bez akcji.</p>\n      <h5>Pochyl i kliknij</h5>\n      <figure class=\"g-fig\">\n        <svg class=\"g-anim g-a3\" viewBox=\"0 0 640 170\" role=\"img\" aria-label=\"Animacja: mocne pochylenie kapsla otwiera koło, przechył wskazuje wycinek, a kliknięcie przycisku wysyła jego akcję.\">\n          <circle class=\"g-kolo-tlo\" cx=\"76\" cy=\"66\" r=\"46\"/>\n          <g class=\"g-kolo-on\"><circle cx=\"76\" cy=\"66\" r=\"46\"/><circle cx=\"76\" cy=\"66\" r=\"13\"/><path d=\"M76 66 L122 66 M76 66 L99 105.8 M76 66 L53 105.8 M76 66 L30 66 M76 66 L53 26.2 M76 66 L99 26.2\"/></g>\n          <g class=\"g-wsk\"><path class=\"g-klin\" d=\"M76 66 L115.84 43 A46 46 0 0 1 115.84 89 Z\"/><path class=\"g-igla\" d=\"M76 66 L110 66\"/></g>\n          <line class=\"g-podloga\" x1=\"24\" y1=\"140.5\" x2=\"64\" y2=\"140.5\"/><g class=\"g-kaps\" style=\"transform-origin:44px 140px\"><rect x=\"30\" y=\"126\" width=\"28\" height=\"11\" rx=\"5\"/></g>\n          <g class=\"g-btn\"><circle class=\"g-btn-ob\" cx=\"108\" cy=\"140\" r=\"13\"/><circle class=\"g-btn-in\" cx=\"108\" cy=\"140\" r=\"7\"/></g>\n          <text class=\"g-sub\" x=\"76\" y=\"162\" data-i18n-en=\"the lean opens, the button confirms\">przechył otwiera, przycisk zatwierdza</text>\n          <g class=\"g-iskra\"><rect x=\"44\" y=\"55\" width=\"64\" height=\"22\" rx=\"8\"/><text x=\"76\" y=\"70\" data-i18n-en=\"action!\">akcja!</text></g>\n          <rect class=\"g-box g-cicho\" x=\"150\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"150\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:0s\"/>\n          <text class=\"g-txt\" x=\"221\" y=\"58\" data-i18n-en=\"1. Lean\">1. Przechyl</text>\n          <text class=\"g-sub\" x=\"221\" y=\"80\" data-i18n-en=\"hard — the wheel\">mocno — koło</text>\n          <text class=\"g-sub\" x=\"221\" y=\"97\" data-i18n-en=\"opens\">się otwiera</text>\n          <rect class=\"g-box g-cicho\" x=\"316\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"316\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:2s\"/>\n          <text class=\"g-txt\" x=\"387\" y=\"58\" data-i18n-en=\"2. Point\">2. Wskaż</text>\n          <text class=\"g-sub\" x=\"387\" y=\"80\" data-i18n-en=\"at a slice by\">wycinek</text>\n          <text class=\"g-sub\" x=\"387\" y=\"97\" data-i18n-en=\"leaning\">przechyleniem</text>\n          <rect class=\"g-box g-cicho\" x=\"482\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"482\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:4s\"/>\n          <text class=\"g-txt\" x=\"553\" y=\"58\" data-i18n-en=\"3. Click\">3. Kliknij</text>\n          <text class=\"g-sub\" x=\"553\" y=\"80\" data-i18n-en=\"the button — the\">przycisk — idzie</text>\n          <text class=\"g-sub\" x=\"553\" y=\"97\" data-i18n-en=\"slice's action fires\">akcja wycinka</text>\n          <path class=\"g-strzalka\" d=\"M297 78 H305\"/><path class=\"g-grot\" d=\"M305 74 L311 78 L305 82 Z\"/>\n          <path class=\"g-strzalka\" d=\"M463 78 H471\"/><path class=\"g-grot\" d=\"M471 74 L477 78 L471 82 Z\"/>\n        </svg>\n        <figcaption data-i18n-en=\"The hand holds nothing for the whole choice: the lean opens it, a single click confirms.\">Ręka nie trzyma niczego przez cały wybór: otwiera przechył, zatwierdza jedno kliknięcie.</figcaption>\n      </figure>\n      <p> — otwiera się pochyleniem, zatwierdza kliknięciem przycisku.</p>\n      <h5>Kliknij, pochyl, kliknij</h5>\n      <figure class=\"g-fig\">\n        <svg class=\"g-anim g-a4\" viewBox=\"0 0 640 170\" role=\"img\" aria-label=\"Animacja: kliknięcie otwiera koło i zostawia je otwarte, przechył wskazuje wycinek, drugie kliknięcie wysyła jego akcję.\">\n          <circle class=\"g-kolo-tlo\" cx=\"76\" cy=\"66\" r=\"46\"/>\n          <g class=\"g-kolo-on\"><circle cx=\"76\" cy=\"66\" r=\"46\"/><circle cx=\"76\" cy=\"66\" r=\"13\"/><path d=\"M76 66 L122 66 M76 66 L99 105.8 M76 66 L53 105.8 M76 66 L30 66 M76 66 L53 26.2 M76 66 L99 26.2\"/></g>\n          <g class=\"g-wsk\"><path class=\"g-klin\" d=\"M76 66 L115.84 43 A46 46 0 0 1 115.84 89 Z\"/><path class=\"g-igla\" d=\"M76 66 L110 66\"/></g>\n          <line class=\"g-podloga\" x1=\"24\" y1=\"140.5\" x2=\"64\" y2=\"140.5\"/><g class=\"g-kaps\" style=\"transform-origin:44px 140px\"><rect x=\"30\" y=\"126\" width=\"28\" height=\"11\" rx=\"5\"/></g>\n          <g class=\"g-btn\"><circle class=\"g-btn-ob\" cx=\"108\" cy=\"140\" r=\"13\"/><circle class=\"g-btn-in\" cx=\"108\" cy=\"140\" r=\"7\"/></g>\n          <text class=\"g-sub\" x=\"76\" y=\"162\" data-i18n-en=\"two clicks with a lean in between\">dwa kliknięcia i przechył między nimi</text>\n          <g class=\"g-iskra\"><rect x=\"44\" y=\"55\" width=\"64\" height=\"22\" rx=\"8\"/><text x=\"76\" y=\"70\" data-i18n-en=\"action!\">akcja!</text></g>\n          <rect class=\"g-box g-cicho\" x=\"150\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"150\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:0s\"/>\n          <text class=\"g-txt\" x=\"221\" y=\"58\" data-i18n-en=\"1. Click\">1. Kliknij</text>\n          <text class=\"g-sub\" x=\"221\" y=\"80\" data-i18n-en=\"the wheel stays\">koło zostaje</text>\n          <text class=\"g-sub\" x=\"221\" y=\"97\" data-i18n-en=\"open on its own\">otwarte samo</text>\n          <rect class=\"g-box g-cicho\" x=\"316\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"316\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:2s\"/>\n          <text class=\"g-txt\" x=\"387\" y=\"58\" data-i18n-en=\"2. Lean\">2. Przechyl</text>\n          <text class=\"g-sub\" x=\"387\" y=\"80\" data-i18n-en=\"point at a slice,\">wskaż wycinek,</text>\n          <text class=\"g-sub\" x=\"387\" y=\"97\" data-i18n-en=\"the hand may rest\">ręka może odpocząć</text>\n          <rect class=\"g-box g-cicho\" x=\"482\" y=\"26\" width=\"142\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"482\" y=\"26\" width=\"142\" height=\"104\" rx=\"10\" style=\"animation-delay:4s\"/>\n          <text class=\"g-txt\" x=\"553\" y=\"58\" data-i18n-en=\"3. Click\">3. Kliknij</text>\n          <text class=\"g-sub\" x=\"553\" y=\"80\" data-i18n-en=\"again — the slice's\">drugi raz — idzie</text>\n          <text class=\"g-sub\" x=\"553\" y=\"97\" data-i18n-en=\"action fires\">akcja wycinka</text>\n          <path class=\"g-strzalka\" d=\"M297 78 H305\"/><path class=\"g-grot\" d=\"M305 74 L311 78 L305 82 Z\"/>\n          <path class=\"g-strzalka\" d=\"M463 78 H471\"/><path class=\"g-grot\" d=\"M471 74 L477 78 L471 82 Z\"/>\n        </svg>\n        <figcaption data-i18n-en=\"Nothing has to be held. A second click with the capsule upright cancels, and the wheel gives up by itself after 8 seconds.\">Nic nie trzeba trzymać. Drugie kliknięcie przy kapslu ustawionym prosto anuluje, a koło samo znika po 8 sekundach.</figcaption>\n      </figure>\n      <p> — kliknięcie otwiera koło i zostaje ono otwarte samo, bez trzymania czegokolwiek; drugie kliknięcie zatwierdza, a przy kapslu ustawionym prosto anuluje.</p>\n      <h5>Przełączaj kliknięciami</h5>\n      <figure class=\"g-fig\">\n        <svg class=\"g-anim g-a5\" viewBox=\"0 0 640 170\" role=\"img\" aria-label=\"Animacja: pierwsze kliknięcie budzi koło i niczego nie wybiera, kolejne przechodzą po wycinkach, odczekanie wysyła akcję, a przytrzymanie usypia koło.\">\n          <circle class=\"g-kolo-tlo\" cx=\"76\" cy=\"66\" r=\"46\"/>\n          <g class=\"g-kolo-on\"><circle cx=\"76\" cy=\"66\" r=\"46\"/><circle cx=\"76\" cy=\"66\" r=\"13\"/><path d=\"M76 66 L122 66 M76 66 L99 105.8 M76 66 L53 105.8 M76 66 L30 66 M76 66 L53 26.2 M76 66 L99 26.2\"/></g>\n          <circle class=\"g-odlicz\" cx=\"76\" cy=\"66\" r=\"53\" pathLength=\"100\" transform=\"rotate(-90 76 66)\"/>\n          <g class=\"g-wsk\"><path class=\"g-klin\" d=\"M76 66 L115.84 43 A46 46 0 0 1 115.84 89 Z\"/><path class=\"g-igla\" d=\"M76 66 L110 66\"/></g>\n          <g class=\"g-btn\"><circle class=\"g-btn-ob\" cx=\"76\" cy=\"140\" r=\"13\"/><circle class=\"g-btn-in\" cx=\"76\" cy=\"140\" r=\"7\"/></g>\n          <text class=\"g-sub\" x=\"76\" y=\"162\" data-i18n-en=\"the button alone, no aiming\">sam przycisk, bez celowania</text>\n          <g class=\"g-iskra\"><rect x=\"44\" y=\"55\" width=\"64\" height=\"22\" rx=\"8\"/><text x=\"76\" y=\"70\" data-i18n-en=\"action!\">akcja!</text></g>\n          <rect class=\"g-box g-cicho\" x=\"150\" y=\"26\" width=\"106\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"150\" y=\"26\" width=\"106\" height=\"104\" rx=\"10\" style=\"animation-delay:0s\"/>\n          <text class=\"g-txt\" x=\"203\" y=\"58\" data-i18n-en=\"1. Click\">1. Kliknij</text>\n          <text class=\"g-sub\" x=\"203\" y=\"80\" data-i18n-en=\"the wheel wakes,\">koło się budzi,</text>\n          <text class=\"g-sub\" x=\"203\" y=\"97\" data-i18n-en=\"nothing is chosen\">nic nie wybiera</text>\n          <rect class=\"g-box g-cicho\" x=\"272\" y=\"26\" width=\"106\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"272\" y=\"26\" width=\"106\" height=\"104\" rx=\"10\" style=\"animation-delay:2s\"/>\n          <text class=\"g-txt\" x=\"325\" y=\"58\" data-i18n-en=\"2. Click again\">2. Klikaj</text>\n          <text class=\"g-sub\" x=\"325\" y=\"80\" data-i18n-en=\"each click steps\">każde kliknięcie</text>\n          <text class=\"g-sub\" x=\"325\" y=\"97\" data-i18n-en=\"to the next slice\">= kolejny wycinek</text>\n          <rect class=\"g-box g-cicho\" x=\"394\" y=\"26\" width=\"106\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"394\" y=\"26\" width=\"106\" height=\"104\" rx=\"10\" style=\"animation-delay:4s\"/>\n          <text class=\"g-txt\" x=\"447\" y=\"58\" data-i18n-en=\"3. Wait\">3. Odczekaj</text>\n          <text class=\"g-sub\" x=\"447\" y=\"80\" data-i18n-en=\"that slice's action\">idzie akcja tego</text>\n          <text class=\"g-sub\" x=\"447\" y=\"97\" data-i18n-en=\"fires\">wycinka</text>\n          <rect class=\"g-box g-cicho\" x=\"516\" y=\"26\" width=\"106\" height=\"104\"/>\n          <rect class=\"g-ramka\" x=\"516\" y=\"26\" width=\"106\" height=\"104\" rx=\"10\" style=\"animation-delay:6s\"/>\n          <text class=\"g-txt\" x=\"569\" y=\"58\" data-i18n-en=\"4. Hold\">4. Przytrzymaj</text>\n          <text class=\"g-sub\" x=\"569\" y=\"80\" data-i18n-en=\"the wheel sleeps,\">koło zasypia,</text>\n          <text class=\"g-sub\" x=\"569\" y=\"97\" data-i18n-en=\"nothing is sent\">nic nie wysyła</text>\n        </svg>\n        <figcaption data-i18n-en=\"The only way in which leaning means nothing at all — the same one button does everything.\">Jedyny sposób, w którym pochylenie nie znaczy nic — wszystko robi ten sam przycisk.</figcaption>\n      </figure>\n      <p> — dla osób, którym celowanie pochyleniem sprawia trudność, i jedyny tryb, w którym <b>pochylanie nie znaczy zupełnie nic</b>. Wszystko robi ten sam przycisk, a koło mówi w środku, co znaczy on TERAZ: pierwsze kliknięcie <b>włącza koło</b> i niczego przy tym nie wybiera, każde następne przechodzi na kolejny wycinek, <b>odczekanie</b> wysyła ten, na którym stanąłeś, a <b>przytrzymanie przycisku wyłącza koło</b> i nie wysyła nic. Wyłączone koło jest przygaszone, więc widać z drugiego końca pokoju, czy słucha; to co innego niż przełącznik On na kaflu kapsla, którym włącza się cały moduł. Dlaczego pierwsze kliknięcie tylko włącza: bez tego jedno przypadkowe naciśnięcie — rękaw, zagłówek, ręka szukająca oparcia — od razu stawiało wybór na pierwszym wycinku i po chwili wysyłało jego akcję. Ten tryb ma dwa własne ustawienia:</p>\n              <ul>\n                <li><b>Koło zawsze widoczne</b> (domyślnie włączone) — wyłączone koło stoi na ekranie przygaszone i mówi w środku, że czeka na kliknięcie: widać, gdzie jest i co ma, zanim się je włączy, a po wysłaniu akcji zostaje w tym samym miejscu i znów jest wyłączone. Bez tego ustawienia wyłączonego koła nie widać wcale, a na ekranie stawia je to samo kliknięcie, które je włącza. <b>Włączone i zostawione samo sobie wyłącza się po 8 sekundach</b> bez wysyłania czegokolwiek — tyle kosztuje pomyłkowe naciśnięcie.</li>\n                <li><b>Czym przesuwasz wybór</b>: <b>Przycisk kapsla</b> albo <b>Pochylenie</b>. To drugie jest dla kogoś, kto nie ma jak nacisnąć: kapsel na czapce, przy głowie, przypięty do ubrania. Ponieważ wycinki lecą po kolei, <b>kierunek nic tu nie znaczy</b> — liczy się samo wyjście poza próg i powrót. Wybierasz jeszcze <b>Kierunek</b> (dowolny / tylko w przód i w tył / tylko na boki — skinienie w dół jest łatwiejsze niż przechył na bok, a przy części niepełnosprawności ruch boczny szyi jest niedostępny) oraz <b>Siłę pochylenia</b>. ⚠️ Zanim zaczniesz, ustaw kapsel tak, jak będzie noszony, i naciśnij <b>⌖ Wyśrodkuj kapsel</b>: kapsel na czapce ma inny punkt zerowy niż na stole i inny dla każdej głowy, więc bez tego próg będzie albo nieosiągalny, albo wyzwoli się sam. Sprawdź też suwak <b>Przytrzymanie wyłącza koło</b>: skinienie trwa dłużej niż kliknięcie palcem, a pochylenie utrzymane ponad ten czas wyłącza koło. Przy tym wyzwalaczu koło stoi zawsze i nie da się tego wyłączyć — bez rysunku na ekranie nie miałbyś jak sprawdzić, czy skinienie w ogóle przechodzi przez próg.</li>\n              </ul>\n      <p>⚠️ <b>Tryby otwierane pochyleniem gryzą się z prowadzeniem kursora.</b> Jeśli TEN SAM kapsel prowadzi mysz albo gałkę, jego pochylenia mają już swoje zadanie i koło będzie się otwierać w środku celowania. Najlepiej dać te tryby kapslowi, który nie steruje kursorem. Dlatego próg otwarcia jest wysoki i nie ma na niego suwaka: musi być wyraźnie większy niż wszystko, co robi się przy zwykłym sterowaniu. Dotyczy to dwóch trybów pochyleniowych — <b>Przełączaj kliknięciami</b> nie czyta pochylenia w ogóle, więc jest tu bezpieczny.</p>\n      <h4 data-i18n-en=\"The wheel together with the screen scanner\">Koło razem ze skanerem ekranu</h4>\n      <p data-i18n-en=\"For somebody with one reliable movement this is the shortest way to running a whole game off one button: the wheel picks WHICH scanner you want to click with, and the scanner does the rest.\"><span data-i18n-en=\"A slice of the wheel sends\">Wycinek koła wysyła</span> <b data-i18n-en=\"the very same action as a Mapping rule\">taką samą akcję, jak reguła Mapowania</b><span data-i18n-en=\", which means it can also start the\">, a to znaczy, że może też uruchomić</span> <b data-i18n-en=\"screen scanner\">skaner ekranu</b>. Dla kogoś, kto ma jeden pewny ruch, jest to najkrótsza droga do obsłużenia całej gry jednym przyciskiem: koło wybiera, KTÓRYM skanerem chcesz teraz klikać, a sam skaner robi resztę.</p>\n      <ul>\n        <li data-i18n-en=\"The scanner cannot see what is on the game's screen right now, so a person switches the views and the scanners. With three views of a game — the board, the action bar, the dialogue window — that used to take three separate triggers, which is three gestures. The wheel makes it one: hold the button, point at “Action bar”, let go.\"><b data-i18n-en=\"Who needs this.\">Po co to komu.</b> Skaner nie widzi, co jest w tej chwili na ekranie gry, więc plansze i skanery przełącza człowiek. Przy trzech widokach gry — plansza, pasek akcji, okno dialogu — potrzebne były do tej pory trzy osobne wyzwalacze, czyli trzy gesty. Koło robi z tego jeden: przytrzymujesz przycisk, wskazujesz „Pasek akcji”, puszczasz.</li>\n        <li data-i18n-en=\"— exactly the same thing you would write in a rule:\"><b data-i18n-en=\"What to put in the slice's action\">Co wpisać w akcję wycinka</b> — dokładnie to samo, co w regule:</li>\n      </ul>\n      <table class=\"g-tab\">\n        <thead><tr><th data-i18n-en=\"The slice's action\">Akcja wycinka</th><th data-i18n-en=\"What it does\">Co robi</th></tr></thead>\n        <tbody>\n          <tr><th scope=\"row\"><code>scan:sekcja=2</code></th><td data-i18n-en=\"switches on the second scanner of the configuration and shows its outline\">włącza drugi skaner z konfiguracji i pokazuje jego obrys</td></tr>\n          <tr><th scope=\"row\"><code>scan:sekcja=nast</code></th><td data-i18n-en=\"the next scanner in the current group, wrapping around\">następny skaner w bieżącej grupie, z zawijaniem</td></tr>\n          <tr><th scope=\"row\"><code>scan:sygnal</code></th><td data-i18n-en=\"stops the bar — the same as the SIGNAL button\">zatrzymuje pasek — to samo, co przycisk SYGNAŁ</td></tr>\n          <tr><th scope=\"row\"><code>scan:cofnij</code></th><td data-i18n-en=\"one step back, when the bar got away\">o krok wstecz, gdy pasek uciekł</td></tr>\n          <tr><th scope=\"row\"><code>scan:stop</code></th><td data-i18n-en=\"breaks the scan off and goes back to rest\">przerywa skanowanie i wraca do spoczynku</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><b data-i18n-en=\"How to put it together.\">Jak to złożyć w całość.</b> <span data-i18n-en=\"Make a wheel with as many slices as the game has views and give each of them the action\">Zrób koło z tylu wycinków, ile masz widoków gry, i daj każdemu akcję</span> <code>scan:sekcja=N</code> <span data-i18n-en=\"— name the slices after the scanners, because those are the names you will see at the moment of choosing. The last slice is worth spending on\">— nazwy wycinków niech będą nazwami skanerów, bo to je zobaczysz w chwili wyboru. Ostatni wycinek warto przeznaczyć na</span> <code>scan:stop</code><span data-i18n-en=\", and one is worth leaving\">, a jeden zostawić</span> <b data-i18n-en=\"empty\">pusty</b><span data-i18n-en=\": that is the way out for a hand that pressed by accident.\">: to jest wyjście dla ręki, która nacisnęła przez przypadek.</span></li>\n        <li>💡 <b data-i18n-en=\"One button for everything.\">Jeden przycisk na wszystko.</b> <span data-i18n-en=\"The wheel does not swallow the press, so the same button can carry a Mapping rule with\">Koło nie połyka naciśnięcia, więc ten sam przycisk może jednocześnie mieć w Mapowaniu regułę</span> <code>scan:sygnal</code><span data-i18n-en=\" at the same time. A short press is then the signal for the scanner at work, and holding the button opens the wheel and lets you change the scanner — with no second gesture and no second capsule.\">. Krótkie naciśnięcie jest wtedy sygnałem dla pracującego skanera, a przytrzymanie otwiera koło i pozwala zmienić skaner — bez drugiego gestu i bez drugiego kapsla.</span></li>\n        <li>⚠️ <b data-i18n-en=\"The signal will also go out as the wheel opens.\">Sygnał pójdzie także przy otwieraniu koła.</b> <span data-i18n-en=\"That is the same trait seen from the other side: a rule on the button fires in the very moment the hold opens the wheel. With the scanner at rest that means nothing, but with the scanner running the bar will stop. If it gets in the way — give the wheel a different button, or switch it to\">To ta sama cecha widziana od drugiej strony: reguła na przycisk zadziała również w chwili, w której przytrzymanie otwiera koło. Przy zatrzymanym skanerze nic to nie znaczy, ale przy skanerze w biegu pasek stanie. Jeśli przeszkadza — daj kołu inny przycisk albo przełącz je na</span> <b>Przełączaj kliknięciami</b><span data-i18n-en=\", where the wheel only opens on the first click.\">, gdzie koło otwiera dopiero pierwsze kliknięcie.</span></li>\n        <li data-i18n-en=\"If you drive the scanner by leaning (the “What drives the scanner” section), do not give the same capsule a wheel that opens on a lean — both things would answer the same movement. The safe pairs are “Hold the button and let go” and “Step through it with clicks”.\">⚠️ <b data-i18n-en=\"Do not mix two things driven by the lean.\">Nie mieszaj dwóch rzeczy sterowanych przechyłem.</b> Jeśli skanerem sterujesz wychyleniem (sekcja „Czym sterujesz skanerem”), nie dawaj temu samemu kapslowi koła otwieranego pochyleniem — obie rzeczy będą reagowały na ten sam ruch. Bezpieczne pary to „Trzymaj przycisk i puść” oraz „Przełączaj kliknięciami”.</li>\n        <li data-i18n-en=\"A scanner's click and a slice's action leave through the same gate: a paused capsule will show the wheel and will show the scanner's outline, but it will click nothing.\"><b data-i18n-en=\"Being armed counts once.\">Uzbrojenie liczy się raz.</b> Kliknięcie skanera i akcja wycinka wychodzą tą samą bramką: wstrzymany kapsel pokaże koło i pokaże obrys skanera, ale nie kliknie niczego.</li>\n      </ul>\n      <h4>Wygląd i martwa strefa</h4>\n      <ul>\n        <li><b>Wygląd: w tej karcie ustawiasz LICZBY, a styl przy oknie.</b> Sekcja „Wygląd” daje cztery suwaki kształtu: wielkość koła (średnica w pikselach — jedna liczba na wszystkie miejsca naraz: okienko przy kursorze, nakładkę nad grą i podgląd obok), odstęp wycinków, zaokrąglenie rogów i wielkość pisma. Odstęp wycina się ze ŚRODKA wycinka, więc celujesz dokładnie tam, gdzie dotąd — zmienia się rysunek, nie granice.\n          <ul>\n            <li data-i18n-en=\"The same wheel looks different in every overlay it stands over, so one button in the wheel's own card would not be telling the truth about the other windows. There are five looks, and each of them is an answer to a different background under the wheel:\"><b>Styl należy do OKNA, nie do koła.</b> To samo koło wygląda inaczej w każdej nakładce, nad którą stoi, więc jeden przycisk w karcie koła nie mówiłby prawdy o pozostałych oknach. Stylów jest pięć, a każdy jest odpowiedzią na inne tło pod kołem:</li>\n          </ul>\n          <table class=\"g-tab\">\n            <thead><tr><th data-i18n-en=\"Look\">Styl</th><th data-i18n-en=\"How it looks\">Jak wygląda</th><th data-i18n-en=\"When to reach for it\">Kiedy po niego sięgnąć</th></tr></thead>\n            <tbody>\n              <tr><th scope=\"row\">Jasny</th><td data-i18n-en=\"a cream card, like the panel\">kremowa karta jak w panelu</td><td data-i18n-en=\"the default; over a dark game and on the desktop\">domyślny; nad ciemną grą i na pulpicie</td></tr>\n              <tr><th scope=\"row\">Ciemny</th><td data-i18n-en=\"a dark card with light lettering\">ciemna karta, jasne napisy</td><td data-i18n-en=\"over a bright game, where a light card dazzles\">nad jasną grą, gdzie jasna karta oślepia</td></tr>\n              <tr><th scope=\"row\">Sama treść</th><td data-i18n-en=\"no card — only the contents are left\">bez karty — zostaje sama zawartość</td><td data-i18n-en=\"when the wheel should cover as little as it can\">gdy koło ma jak najmniej zasłaniać</td></tr>\n              <tr><th scope=\"row\">Neon</th><td data-i18n-en=\"a navy card and almost black slices with glowing edges\">granatowa karta, prawie czarne wycinki ze świecącymi krawędziami</td><td data-i18n-en=\"for a stream, and anywhere the wheel has to be visible from across the room\">na stream i wszędzie tam, gdzie koło ma być widać z drugiego końca pokoju</td></tr>\n              <tr><th scope=\"row\">Szkło</th><td data-i18n-en=\"a light, cool card and slices like frosted glass\">jasna, chłodna karta i wycinki jak matowa szyba</td><td data-i18n-en=\"over the desktop and over application windows\">nad pulpitem i nad oknami programów</td></tr>\n            </tbody>\n          </table>\n          <ul>\n            <li><b>Okienko przy kursorze ustawia się na ekranie „Nakładka”.</b> W karcie „Nakładki nad grą” stoi kafel z kreskowaną obwódką podpisany „koło przy kursorze” — to w nim wybierasz jego styl. Zwykłą nakładkę ustawia się tam samo albo w jej własnej szufladzie ⚙, sekcja Wygląd. Zdanie na dole sekcji Wygląd w karcie koła mówi, jaki styl nosi teraz to okienko, i prowadzi we właściwe miejsce.</li>\n            <li><b>Podgląd obok rysuje jeden styl — ten obszywany ściegiem.</b> I tak ma być: podgląd pokazuje KSZTAŁT, czyli dokładnie to, co ustawiają suwaki. Różne okna mogą wyglądać różnie i o to chodzi: nakładka dla widzów bywa jasna, a okienko przy kursorze neonowe, bo jedno stoi nad streamem, a drugie nad grą.</li>\n            <li>⚠️ Nad grą tło okna jest wycięte, więc Szkło nie ma czego rozmyć i zostaje tam matową tarczą — a jego karta jest nieprzezroczysta, bo półprzezroczysta zniknęłaby razem z wycięciem.</li>\n          </ul>\n        </li>\n        <li><b>Zapis</b> w zwijaku „Zaawansowane” na dole kolumny: <b>Importuj JSON</b> wczytuje cudze koło albo preset z forum — przez tę samą sanityzację, co zwykły zapis, więc obcięte nazwy, odrzucone <code>layer:</code> i za głębokie drzewo zobaczysz od razu na liście. Import nigdy nie włącza koła za Ciebie. Drugi przycisk, <b>Ustawienia domyślne (wycinki zostają)</b>, cofa sposób sterowania, czasy, martwą strefę, kształt podmenu i wygląd, a listy wycinków nie rusza. Eksportu tu nie ma: gotowy plik do wysłania komuś pobierzesz w zakładce „Biblioteka” przyciskiem „Pobierz”.</li>\n        <li><b>Martwa strefa</b> to środek koła, w którym nic nie jest wskazane. Suwak „Martwa strefa” w „Zaawansowane” › „Strojenie sterowania” pozwala ją zwęzić (szybszy wybór małym ruchem) albo poszerzyć (spokojniejsza ręka nic nie wybiera przez przypadek). Przy bardzo szerokiej strefie próg otwarcia w trybach pochyleniowych podnosi się sam, żeby zostać wyraźnie poza nią.</li>\n        </ul>\n      <h4>Jak koło zachowuje się w biegu</h4>\n      <ul>\n        <li>⚠️ <b>Koło otwiera GEST, nie zastane pochylenie.</b> Zanim pochylenie zacznie cokolwiek znaczyć, kapsel musi raz powiedzieć „stoję prosto” — czyli trafić do martwej strefy. Kapsel, który w chwili włączenia koła już leży na boku albo siedzi na przechylonej głowie, nie otworzy niczego i niczego nie wyśle, dopóki nie wróci do środka. W podglądzie widać to jako <b>dwa przerywane okręgi</b> na zamkniętej scenie, bo progi są dwa: w mniejszy trzeba <b>wejść</b> (to martwa strefa — stąd wychylenie zaczyna cokolwiek znaczyć), a większy trzeba <b>przekroczyć</b> (to próg otwarcia, celowo dużo dalej niż martwa strefa — inaczej koło otwierałoby się przy zwykłym sterowaniu kursorem). Po wejściu w mniejszy oba zmieniają barwę, a na większym pojawia się podpis „przekrocz tę linię”.</li>\n        <li>Wszystkie trzy koła <b>bez trzymania</b> (pochyleniowe i „Kliknij, pochyl, kliknij”) zamykają się same po <b>8 sekundach</b> bez decyzji i nic wtedy nie wysyłają. W trybie <b>Przełączaj kliknięciami</b> ten sam czas WYŁĄCZA koło zamiast je chować: włączone i zostawione samo sobie po prostu przygasa, a stojące na stałe zostaje na ekranie, bo tam nie ma czego chować.</li>\n        <li><b>Podgląd da się obsłużyć klawiaturą.</b> Tabulatorem dochodzisz do sceny, strzałki przechodzą po wycinkach, a <b>Enter albo spacja wybiera od razu</b> — bez przytrzymywania czegokolwiek, bo wymuszone trzymanie jest barierą przy drżeniu i słabym chwycie. Esc zamyka koło. Czytnik ekranu mówi przy każdej zmianie, co jest wskazane („Widok zadań — 2 z 6”), i co zostało wybrane.</li>\n        </ul>\n      <h4>Gdzie koło się pokazuje</h4>\n      <ul>\n        <li><b>Gdzie je zobaczysz — i to jest jeden wybór:</b> koło umie się narysować w trzech miejscach: na ściądze (zakładka „Wszystko”), w nakładkach nad grą i w osobnym okienku wokół wskaźnika myszy. W zwijaku „Gdzie pokazywać koło” wybierasz jedno miejsce: „Przy kursorze”, „W nakładkach”, „W obu” albo „Na środku ekranu”, więc koło nie pokazuje się w dwóch miejscach naraz, chyba że sam o to poprosisz („W obu” ma sens, gdy nakładka jest dla widzów, a okienko dla Ciebie). Poza chwilą wyboru koła nie ma wcale — nie zajmuje miejsca, dopóki nie jest otwarte.</li>\n        <li><b>Przy kursorze:</b> koło pokazuje się dokładnie wokół wskaźnika myszy — tam, gdzie i tak patrzysz w chwili wyboru, zamiast w rogu ekranu. Okienko jest niewidoczne, dopóki koło nie jest otwarte, nigdy nie łapie kliknięć (więc kliknięcie zatwierdzające trafia do gry), a jego wygląd i przezroczystość ustawiasz tuż pod wyborem. Wielkość bierze się z suwaka <b>Wielkość koła</b> w zwijaku „Wygląd”, jedna liczba na wszystkie miejsca. Nakładki nad grą wtedy koła nie rysują, ale ich własne ustawienia zostają nietknięte, więc powrót do „W nakładkach” przywraca dokładnie to, co było. Ściąga w panelu pokazuje koło zawsze, bo to na niej je ustawiasz.</li>\n        </ul>\n      <h4>Wyjścia awaryjne i bramki</h4>\n      <ul>\n        <li><b>Środek to wyjście awaryjne:</b> puszczenie przycisku, kiedy kapsel stoi prosto, nie wysyła nic. Otwarcie koła „na próbę” jest więc bezpieczne.</li>\n        <li><b>Bramka jest ta sama:</b> akcja idzie do Windows tylko wtedy, gdy kapsel jest <b>uzbrojony</b> — wstrzymany kapsel pokaże koło, ale niczego nie wyśle.</li>\n        <li>⚠️ <b>Ten sam przycisk może mieć wyzwalacz.</b> Jeśli masz regułę na przycisk kapsla, przy każdym otwarciu koła ona też zadziała — koło niczego nie przechwytuje. To celowe (czasem właśnie tego się chce), ale jeśli przeszkadza, wyłącz tę regułę albo przepnij ją na inny warunek.</li>\n        <li>Wycinek bez akcji i bez makra tylko się podświetla. Akcja warstwy (<code>layer:…</code>) wpisana jako pojedyncza akcja wycinka jest odrzucana przy zapisie, ale <b>w kroku makra działa</b>.</li>\n      </ul>"},
  {id:"mysz",panel:"tab-mysz",title:"Jak zamienić kapsel w mysz?",html:"<h4>Co robi ten moduł?</h4>\n      Zamienia ruch kapsla w kursor Windows: obracasz albo pochylasz kapsel, a wskaźnik jedzie po ekranie. Okno podglądu po lewej pokazuje na żywo, dokąd karta prowadzi kursor. Kapsel ma jeden tryb ruchu naraz, więc włączenie myszy odbiera ruch zakładce <b>Kontroler</b>, a włączenie ruchu tam gasi mysz tutaj.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 186\" role=\"img\" aria-label=\"Dwa znaczenia ruchu kapsla: prędkość, przy której wychylenie mówi, jak szybko jedzie kursor, oraz położenie, przy którym kapsel wskazuje punkt jak pilot.\">\n          <rect class=\"g-box\" x=\"8\" y=\"26\" width=\"306\" height=\"132\"/>\n          <text class=\"g-txt\" x=\"161\" y=\"54\" data-i18n-en=\"Speed\">Prędkość</text>\n          <text class=\"g-sub\" x=\"161\" y=\"78\" data-i18n-en=\"the lean says HOW FAST\">wychylenie mówi, JAK SZYBKO</text>\n          <text class=\"g-sub\" x=\"161\" y=\"96\" data-i18n-en=\"the cursor travels while you hold it\">kursor jedzie, póki trzymasz</text>\n          <text class=\"g-sub\" x=\"161\" y=\"128\" data-i18n-en=\"like a stick on a gamepad\">jak gałka w padzie</text>\n          <rect class=\"g-box\" x=\"326\" y=\"26\" width=\"306\" height=\"132\"/>\n          <text class=\"g-txt\" x=\"479\" y=\"54\" data-i18n-en=\"Position (pointing)\">Położenie (wskazywanie)</text>\n          <text class=\"g-sub\" x=\"479\" y=\"78\" data-i18n-en=\"the capsule points at a SPOT\">kapsel wskazuje PUNKT</text>\n          <text class=\"g-sub\" x=\"479\" y=\"96\" data-i18n-en=\"straight ahead = the middle of the area\">na wprost = środek obszaru</text>\n          <text class=\"g-sub\" x=\"479\" y=\"128\" data-i18n-en=\"like a remote control\">jak pilot do telewizora</text>\n          <rect class=\"g-box g-cicho\" x=\"372\" y=\"138\" width=\"214\" height=\"20\"/>\n          <text class=\"g-sub\" x=\"479\" y=\"152\" data-i18n-en=\"needs the 3D filter as its source\">wymaga źródła Filtr 3D</text>\n          <text class=\"g-sub\" x=\"320\" y=\"176\" data-i18n-en=\"“The capsule's movement is…”\">Ruch kapsla to…</text>\n        </svg>\n        <figcaption data-i18n-en=\"The first choice on this card. Every other dial — sensitivity, dead zone, smoothing — tunes whatever you pick here.\">Pierwszy wybór na tej karcie. Reszta pokręteł — czułość, martwa strefa, wygładzanie — dostraja to, co tu wybierzesz.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Ustaw kapsel tak, jak będzie noszony, i kliknij <b>Wyśrodkuj kapsel</b>. To położenie staje się środkiem ruchu, więc znika dryf i grawitacja. W zwijaku „Zaawansowane”, w części „Dostrajanie ruchu”, włączysz też <b>Auto-środkowanie przy bezruchu</b>, a dryf będzie zerowany za Ciebie.</li>\n        <li>Wybierz, jak kapsel prowadzi kursor: <b>Prędkość</b> albo <b>Położenie (wskazywanie)</b>. Źródło ruchu zmienisz w zwijaku „Zaawansowane”.</li>\n        <li>Ruszaj kapslem i patrz na podgląd po lewej. W zwijaku „Czułość i kierunek” przesuwaj suwak <b>Ile trzeba wychylić do pełnej prędkości</b> i martwą strefę, aż ruch będzie wygodny.</li>\n        <li>Przestaw włącznik w nagłówku modułu na <b>Wł.</b> albo kliknij <b>Włącz Mysz</b> w linii nad kartą. Dopiero wtedy kursor Windows naprawdę słucha kapsla, a linia mówi, jakim skrótem go zatrzymasz.</li>\n      </ul>\n      <h4>Możliwości — co można tu zrobić</h4>\n      <ul>\n        <li>Na wierzchu karty stoją <b>Wyśrodkuj kapsel</b> i wybór, jak kapsel prowadzi kursor. Resztę trzymają zwijaki z podsumowaniem w nagłówku: „Czułość i kierunek”, „Czas i rodzaj kliknięcia” pod „Klik bez klikania”, „Przycisk kapsla klika” i „Obszar kursora”. Na samym dole jest „Zaawansowane” z dostrajaniem ruchu.</li>\n        <li><b>Źródło ruchu</b> (w „Zaawansowane”) decyduje, co porusza kursorem. <b>📈 Oś (prędkość z żyro)</b>: obracasz kapsel, kursor płynie. <b>🧭 Filtr 3D (pochylenie → ruch kursora)</b>: kąt pochylenia jest prędkością.</li>\n        <li><b>Ruch kapsla to</b> pierwszy wybór tej karty. <b>Prędkość</b>: wychylenie mówi, jak szybko kursor jedzie. <b>Położenie (wskazywanie)</b>: kapsel wskazuje punkt jak pilot — trzymany na wprost celuje w środek obszaru, a pole <b>brzeg obszaru przy</b> ustala, ile trzeba wychylić, żeby dojeżdżać do krawędzi. Wskazywanie wymaga źródła <b>🧭 Filtr 3D (pochylenie → ruch kursora)</b>, bo tylko ono zna kąt.</li>\n        <li><b>Obszar kursora</b> mówi, dokąd kapsel może zaprowadzić kursor: cały pulpit, <b>📺 Wybrany monitor</b>, <b>🎯 Monitor, na którym stoi kursor</b> albo własny prostokąt. Na mapce klikasz ten ekran, na którym pracujesz. Przełącznik <b>Pomiń pasek zadań</b> trzyma kursor nad oknami, a pole <b>Margines</b> odsuwa go od krawędzi ekranu. Ogrodzenie dotyczy tylko kapsla — zwykłą myszką dalej pojedziesz, gdzie chcesz.</li>\n        <li>Pudełko <b>Klik bez klikania</b> zdejmuje z Ciebie naciskanie przycisku: zatrzymaj kursor na chwilę w jednym miejscu, a aplikacja kliknie za Ciebie. Pomyślana jest przede wszystkim jako ułatwienie dostępności, bo prowadzenie kursora i wciśnięcie przycisku to dwie różne sprawności, a przydaje się każdemu, kto ma zajęte ręce. <b>Czas zatrzymania</b> mówi, jak długo kursor ma stać, <b>Promień spokoju</b> wybacza drżenie ręki, a <b>Rodzaj kliknięcia</b> wybiera przycisk: lewy, prawy, środkowy albo dwuklik. Klika raz i czeka, aż ruszysz kursorem poza ten promień, więc kursor odstawiony na przycisku nie klika go w kółko. Działa w obu trybach ruchu, i przy prędkości, i przy wskazywaniu, a pierścień wokół kursora na podglądzie po lewej pokazuje, ile zostało do kliknięcia.</li>\n        <li>Pudełko <b>Przycisk kapsla klika</b> daje cztery gesty na jednym przycisku: puknięcie to lewy, dwa szybkie puknięcia to dwuklik, trzy to środkowy, a przytrzymanie to prawy. Ustawiasz dwie liczby: okno puknięć i czas przytrzymania. Pojedynczy klik z natury spóźnia się o to okno, bo aplikacja czeka, czy nie przyjdzie drugie puknięcie — tak samo działa dwuklik myszy w każdym systemie. Pod spodem powstają ZWYKŁE reguły w Mapowaniu (nazwane „Puknięcie → lewy przycisk” i tak dalej), więc widać je tam, można je przerobić na inne przyciski i jadą w zestawie razem z resztą. Wyłącznik ich nie kasuje, tylko gasi.</li>\n        <li><b>Które pola zobaczysz, zależy od źródła ruchu.</b> Przy domyślnym <b>🧭 Filtr 3D (pochylenie → ruch kursora)</b> zwijak „Czułość i kierunek” pokazuje suwak <b>Ile trzeba wychylić do pełnej prędkości</b> i <b>Martwa strefa (kąt)</b>, a „Zaawansowane” › „Dostrajanie ruchu” osie filtra, <b>Maks. krok</b>, <b>Krzywa odpowiedzi</b> i <b>Wygładzanie</b> z suwakiem <b>Siła wygładzania</b>. Czułości tu nie ma, bo prędkość liczy się z maksymalnego kroku pomnożonego przez wychylenie.</li>\n        <li>Po przełączeniu na <b>📈 Oś (prędkość z żyro)</b> dochodzą pola, których filtr nie czyta: wybór osi kapsla z martwą strefą w LSB, <b>Czułość X</b>, <b>Czułość Y</b>, <b>Stabilizacja kursora (próg drżenia ręki)</b>, zwijana <b>Akceleracja (dwie czułości: wolno/szybko)</b> oraz zwijana <b>Scroll: kręcenie zamiast ruchu kursora</b>, która zamienia obrót wybranej osi w przewijanie strony.</li>\n        <li>Dwa suwaki o podobnych nazwach robią dwie różne rzeczy. <b>Siła wygładzania</b> uśrednia kolejne próbki, więc kursor jedzie płynniej, ale odrobinę zostaje za ręką. <b>Stabilizacja kursora (próg drżenia ręki)</b> ustawia próg: ruch mniejszy od niego jest tłumiony, większy idzie w całości. Ten drugi widać tylko przy źródle <b>📈 Oś (prędkość z żyro)</b>.</li>\n        <li><b>Położenie (wskazywanie)</b> wymusza źródło <b>🧭 Filtr 3D (pochylenie → ruch kursora)</b>, bo tylko ono zna kąt. Po jego wybraniu źródło przestawia się samo, pozycja <b>📈 Oś (prędkość z żyro)</b> jest zablokowana, a zdanie pod listą mówi o tym wprost — razem z tym, które pola przez to zniknęły.</li>\n        <li><b>Odwróć lewo i prawo</b>, <b>Odwróć górę i dół</b> i <b>Martwa strefa</b> należą do samej myszy. Gałka i krzyżak mają własne, więc strojenie jednego trybu nie psuje pozostałych.</li>\n        <li>Tryb potrafi się przełączać sam. Reguła <b>🔀 Auto-przełączanie trybu wg pozycji (filtr 3D / oś)</b> mieszka na ekranie <b>Kontroler</b> i decyduje, kiedy kapsel jest myszą, a kiedy gałką albo krzyżakiem: kapsel płasko to mysz, postawiony pionowo to gałka. Stoi tam w zwijaku „Zaawansowane” na dole prawej kolumny, widocznym po kliknięciu drążka albo krzyżaka na rysunku pada.</li>\n      </ul>\n      <h4>Dla opiekuna</h4>\n      <ul>\n        <li>Załóż kapsel tak, jak będzie noszony, i kliknij <b>Wyśrodkuj kapsel</b>. Od tego położenia liczy się każdy ruch.</li>\n        <li>Gdy naciśnięcie przycisku jest trudne, włącz <b>Klik bez klikania</b>. Przy drżącej ręce albo głowie podnieś <b>Promień spokoju</b>, żeby drżenie nie przerywało odliczania.</li>\n        <li>Linia nad kartą mówi, czego jeszcze brakuje, a gdy wszystko gra, podaje skrót, którym zatrzymasz kursor.</li>\n      </ul>\n      <h4>💡 Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li>Kursor ucieka sam? Ustaw kapsel tak, jak będzie noszony, i kliknij <b>Wyśrodkuj kapsel</b>.</li>\n        <li>Kursor ucieka na sąsiedni monitor? W zwijaku <b>Obszar kursora</b> ogranicz go do jednego ekranu: <b>📺 Wybrany monitor</b> zostaje na tym, który wskażesz, a <b>🎯 Monitor, na którym stoi kursor</b> idzie za Tobą.</li>\n        <li>Prezentacja albo telewizor z kanapy: włącz <b>Położenie (wskazywanie)</b> i ogranicz obszar do tego jednego ekranu — kapsel staje się wskaźnikiem.</li>\n        <li>Naciśnięcie przycisku sprawia trudność albo ręce są zajęte? Włącz <b>Klik bez klikania</b>: kursor, który przystanie, kliknie sam.</li>\n        <li>Kursor drży? Podnieś <b>Stabilizacja kursora (próg drżenia ręki)</b> lub przełącz <b>Wygładzanie</b> na tryb <b>Adaptacyjne</b>.</li>\n        <li>Ruch w złą stronę? Włącz <b>Odwróć lewo i prawo</b> albo <b>Odwróć górę i dół</b>.</li>\n        <li>Przeglądanie stron i prezentacje lubią mysz ze scrollem na osi obrotu. Do gier wygodniejszy jest ekran <b>Kontroler</b>.</li>\n      </ul>\n      \n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego kapsla: co tu zmienisz, działa od razu i zapisuje się na kapslu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: na kapslu wszystko już działa, w bibliotece jeszcze nie.\n      <h4>Bezpieczeństwo i uwagi</h4>\n      Kursor rusza się <b>tylko gdy Mysz jest włączona, a sterowanie nie jest wstrzymane</b>. Mysz działa niezależnie od Mapowania i MIDI/OSC, a kropka przy module w nawigacji mówi, czy jest włączona: zielona — włączona, szara — wyłączona, bursztynowa — masz niezapisane zmiany. W trybie symulacji i przy starcie z opcją <code>--no-keys</code> nic nie wychodzi do systemu, działa sam podgląd.<br>\n      <small style=\"color:var(--dim)\">💡 Gdy kursor ucieknie pod grą i nie da się trafić w panel, wszystkie wyjścia wyłącza globalny skrót ze <b>Stopu awaryjnego</b>, opisany na ekranie Ustawienia.</small>"},
  {id:"kontroler",panel:"tab-kontroler",title:"Jak zamienić kapsel w kontroler?",html:"<h4>Co robi ten moduł?</h4>\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 150\" role=\"img\" aria-label=\"Kapsel przechylany na dwie strony steruje jednym z trzech wyjść: kursorem myszy, gałką analogową albo krzyżakiem\">\n          <rect class=\"g-box\" x=\"6\" y=\"34\" width=\"150\" height=\"66\"/>\n          <text class=\"g-txt\" x=\"81\" y=\"60\" data-i18n-en=\"The capsule's tilt\">Przechył kapsla</text>\n          <text class=\"g-sub\" x=\"81\" y=\"78\" data-i18n-en=\"forward/back and sideways\">w przód/tył i w boki</text>\n          <text class=\"g-sub\" x=\"81\" y=\"24\" data-i18n-en=\"one movement\">jeden ruch</text>\n          <path class=\"g-strzalka\" d=\"M156 67 H196\"/><path class=\"g-grot\" d=\"M196 61 L206 67 L196 73 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"214\" y=\"12\" width=\"196\" height=\"38\"/>\n          <text class=\"g-txt\" x=\"312\" y=\"36\" data-i18n-en=\"The mouse pointer\">Kursor myszy</text>\n          <rect class=\"g-box\" x=\"214\" y=\"56\" width=\"196\" height=\"38\"/>\n          <text class=\"g-txt\" x=\"312\" y=\"80\" data-i18n-en=\"The pad's analogue stick\">Gałka analogowa pada</text>\n          <rect class=\"g-box\" x=\"214\" y=\"100\" width=\"196\" height=\"38\"/>\n          <text class=\"g-txt\" x=\"312\" y=\"124\" data-i18n-en=\"The pad's d-pad\">Krzyżak pada</text>\n          <path class=\"g-strzalka\" d=\"M410 31 H450\"/><path class=\"g-grot\" d=\"M450 25 L460 31 L450 37 Z\"/>\n          <path class=\"g-strzalka\" d=\"M410 75 H450\"/><path class=\"g-grot\" d=\"M450 69 L460 75 L450 81 Z\"/>\n          <path class=\"g-strzalka\" d=\"M410 119 H450\"/><path class=\"g-grot\" d=\"M450 113 L460 119 L450 125 Z\"/>\n          <rect class=\"g-box g-cicho\" x=\"468\" y=\"34\" width=\"166\" height=\"66\"/>\n          <text class=\"g-txt\" x=\"551\" y=\"60\" data-i18n-en=\"Windows and the game\">Windows i gra</text>\n          <text class=\"g-sub\" x=\"551\" y=\"78\" data-i18n-en=\"see a mouse or an Xbox pad\">widzą mysz albo pada Xbox</text>\n        </svg>\n        <figcaption data-i18n-en=\"One capsule drives ONE of these at a time — picking the mode is picking what it is.\">Jeden kapsel prowadzi w danej chwili JEDNO z tych wyjść — wybór trybu jest wyborem, czym ma być.</figcaption>\n      </figure>\n      Zbiera wszystko o wirtualnych kontrolerach: padzie Xbox 360 albo DualShock 4, którego RibbitFlip podaje Windowsowi, oraz kontrolerze Wii, którego czyta emulator. U góry stoi sekcja <b>Kontrolery</b>: jedna ramka na każdy pad, który zobaczy gra, a w ramce kapsle, które na nim grają. Niżej stoi nagłówek z numerem i nazwą oglądanego kontrolera, a pod nim po lewej rysunek pada, czyli mapa: obwódka w kolorze kapsla mówi, że dana część jest używana i przez który kapsel, zapalona oznacza wciśnięcie teraz, a czerwona, że nic nie wyszło z aplikacji. Po prawej stoją ustawienia części, którą klikniesz na rysunku. Kapsel ma jeden tryb ruchu naraz, więc włączenie ruchu tutaj gasi ruch w zakładce <b>Mysz</b>. Tak samo w drugą stronę.\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Zainstaluj darmowy sterownik <b>ViGEmBus</b>, bo bez niego Windows nie zobaczy pada. Gdy go brakuje, mówi to linia gotowości nad kartą, a komunikat pod nią ma odnośnik do pobrania i przycisk „Sprawdź ponownie”.</li>\n        <li>Sprawdź w sekcji <b>Kontrolery</b>, na którym padzie gra Twój kapsel. Numer stoi na środku rysunku, w miejscu logo, i to jego zobaczy gra.</li>\n        <li>Kliknij na rysunku drążek, krzyżak albo touchpad. Prawa kolumna stanie się tą częścią: ruszaj kapslem i patrz na podgląd pod rysunkiem. Pierwsza linia mówi, czy ruch idzie właśnie tutaj, a przełącznik obok przestawia to jednym kliknięciem. Wyłączenie parkuje sam ruch: moduł zostaje włączony, więc mapowania przycisków pada dalej wychodzą.</li>\n        <li>W tej samej kolumnie, pod przełącznikiem, stoi <b>Wyśrodkuj kapsel</b>: ustaw kapsel tak, jak będzie trzymany, i kliknij. To położenie staje się środkiem ruchu, więc znika dryf i grawitacja. W zwijaku „Czułość i martwa strefa” zaznacz też <b>Auto-środkowanie żyro przy bezruchu</b>, a dryf będzie zerowany za Ciebie.</li>\n        <li>Przestaw włącznik w nagłówku modułu na <b>Wł.</b>. Dopiero wtedy ruch naprawdę porusza padem, a napis <b>⚠ NA ŻYWO</b> przypomina, że wyjście jest aktywne.</li>\n        <li>Ten sam przełącznik odbiera ruch: wyłączony zamyka wyjście, a ustawienia części zostają nietknięte. Zdanie obok mówi jeszcze trzecią rzecz, której dwupozycyjny przełącznik powiedzieć nie umie — że część jest wycelowana, ale cicha, bo grupa ruchu jest wyłączona.</li>\n        <li>Przycisk dokładasz jednym kliknięciem. Przycisk, którego jeszcze nic nie wciska, ma pod kursorem zielony plusik, a klik od razu otwiera nowe mapowanie wycelowane właśnie w niego; przycisk z jednym mapowaniem otwiera je do edycji, a z kilkoma pokazuje ich listę do wyboru. Wszystkie razem stoją w spisie <b>Mapowania pada</b>, widocznym, gdy żadna część nie jest wybrana. Ta lista wychodzi razem z ruchem: włącznik w nagłówku karty otwiera i drążek, i przyciski.</li>\n      </ul>\n      <h4>Możliwości — co można tu zrobić</h4>\n      <ul>\n        <li><b>Kontrolery</b>: ramka to kontroler, chip to kapsel. Nowy zakładasz kafelkiem <b>Utwórz wirtualny kontroler</b> — stoi pusty, dopóki nie przypniesz do niego kapsla listą wyboru przy chipie albo przeciągnięciem chipa na tę ramkę. Kilka kapsli w jednej ramce znaczy jeden gracz obiema rękami: wciskają wtedy jeden pad, ramka dostaje dopisek <b>wspólny</b>, a rysunek jeden numer. Osobne ramki to osobni gracze. Ikonka ✎ nadaje kontrolerowi nazwę, a ✕ go usuwa i przenosi jego kapsle na inny; przy jedynym kontrolerze ✕ jest wygaszona, bo jeden musi zostać — kapsel odpinasz wtedy ✕ na jego chipie, a ląduje na tacce nad ramkami. Windows pokazuje grze najwyżej cztery kontrolery i tyle da się utworzyć. Każdy wybór zapisuje się od razu, także dla kapsla, którego akurat nie edytujesz. Typ pada wybierasz przy tworzeniu i zmieniasz potem na ramce: Xbox 360 widzi niemal każda gra, a DualShock 4 bywa jedynym, którego zobaczy tytuł pomijający pady Xboxa. Zmiana typu nie rusza mapowań, bo pad:a to na DualShocku po prostu krzyżyk. Trzeci typ to <b>Wii (emulator)</b> i wychodzi zupełnie inną drogą: nie przez sterownik, tylko protokołem DSU na 127.0.0.1:26760. Windows go NIE widzi, więc zwykła gra ze Steama nigdy go nie zobaczy, choćbyś ustawił wszystko poprawnie. Odbierają go emulatory: Dolphin (Wii, GameCube), Cemu (Wii U), Citra, yuzu, Ryujinx, PPSSPP. Za to nie wymaga żadnego sterownika i jako jedyny niesie prawdziwy ruch, czyli żyroskop i akcelerometr kapsla. Adres, stan podłączenia, port i instrukcję krok po kroku masz na samym kafelku — także wtedy, gdy port jest zajęty i serwer nie wystartował. Mapowania działają na nim tak samo jak na padzie, a przy dwóch kapslach na jednym kontrolerze Wii pierwszy wnosi ruch, a drugi przyciski.</li>\n        <li><b>Legenda pod rysunkiem</b> mówi, co który kapsel wnosi: drążek, krzyżak albo liczbę mapowań przycisków — w tym samym kolorze, który noszą obwódki na rysunku. Kliknięcie wiersza przełącza edycję na tamten kapsel, to samo robi chip w sekcji Kontrolery.</li>\n        <li>Ustawienia klikniętej części stoją w dwóch zwijakach. „Czułość i martwa strefa” ma wyjście, odwracanie osi, martwe strefy, czułość i auto-środkowanie. „Zaawansowane” na dole kolumny ma źródło ruchu, osie, krzywą odpowiedzi, pełne wychylenie i auto-przełączanie trybu.</li>\n        <li><b>Drążek</b> ma w polu <b>Wyjście</b> trzy drogi: <b>🎮 Drążek analogowy (kontroler)</b> to prawdziwy pad i wymaga sterownika ViGEmBus, <b>⌨ Klawiatura WSAD (skosy = combo)</b> działa bez niego, a <b>🖐 Palec na touchpadzie</b> prowadzi palec po panelu DualShocka — pochylenie znaczy wtedy miejsce na szkle, a martwa strefa znaczy, że palec się z niego podnosi. Powierzchnię czyta niewiele programów: Steam Input i emulatory mówiące DS4/DSU; zwykła gra zobaczy samo kliknięcie panelu. Który to drążek, lewy czy prawy, decyduje klik na rysunku pada, a nagłówek panelu to powtarza. Dostrajasz jeszcze <b>Martwa strefa wewn.</b> oraz <b>Krzywa odpowiedzi (expo)</b>, a przy wyjściu klawiaturowym <b>Próg WSAD</b> i własne klawisze kierunków. Suwak <b>Przyspieszenie wejścia</b> mówi, jak szybko drążek dobiega do wychylenia, które zadajesz kapslem: 0% to płynny rozbieg, 100% to natychmiast. <b>Strefa rozruchu (anti-deadzone)</b> robi rzecz odwrotną do martwej strefy — przeskakuje tę, którą ma sama gra, więc postać rusza od pierwszego pochylenia zamiast dopiero po chwili. <b>Czułość osi X i Y</b> mnoży wychylenie każdej osi osobno: 1,00 zostawia drążek takim, jaki był, a mniej znaczy, że trzeba pochylić kapsel dalej i że oś nie dochodzi do końca. Tak ustawia się celowanie — kamera skręca na boki szybko, a w górę i w dół idzie delikatnie. Skrajne 0,00 zdejmuje oś z drążka: przy zerze na osi Y drążek jeździ tylko na boki, a pion zostaje nieruchomy. Zdanie pod suwakami mówi wtedy wprost, która oś stoi.</li>\n        <li><b>Krzyżak</b> skacze pochyleniem do kierunków ↑↓←→. Pole <b>Wyjście</b> daje dwie możliwości: <b>⌨ Klawiatura</b>, gdzie klikasz przycisk kierunku i naciskasz własny klawisz, albo <b>🎮 Kontroler (D-pad)</b>. Pole <b>Klawisze naraz</b> decyduje, czy na przekątnej lecą dwa klawisze, czy zawsze jeden, a <b>Pełne wychylenie</b> i <b>Martwa strefa</b> działają jak w gałce: w środku cisza, za martwą strefą kierunek się załącza. Podgląd ze strefami stoi pod rysunkiem pada.</li>\n        <li>Gdy część napędza inny kapsel niż ten, którego ustawienia oglądasz, kolumna mówi to wprost i daje przycisk <b>Przełącz na: …</b> — ustawienia zawsze pokazują liczby tego kapsla, do którego należą.</li>\n        <li><b>🔀 Auto-przełączanie trybu wg pozycji (filtr 3D / oś)</b> ustawia warunek, na przykład <code>pochylenie &gt; 60</code>, po którym tryb przełącza się sam: kapsel płasko to mysz, postawiony pionowo to gałka. Stoi w zwijaku „Zaawansowane” na dole prawej kolumny, który pojawia się dopiero po kliknięciu drążka albo krzyżaka na rysunku pada, bo dotyczy trybu ruchu, a nie zwykłego przycisku. Reguła obejmuje też ekran <b>Mysz</b>, bo tryb ruchu jest jeden na kapsel.</li>\n        <li><b>Mapowania pada</b> to reguły, których akcją jest przycisk pada (<code>pad:a</code>, <code>pad:rt</code> i dalsze): A/B/X/Y, LB/RB, spusty LT/RT, krzyżak, Start, Back, klik drążkiem i kliknięcie touchpada, którego pad Xboxa nie ma i powie to wprost, zamiast wcisnąć nic. Edytor otwiera się w prawej kolumnie, obok rysunku, na którym od razu widać wciskany przycisk. Mapowania pozostałych kapsli z tego pada stoją niżej, z nazwą kapsla przy każdym.</li>\n        <li><b>Odwróć X</b>, <b>Odwróć Y</b> i <b>Martwa strefa</b> są zapamiętane osobno dla gałki i osobno dla krzyżaka, więc strojenie jednego trybu nie rusza drugiego.</li>\n      </ul>\n      <h4>Czym różnią się od ekranu Mapowanie?</h4>\n      Tylko akcją. To te same wyzwalacze i ten sam edytor: reguła, której akcją jest przycisk pada, pokazuje się tutaj, a reguła z klawiszem, myszą albo makrem zostaje w <b>Mapowaniu</b>. Wychodzą jednak innym włącznikiem: przyciski pada słuchają modułu <b>Kontroler</b> (włącznik w nagłówku karty), a klawisze i mysz grupy <b>Mapowanie</b> — każda ma własną zieloną kropkę. W pliku zestawu jadą razem z resztą reguł, w części <b>Wyzwalacze (Mapowanie)</b>, i preset wyzwalaczy zabiera je ze sobą.\n      <h4>💡 Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li>Gry retro wolą <b>Krzyżak</b> ze skosami, gry 3D <b>Drążek</b>, a kursor i prezentacje ekran <b>Mysz</b>.</li>\n        <li>Nie chcesz instalować sterownika? Kliknij drążek na rysunku i wybierz wyjście <b>⌨ Klawiatura WSAD (skosy = combo)</b>, a gra dostanie klawisze zamiast drążka.</li>\n        <li>Dwa kapsle i jeden gracz: wybierz przy drugim kapslu ten sam kontroler co przy pierwszym i sprawdź, czy ramka ma dopisek <b>wspólny</b>. Gra widzi wtedy jednego gracza, więc lewa ręka może prowadzić drążkiem, a prawa skakać spustem. Gotowy punkt wyjścia dostajesz razem z aplikacją, a nie w Bibliotece tego modułu: w zakładce <b>Zestawy</b>, wśród wbudowanych z pigułką „w aplikacji”, stoi <b>Pad na jeden kapsel (start)</b>, a obok niego <b>Pad na dwa kapsle (start)</b>.</li>\n        <li>Postać dryfuje w bezruchu? Kliknij <b>Wyśrodkuj kapsel</b> i podnieś <b>Martwa strefa</b>.</li>\n        <li>Ruch działa, a przycisk nie? Sprawdź, czy kapsel jest przypięty do kontrolera i czy wyjścia są uzbrojone. Linia gotowości pod nagłówkiem modułu mówi, co blokuje.</li>\n      </ul>\n      \n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego kapsla: co tu zmienisz, działa od razu i zapisuje się na kapslu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: na kapslu wszystko już działa, w bibliotece jeszcze nie.\n      <h4>Bezpieczeństwo i uwagi</h4>\n      Pad rusza się i przyciski wychodzą <b>tylko gdy włącznik w nagłówku modułu jest na Wł.</b>; grupa <b>Mapowanie</b> ich nie dotyczy. Zielona kropka na zakładce mówi, że wyjście jest otwarte. W trybie symulacji i przy starcie z opcją <code>--no-keys</code> nic nie wychodzi do systemu, działa sam podgląd.<br>\n      <small style=\"color:var(--dim)\">🎮 Pełny pad Xbox, czyli drążek analogowy i krzyżak ze skosami, wymaga darmowego sterownika <b>ViGEmBus</b>. Gdy go brakuje, linia gotowości nad kartą daje odnośnik do pobrania, a wspomina o nim też README. Bez sterownika gałka jest tylko podglądem, krzyżak wysyła klawisze, a mapowania przycisków nie mają czym wyjść.</small>"},
  {id:"midi",panel:"tab-midi",title:"Jak grać MIDI ruchem kapsla?",html:"<h4>Do czego służy ten moduł?</h4>\n      Zamienia ruch kapsla w sygnał MIDI — pochylasz lub obracasz kapsel, a do DAW (Ableton, Reaper, FL Studio) czy wizuali (Resolume) płynie strumień komunikatów jak z fizycznego kontrolera. Każde mapowanie to jedna reguła „ruch → cel MIDI”, a pasek pod nim pokazuje wartość na żywo. Moduł ma własny przełącznik Wył./Wł. w pasku modułu, na samej górze ekranu, i działa niezależnie od modułów OSC, Mapowanie, Mysz i Kontroler.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 110\" role=\"img\" aria-label=\"Droga sygnału MIDI: kapsel, mapowanie ruchu na cel MIDI, wirtualny port MIDI, program odbierający.\">\n          <rect class=\"g-box\" x=\"8\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"77\" y=\"58\" data-i18n-en=\"The capsule\">Kapsel</text>\n          <text class=\"g-sub\" x=\"77\" y=\"76\" data-i18n-en=\"movement and lean\">ruch i pochylenie</text>\n          <rect class=\"g-box\" x=\"169\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"238\" y=\"58\" data-i18n-en=\"A mapping\">Mapowanie</text>\n          <text class=\"g-sub\" x=\"238\" y=\"76\" data-i18n-en=\"movement → a MIDI target\">ruch → cel MIDI</text>\n          <path class=\"g-strzalka\" d=\"M150 61 H158\"/><path class=\"g-grot\" d=\"M158 56 L166 61 L158 66 Z\"/>\n          <rect class=\"g-box\" x=\"330\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"399\" y=\"58\" data-i18n-en=\"A MIDI port\">Port MIDI</text>\n          <text class=\"g-sub\" x=\"399\" y=\"76\" data-i18n-en=\"loopMIDI\">loopMIDI</text>\n          <path class=\"g-strzalka\" d=\"M311 61 H319\"/><path class=\"g-grot\" d=\"M319 56 L327 61 L319 66 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"491\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"560\" y=\"58\" data-i18n-en=\"DAW / visuals\">DAW / wizuale</text>\n          <text class=\"g-sub\" x=\"560\" y=\"76\" data-i18n-en=\"Ableton, Reaper, Resolume\">Ableton, Reaper, Resolume</text>\n          <path class=\"g-strzalka\" d=\"M472 61 H480\"/><path class=\"g-grot\" d=\"M480 56 L488 61 L480 66 Z\"/>\n          <text class=\"g-sub\" x=\"320\" y=\"112\" data-i18n-en=\"Windows has no MIDI port of its own — the third block has to be created in loopMIDI.\">Windows nie ma własnego portu MIDI — trzeci klocek musi powstać w loopMIDI.</text>\n        </svg>\n        <figcaption data-i18n-en=\"Without a port the stream has no way out. It is the only thing that has to be installed.\">Bez portu strumień nie ma którędy wyjść. To jedyna rzecz, którą trzeba doinstalować.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Windows nie ma wbudowanego wirtualnego portu MIDI — zainstaluj darmowy loopMIDI i utwórz w nim port (np. <code>RibbitFlip</code>).<br>\n          <small style=\"color:var(--dim)\">💡 Pełna instrukcja: zwijak „Jak połączyć z DAW albo wizualami?” w „Zaawansowane” na dole ekranu.</small></li>\n        <li>W zwijaku „Port MIDI i skala” kliknij <b>🔄</b> obok pola <b>Port OUT</b> i wybierz port loopMIDI z listy — status pod spodem zmieni się na <code>● połączony</code>.</li>\n        <li>W DAW / Resolume wybierz ten sam port jako wejście MIDI.</li>\n        <li>Dodaj regułę: kliknij <b>Nowe mapowanie</b>, ustaw źródło <b>Filtr 3D</b> i wielkość <b>Pochylenie</b>, cel <b>CC 7-bit</b>, potem <b>✓ Dodaj mapowanie</b>.</li>\n        <li>Przestaw włącznik modułu na <b>Wł.</b> — stoi w pasku modułu na górze ekranu, a nie w karcie — i rusz kapslem: pasek mapowania jedzie, a DAW odbiera komunikaty.</li>\n      </ul>\n      <h4>Co można tu zrobić</h4>\n      <ul>\n        <li>Cele: <b>CC 7-bit</b> (fader 0–127), <b>CC 14-bit</b> (precyzja bez schodków), <b>Pitch Bend</b> (dwubiegunowy, domyślnie wycentrowany), <b>Aftertouch</b>, <b>Program</b> (zmiana presetu — tylko tryb progowy), <b>🎵 Nuta</b> (ruch gra dźwięki) i <b>📡 OSC</b> (mapowanie przenosi się do zakładki OSC).</li>\n        <li>Tryby: <b>Ciągły</b> — wartość płynie z ruchu; <b>Próg</b> — komunikat pada przy przekroczeniu (np. <code>obrót &gt; 40</code>).</li>\n        <li>Kształt reakcji: <b>Krzywa (easing)</b> z animowanym podglądem ruchu, <b>Wygładzanie (ms)</b>, <b>odwróć kierunek</b>, <b>Min odstęp (ms)</b>.</li>\n        <li>Skala dla celu „Nuta”: pola <b>Tonika</b> i <b>Rodzaj</b> (np. <code>pentatonika moll</code>) — ruch trafia wyłącznie w dźwięki ze skali, fałsz niemożliwy.</li>\n        <li>Nuta w trybie ciągłym przesuwa wysokość po polu <b>Zakres nut (niska–wysoka)</b>; <b>Velocity</b> ustaw na <b>💥 z ruchu</b>, by mocniejszy gest grał głośniej.</li>\n        <li><b>Kanał MIDI (1–16)</b> obowiązuje cały moduł, a pojedyncze mapowanie nadpisze go polem <b>Kanał mapowania (puste = kanał grupy)</b>.</li>\n      </ul>\n      <h4>💡 Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li>Klasyka na start: <b>Pochylenie</b> → <code>CC 1</code> (modulacja), <b>Obrót</b> → głośność; w DAW użyj „MIDI Learn” i po prostu rusz kapslem.</li>\n        <li>Do pitch/roll najnaturalniejszy jest <b>Pitch Bend</b> — zostaw <b>wycentrowane (środek)</b>, a pole <b>Martwa strefa środka (±%)</b> uciszy drobne drgania w spoczynku.</li>\n        <li>Nerwowy sygnał? Podnieś <b>Wygładzanie (ms)</b> albo zmień krzywą — animowany podgląd w edytorze pokazuje charakter ruchu, zanim zapiszesz.</li>\n        <li><b>▷ Test</b> przy mapowaniu i <b>▷ Test wyjścia</b> w edytorze wysyłają pojedynczy komunikat — sprawdzisz trasę do DAW bez machania kapslem.</li>\n      </ul>\n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego kapsla: co tu zmienisz, działa od razu i zapisuje się na kapslu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: na kapslu wszystko już działa, w bibliotece jeszcze nie. Konfiguracja jest jedna i <b>wspólna dla MIDI i OSC</b> — niesie całą listę mapowań razem ze skalą, więc zmiana zrobiona w jednej z tych dwóch zakładek zapala kropkę także w drugiej. Nie wchodzą do niej włączniki modułów, kanał MIDI ani prefiks adresów OSC, a adres domyślny i lista odbiorników OSC są wspólne dla całej aplikacji i też nie są jej częścią.\n      <h4>Bezpieczeństwo i uwagi</h4>\n      <ul>\n        <li>MIDI wychodzi z aplikacji tylko przy włączonym module (przełącznik w pasku modułu; zielona kropka na zakładce). Wyłączenie modułu nie kasuje mapowań. Przy wyłączonym module „▷ Test” i „⏹ MIDI panic” nic nie wysyłają i mówią o tym wprost.</li>\n        <li>Bez loopMIDI jedynym wyjściem bywa „Microsoft GS Wavetable Synth” — usłyszysz dźwięk, ale DAW go nie zobaczy. Karta pokaże wtedy żółte ostrzeżenie z krokami naprawy.</li>\n        <li>Wisząca nuta po zmianie mapowań w trakcie grania? <b>⏹ MIDI panic</b> wysyła „All Notes Off” na wszystkich kanałach.</li>\n        <li>Ta zakładka wysyła tylko MIDI; do TouchOSC / Resolume po UDP służy osobna zakładka <b>📡 OSC</b> z własnym włącznikiem.</li>\n      </ul>"},
  {id:"osc",panel:"tab-osc",title:"Jak wysyłać ruch po OSC?",html:"<h4>Do czego służy moduł OSC?</h4>\n      Wysyła ruch i pochylenie kapsla jako komunikaty <b>OSC po UDP</b> — do TouchOSC, Resolume, TouchDesigner, VRChat czy ESP32. Bez instalowania czegokolwiek: wystarczy adres programu, który nasłuchuje. Grupa działa <b>niezależnie od MIDI</b> — ma własny przełącznik Wył./Wł. w pasku modułu, na samej górze ekranu, obok nazwy kapsla — ale dzieli z MIDI jedną listę mapowań (cel „📡 OSC”).\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 110\" role=\"img\" aria-label=\"Droga komunikatu OSC: kapsel, mapowanie ruchu na adres OSC, pakiet UDP pod wskazany host i port, program odbierający.\">\n          <rect class=\"g-box\" x=\"8\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"77\" y=\"58\" data-i18n-en=\"The capsule\">Kapsel</text>\n          <text class=\"g-sub\" x=\"77\" y=\"76\" data-i18n-en=\"movement and lean\">ruch i pochylenie</text>\n          <rect class=\"g-box\" x=\"169\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"238\" y=\"58\" data-i18n-en=\"A mapping\">Mapowanie</text>\n          <text class=\"g-sub\" x=\"238\" y=\"76\" data-i18n-en=\"movement → /address\">ruch → /adres</text>\n          <path class=\"g-strzalka\" d=\"M150 61 H158\"/><path class=\"g-grot\" d=\"M158 56 L166 61 L158 66 Z\"/>\n          <rect class=\"g-box\" x=\"330\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"399\" y=\"58\" data-i18n-en=\"UDP\">UDP</text>\n          <text class=\"g-sub\" x=\"399\" y=\"76\" data-i18n-en=\"a host and a port\">host i port</text>\n          <path class=\"g-strzalka\" d=\"M311 61 H319\"/><path class=\"g-grot\" d=\"M319 56 L327 61 L319 66 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"491\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"560\" y=\"58\" data-i18n-en=\"The receiver\">Odbiornik</text>\n          <text class=\"g-sub\" x=\"560\" y=\"76\" data-i18n-en=\"TouchOSC, Resolume, VRChat\">TouchOSC, Resolume, VRChat</text>\n          <path class=\"g-strzalka\" d=\"M472 61 H480\"/><path class=\"g-grot\" d=\"M480 56 L488 61 L480 66 Z\"/>\n          <text class=\"g-sub\" x=\"320\" y=\"112\" data-i18n-en=\"Nothing has to be installed — all you need is the address of a program that is listening.\">Nic nie trzeba instalować — wystarczy adres programu, który nasłuchuje.</text>\n        </svg>\n        <figcaption data-i18n-en=\"The same movement can travel to MIDI and to OSC at once: two separate groups sharing one list of mappings.\">Ten sam ruch może jechać jednocześnie do MIDI i do OSC: to dwa osobne moduły z jedną listą mapowań.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>W zwijaku „Cel domyślny i odbiorniki” wpisz w polach <b>Host</b> i <b>Port</b> adres programu, który nasłuchuje: lokalnie <code>127.0.0.1</code> i port, którego ten program pilnuje (fabrycznie <code>9000</code>), albo IP telefonu z TouchOSC w tej samej sieci Wi‑Fi. Zły adres jest odrzucany od razu, z powodem w wierszu — pakiet wysłany w próżnię wygląda dokładnie tak samo jak wyłączony moduł.</li>\n        <li>Kliknij <b>Nowe mapowanie OSC</b>, wybierz źródło (np. <b>Filtr 3D → Pochylenie</b>) i w polu <b>Adres OSC (po prefiksie)</b> wpisz np. <code>/fader1</code> — w sieć pójdą prefiks i adres razem, czyli <code>/ribbitflip/fader1</code>.</li>\n        <li>Przestaw włącznik modułu na <b>Wł.</b>. Stoi w pasku modułu na górze ekranu, a nie w karcie.</li>\n        <li>Rusz kapslem. Pasek przy mapowaniu pokazuje wartość na żywo, a linia pod listą mapowań mówi, co się dzieje: <code>⚠ NA ŻYWO — OSC → 127.0.0.1:9000</code> albo powód, dla którego nic nie wychodzi.</li>\n      </ul>\n      <h4>Co jest wspólne dla całej aplikacji, a co należy do kapsla</h4>\n      <b>Host</b>, <b>Port</b> i lista <b>odbiorników OSC</b> są wspólne dla wszystkich kapsli: opisują maszyny stojące w sieci, a te są jedne, niezależnie od tego, który kapsel trzymasz w ręce. Przy kapslu zostają <b>prefiks adresu</b> i sam <b>przełącznik grupy</b> — dwa kapsle z tym samym zestawem mapowań mają się różnić adresem, a nie grać po sobie w to samo miejsce.\n      <h4>Odbiorniki OSC — kilka maszyn naraz</h4>\n      Jeżeli jeden zestaw steruje więcej niż jedną maszyną, na przykład lampą na ESP32 i tabletem z TouchOSC albo dwoma sterownikami w różnych rogach warsztatu, dodaj je w zwijaku „Cel domyślny i odbiorniki” (mieści się ich szesnaście). Każdy ma własną nazwę, host i port, a w edytorze mapowania pole <b>Odbiornik</b> mówi, do którego z nich to mapowanie leci. Nazwa pojawia się potem w wierszu mapowania i w dzienniku wysyłek, bo przy kilku odbiornikach sam adres przestaje cokolwiek identyfikować. Cel domyślny stoi w tej liście jako pierwszy wiersz i nie da się go usunąć — dzięki temu usunięcie dowolnego odbiornika zawsze ma dokąd przenieść mapowania.\n      <h4>Co można ustawić w mapowaniu</h4>\n      <ul>\n        <li><b>Profil odbiornika</b> to gotowa para (typ argumentu, zakres), jakiej oczekuje maszyna po drugiej stronie: analog 0–1 dla programów AV, cyfrowy ON/OFF, PWM 0–100%, serwo 0–180°, 0–270° i 0–360°, serwo na szerokości impulsu 1000–2000 µs, analog 10-bit 0–1023, DAC 8-bit i 12-bit, albo <b>Własny</b>, w którym typ i zakres wpisujesz ręcznie. Zaznacz <b>własny zakres roboczy</b>, żeby mapowanie pracowało tylko w wycinku możliwości profilu.</li>\n        <li>Tryb <b>Ciągły</b> — wartość płynie razem z ruchem. Tryb <b>Próg</b> — komunikat leci na zboczu, a pole <b>Zachowanie na progu</b> mówi, jak długo: <b>Impuls</b> to jeden komunikat w chwili przekroczenia, <b>Bramka</b> trzyma wartość górną, dopóki próg jest przekroczony, <b>Przełącznik</b> zmienia stan przy każdym zboczu, a <b>Impuls X ms</b> sam wraca do spoczynku po zadanym czasie.</li>\n        <li><b>Wartość przy rozbrojeniu</b> to jeden komunikat na pożegnanie — przy rozbrojeniu, wyłączeniu modułu OSC i rozłączeniu kapsla. Puste znaczy „nie parkuj”. UDP nie ma czego zamknąć, więc bez tego serwo zostaje wykręcone, a lampa zapalona.</li>\n        <li><b>Tempo i niezawodność</b> (tylko w trybie ciągłym): <b>Min odstęp (ms)</b> to górna granica tempa, <b>Limit prędkości (jedn./s)</b> chroni mechanikę („pełny przejazd nie szybciej niż w dwie sekundy”), a <b>Powtarzaj co (ms)</b> jest biciem serca strumienia — bez niego nieruchomy kapsel jest nie do odróżnienia od zerwanego Wi‑Fi.</li>\n        <li>Kształt sygnału: <b>Krzywa (easing)</b> z animowanym podglądem, <b>Wygładzanie (ms)</b> i <b>odwróć kierunek</b>. Linijka pod polami zawsze pokazuje, co dokładnie poleci na drut.</li>\n        <li><b>Prefiks adresu</b> (fabrycznie <code>/ribbitflip</code>) jest doklejany przed adres każdego mapowania OSC.</li>\n        <li>Lista mapowań jest wspólna z MIDI: gdy w edytorze zmienisz cel na „📡 OSC”, wiersz przeniesie się między zakładkami.</li>\n      </ul>\n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego kapsla: co tu zmienisz, działa od razu i zapisuje się na kapslu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: na kapslu wszystko już działa, w bibliotece jeszcze nie. Konfiguracja jest jedna i <b>wspólna dla MIDI i OSC</b> — niesie całą listę mapowań razem ze skalą, więc zmiana zrobiona w jednej z tych dwóch zakładek zapala kropkę także w drugiej. Nie wchodzą do niej włączniki modułów, kanał MIDI ani prefiks adresów OSC, a adres domyślny i lista odbiorników OSC są wspólne dla całej aplikacji i też nie są jej częścią.\n      <h4>Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li><b>TouchOSC na telefonie</b> — w ustawieniach połączenia TouchOSC włącz UDP i sprawdź port nasłuchu; tutaj jako <b>Host</b> wpisz IP telefonu i przepisz ten port. Telefon i komputer muszą być w tej samej sieci Wi‑Fi.</li>\n        <li><b>VRChat</b> — nasłuchuje na porcie <code>9000</code>; parametry avatara mają adresy <code>/avatar/parameters/…</code> — <b>Prefiks adresu</b> ustawiony na <code>/avatar/parameters</code> załatwia sprawę, a adres po prefiksie = nazwa parametru.</li>\n        <li><b>Resolume / TouchDesigner</b> — włącz w programie wejście OSC na tym samym porcie; pełny adres podejrzysz w wierszu mapowania na liście.</li>\n        <li>💡 Zacznij od profilu <b>Analog 0–1</b> — fadery TouchOSC i parametry VRChat oczekują właśnie zakresu 0–1.</li>\n      </ul>\n      <h4>Bezpieczeństwo i uwagi</h4>\n      Nic nie wychodzi w sieć, dopóki moduł jest wyłączony — stan zawsze widać w linii pod listą mapowań (⚠ oznacza NA ŻYWO). OSC nie wysyła klawiszy do Windows i nie wymaga loopMIDI ani sprzętu MIDI — to czysty ruch UDP do podanego hosta. Pakiety lecą dokładnie na adres <b>Host</b>:<b>Port</b>, który wpiszesz — literówka w IP oznacza ciszę po drugiej stronie. Wszystko o profilach, zachowaniach i parkowaniu stoi w zwijaku „Jak działa OSC w RibbitFlipie” w „Zaawansowane” na dole ekranu.<br>\n      <small style=\"color:var(--dim)\">💡 Wyłącznik modułu OSC nie wpływa na MIDI, Mapowanie ani na Mysz i Kontroler — każdy moduł ma własny włącznik i mogą działać równocześnie.</small>"},
  {id:"restapi",panel:"tab-restapi",title:"Jak wysyłać HTTP i sterować OBS-em z ruchu?",html:"<h4>Do czego służy ten moduł?</h4>\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 132\" role=\"img\" aria-label=\"Droga od ruchu kapsla przez wyzwalacz i akcję z paczki do usługi w sieci\">\n          <rect class=\"g-box\" x=\"6\" y=\"30\" width=\"132\" height=\"56\"/>\n          <text class=\"g-txt\" x=\"72\" y=\"54\" data-i18n-en=\"Capsule movement\">Ruch kapsla</text>\n          <text class=\"g-sub\" x=\"72\" y=\"72\" data-i18n-en=\"tilt, turn, shake\">przechył, obrót, wstrząs</text>\n          <path class=\"g-strzalka\" d=\"M138 58 H172\"/><path class=\"g-grot\" d=\"M172 52 L182 58 L172 64 Z\"/>\n          <rect class=\"g-box\" x=\"190\" y=\"30\" width=\"132\" height=\"56\"/>\n          <text class=\"g-txt\" x=\"256\" y=\"54\" data-i18n-en=\"The trigger\">Wyzwalacz</text>\n          <text class=\"g-sub\" x=\"256\" y=\"72\" data-i18n-en=\"threshold, time, behaviour\">próg, czas, zachowanie</text>\n          <path class=\"g-strzalka\" d=\"M322 58 H356\"/><path class=\"g-grot\" d=\"M356 52 L366 58 L356 64 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"374\" y=\"30\" width=\"132\" height=\"56\"/>\n          <text class=\"g-txt\" x=\"440\" y=\"54\" data-i18n-en=\"An action from the pack\">Akcja z paczki</text>\n          <text class=\"g-sub\" x=\"440\" y=\"72\" data-i18n-en=\"an HTTP request\">żądanie HTTP</text>\n          <path class=\"g-strzalka\" d=\"M506 58 H540\"/><path class=\"g-grot\" d=\"M540 52 L550 58 L540 64 Z\"/>\n          <rect class=\"g-box g-cicho\" x=\"558\" y=\"30\" width=\"76\" height=\"56\"/>\n          <text class=\"g-txt\" x=\"596\" y=\"54\" data-i18n-en=\"The service\">Usługa</text>\n          <text class=\"g-sub\" x=\"596\" y=\"72\" data-i18n-en=\"OBS, a lamp\">OBS, lampa</text>\n          <text class=\"g-sub\" x=\"320\" y=\"120\" data-i18n-en=\"Passwords and tokens stay in the safe on your disk — a pack you send carries none of them.\">Hasła i tokeny zostają w sejfie na Twoim dysku — paczka do wysłania ich nie niesie.</text>\n        </svg>\n      </figure>\n      Wysyła wiadomości HTTP do innych aplikacji — webhooki, smart-home i Twoje własne serwery — oraz steruje OBS Studio. Ręcznie przyciskiem albo automatycznie z ruchu kapsla (np. <b>puknij kapsel → powiadomienie na telefonie</b>). Na wierzchu stoi karta „Aplikacje i usługi” (akcje i wyzwalacze), a w niej zwijaki „OBS Studio” (połączenie z OBS-em) i „Zmienne” (wartości pod <code>{{var.…}}</code>). „Sejf poświadczeń” (tokeny i hasła) oraz „Dziennik wysyłek” są w „Zaawansowane” na dole ekranu.\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Klikasz <b>Wybierz szablon</b> w karcie <b>Aplikacje i usługi</b> i wybierasz usługę. Powstaje aplikacja z gotowymi akcjami i sekcją <b>📖 Instrukcja konfiguracji</b> — tam krok po kroku stoi, gdzie kliknąć u dostawcy.<br>\n          <small style=\"color:var(--dim)\">💡 <span data-packn></span> gotowych szablonów, m.in. OBS Studio, Twitch, Discord, Slack, ntfy.sh, n8n, IFTTT, Home Assistant, Philips Hue, WLED, Telegram.</small></li>\n        <li>Sekrety do sejfu: <b>Ustaw hasło sejfu</b>, potem <b>Dodaj poświadczenie</b> (token, login i hasło, własny nagłówek albo parametr w adresie). W akcji wstawiasz <code>{{secret.…}}</code> — nigdy jawnego tokenu.</li>\n        <li>W zwijaku „Zmienne” uzupełniasz wartości, o które prosi szablon (np. identyfikator webhooka), a akcje czytają je tokenem <code>{{var.nazwa}}</code>.</li>\n        <li>Próba: <b>▶ Wyślij</b> przy akcji albo <b>Test połączenia</b> w pod-zakładce <b>Ustawienia i test</b>. Wynik ląduje w karcie <b>Dziennik wysyłek</b> w „Zaawansowane”.</li>\n        <li>Automat — trzy kroki, w tej kolejności, i tak samo wypisane na samych pod-zakładkach: <b>Akcje</b> (co wysłać) › <b>Wyzwalacze</b> (kiedy wysłać) › <b>Ustawienia i test</b> (czy dochodzi). W pod-zakładce <b>Wyzwalacze</b> klikasz <b>Dodaj wyzwalacz</b>, wybierasz <b>regułę z Mapowania</b> albo <b>własny próg ruchu</b>, a potem naciskasz <b>▶ Testuj</b> w wierszu wyzwalacza — to wysyła akcję tą samą drogą, którą pójdzie ona z ruchu, więc zielony wynik naprawdę coś znaczy. Na koniec włącz <b>włącznik modułu</b> u góry ekranu.</li>\n        <li>Pod listą wyzwalaczy stoi rachunek <b>Żeby wyzwalacz naprawdę wysłał</b> — wypisuje wszystko, czego jeszcze brakuje, łącznie z tym, że w symulacji żądania nie wychodzą, dopóki nie potwierdzisz wyjść. Bez niego „nic się nie dzieje” wygląda tak samo przy literówce w adresie, przy wyłączonym module i przy dobrze ustawionym wyzwalaczu.</li>\n      </ul>\n      <h4>Co można tu zrobić?</h4>\n      <ul>\n        <li><b>Dodaj własne API</b> — własna aplikacja od zera: <b>Adres bazowy</b>, <b>Poświadczenie</b>, <b>Limit czasu (ms)</b> i wspólne nagłówki znajdziesz w pod-zakładce <b>Ustawienia i test</b>.</li>\n        <li><b>Nowa akcja</b> — jedna gotowa wiadomość: metoda, ścieżka, nagłówki i treść. <b>👁 Podgląd</b> pokazuje, co naprawdę poleci (sekrety zamaskowane jako ••••), a <b>▶ Wyślij</b> wysyła od razu.</li>\n        <li>W treści akcji działają placeholdery: <code>{{pose.tilt}}</code>, <code>{{ch0}}</code>…<code>{{ch5}}</code>, <code>{{var.nazwa}}</code>, <code>{{secret.…}}</code> — wartości podstawiają się dopiero przy wysyłce.</li>\n        <li><b>Wymiana</b> — całą aplikacją dzielisz się jednym plikiem JSON: kreator ułoży post na forum #zestawy, „Weź paczkę od kogoś” wczyta cudzą (plik z dysku albo odnośnik), a „Pobierz plik .json” zapisze Twoją na dysk. Paczka niesie wywołania HTTP <b>razem z ruchami</b>, które je odpalają (np. „przechył w bok &gt; 35° → następny utwór, nie częściej niż co 800 ms”). Paczka nigdy nie niesie tokenów ani haseł — te zostają w sejfie, a osoba importująca wpisuje własne. Nie jadą też rzeczy lokalne: numer kapsla i wskazana reguła z Mapowania, bo u kogoś innego nic nie znaczą. Ruch, który reagował na konkretną regułę autora, przyjeżdża wyłączony; tak samo ruch podpięty pod akcję, którą podgląd importu oznaczył ostrzeżeniem.</li>\n      </ul>\n      <h4>🎬 OBS Studio</h4>\n      <ul>\n        <li>Zwijak „OBS Studio” w karcie aplikacji trzyma jedno połączenie z OBS-em przez obs-websocket. To nie jest HTTP, więc nie ma tam ani adresu bazowego, ani nagłówków.</li>\n        <li>W OBS włącz serwer: Narzędzia → Ustawienia serwera WebSocket. Hasło stamtąd wklej do sejfu jako poświadczenie „Hasło OBS (WebSocket)”, wybierz je w karcie i kliknij „Połącz”.</li>\n        <li>Do OBS-a nie jedzie samo hasło, tylko wyliczony z niego podpis. Samo połączenie trzyma serwer RibbitFlipa, bo przeglądarce zabrania tego polityka bezpieczeństwa panelu.</li>\n        <li>Akcje bierzesz z szablonu „OBS Studio”: przełącz scenę, nagrywanie, powtórka, transmisja, wyciszenie mikrofonu. Zamiast metody i ścieżki mają pole „Żądanie OBS” i dane w JSON.</li>\n        <li>Nic nie łączy się samo po restarcie OBS-a albo aplikacji — pigułka w karcie mówi, jak jest.</li>\n      </ul>\n      <h4>Wskazówki</h4>\n      <ul>\n        <li>💡 Streamujesz? Szablon „Twitch” robi klip z ostatnich sekund transmisji albo stawia na niej znacznik, a „OBS Studio” przełącza scenę bez dotykania klawiatury.</li>\n        <li>💡 Na start bez żadnego konta: szablon ntfy.sh wysyła push na telefon bez rejestracji, a „Losowy żart / demo bez konta” działa całkiem bez poświadczeń.</li>\n        <li>💡 <b>Dziennik wysyłek</b> jest trwały — zapisuje się na dysku (<code>Settings/ribbitflip_rest_log.jsonl</code>) z rotacją, a sekrety są w nim zawsze zamaskowane. <b>Folder</b> otwiera katalog i podświetla w nim sam plik dziennika (a gdyby okno nie weszło na wierzch, aplikacja powie o tym i poda ścieżkę do skopiowania), <b>Eksportuj</b> pobiera cały plik JSONL, a <b>Wyczyść</b> czyści widok oraz plik na dysku — pyta o potwierdzenie, bo tego nie da się cofnąć.</li>\n        <li>💡 Sejf zamyka się sam po 15 minutach bezczynności i przy wyjściu z tej zakładki. Wyzwalacze liczy panel, więc karta z panelem musi zostać otwarta. Żeby akcje z hasłem wychodziły w tle, zostaw zaznaczone <b>Trzymaj odblokowane do wysyłki w tle</b>.</li>\n      </ul>\n      <h4>Wyzwalacz: kiedy ma wysłać</h4>\n      <ul>\n        <li><b>Własny próg ruchu</b> ustawia się tymi samymi słowami, co warunek reguły w <b>Mapowaniu</b>: źródło (pochylenie, przechyły, obrót, <b>wirowanie</b>, kanały CH0–CH5), sześć warunków — w tym <b>w zakresie x..y</b> i <b>poza zakresem</b> — <b>|x|</b> („w którąkolwiek stronę”), <b>NIE</b>, suwak progu oraz <b>↧</b>, które wpisuje wartość zmierzoną w tej chwili.</li>\n        <li><b>Zachowanie</b> też nazywa się jak tam: <b>Jednorazowo</b>, <b>Ciągłe</b>, <b>Po odczekaniu</b>, <b>X razy w czasie</b> i <b>Dokładnie N puknięć</b> — to ostatnie rozstrzyga na końcu okna, więc jedno puknięcie i dwuklik mogą stać na dwóch różnych akcjach.</li>\n        <li>Potrzebujesz <b>przycisku kapsla</b>, <b>nagranego gestu</b>, kilku warunków połączonych <b>ORAZ/LUB</b> albo <b>warstw</b>? To wszystko ma reguła w <b>Mapowaniu</b> — zrób ją tam i wskaż tutaj jako źródło <b>Reguła z Mapowania</b>. Oba źródła różnią się jeszcze tym, że własny próg jedzie w paczce akcji do innych osób, a reguła zostaje na Twoim komputerze.</li>\n        <li><b>Nazwa</b> wyzwalacza jest po to, żeby po tygodniu wiedzieć, PO CO on jest; pusta = opis warunku. Wchodzi też do powiadomienia i do akcji jako <code>{{trigger.label}}</code>.</li>\n        <li>Jedna różnica względem Mapowania jest celowa: próg w Usługach ma <b>zapas na drganie</b> (warunek puszcza dopiero po cofnięciu o 5% progu). Tam każde drgnięcie kosztuje naciśnięcie klawisza, tutaj — prawdziwe żądanie sieciowe.</li>\n      </ul>\n      <h4>🔔 Powiadomienie systemowe Windows</h4>\n      Każdy wyzwalacz może przy zadziałaniu wyrzucić dymek Windows z ikony w zasobniku — widać go nawet wtedy, gdy panel jest schowany za grą.\n      <ul>\n        <li><b>Włączasz:</b> w wierszu wyzwalacza rozwijasz listę „🔔 Powiadomienie Windows” i wybierasz „przy zadziałaniu”. Dla własnego progu ruchu jest jeszcze „gdy warunek jest spełniony (i gdy mija)” — dymek dostajesz na początku i na końcu. Wyzwalacz jadący na regule z Mapowania tego drugiego trybu nie ma: stan aktywności ustawiasz przy samej regule, w zakładce Mapowanie.</li>\n        <li><b>Dźwięk:</b> pole „bez dźwięku” jest zaznaczone domyślnie — wyzwalacz potrafi zadziałać kilkadziesiąt razy w sesji, a dzwonek za każdym razem szybko męczy.</li>\n        <li><b>Treść:</b> w polu „Treść powiadomienia” wpisujesz własne zdanie (np. „Wysłano na Discorda”). Puste = nazwa wyzwalacza i akcji.</li>\n        <li><b>Wygląd:</b> dymek ma trzy linie — „RibbitFlip” z żabką, pod spodem „Usługi sieciowe — nazwa akcji”, a najniżej Twój opis albo to, co się właśnie stało.</li>\n        <li><b>Limity:</b> nie częściej niż raz na 3 s dla jednego wyzwalacza; zdławione zadziałania dolicza licznik „(x7)”. Start z flagą --no-tray odbiera ikonę w zasobniku, więc dymka nie będzie — aplikacja powie to od razu przy włączaniu opcji.</li>\n      </ul>\n      \n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego modułu: co tu zmienisz, działa od razu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: w module wszystko już działa, w bibliotece jeszcze nie.\n      <h4>Bezpieczeństwo</h4>\n      <ul>\n        <li>Włącznik u góry ekranu gasi CAŁY moduł: na Off nie wysyła ani wyzwalacz, ani ręczne <b>▶ Wyślij</b> — próba zostawia w dzienniku wpis „nie wysłano — moduł Usługi wyłączony”. Ten włącznik jest wspólny dla wszystkich kapsli, tak jak cała ta zakładka: jeden zestaw akcji, jeden dziennik.</li><li>Akcja, w której został nierozwiązany <code>{{var.…}}</code>, NIE wyjdzie — wysyłka jest wstrzymana, zanim cokolwiek opuści komputer, a panel mówi, której zmiennej brakuje. Dodaj ją w karcie <b>Zmienne</b> albo popraw akcję.</li>\n        <li>Sejf jest szyfrowany w Twojej przeglądarce (PBKDF2 → AES-GCM) — serwer widzi wyłącznie zaszyfrowany plik. Hasła nie da się odzyskać: bez niego sejfu nie otworzy nikt.</li>\n        <li>Przy imporcie obcej paczki modal pokazuje ostrzeżenia: obcy host, nagłówek autoryzacji, tokeny <code>{{secret.…}}</code>. Czytaj czerwone wiersze i importuj tylko z zaufanego źródła. Pod listą akcji zobaczysz też <b>gotowe ruchy</b> zapisane po ludzku i to, które z nich przyjdą wyłączone.</li>\n        <li>Poświadczenie z sejfu działa wyłącznie na hoście z pola <b>Adres bazowy</b> — akcja prowadząca na inny serwer wyjdzie bez sekretu.</li>\n      </ul>"},
  {id:"pad",panel:"tab-pad",title:"Jak grać dźwiękiem z ruchu?",html:"<h4>Co to jest ten moduł?</h4>\n      <b>Synth</b> to instrument w przeglądarce sterowany ruchem kapsla albo palcem. Każdy <b>pad grający</b> to osobny instrument: własne brzmienie, własna skala, własne osie i własne efekty. Dźwięk powstaje lokalnie (WebAudio) — <b>nie idzie</b> do MIDI, OSC ani do Windows.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 196\" role=\"img\" aria-label=\"Pad grający: w poziomie zmienia się nuta, w pionie barwa i głośność, a dźwięk powstaje w przeglądarce i nigdzie nie wychodzi.\">\n          <rect class=\"g-box g-akcent\" x=\"150\" y=\"28\" width=\"168\" height=\"130\"/>\n          <text class=\"g-txt\" x=\"234\" y=\"20\" data-i18n-en=\"PAD\">PAD</text>\n          <path class=\"g-strzalka\" d=\"M158 152 H310\"/><path class=\"g-grot\" d=\"M310 147 L318 152 L310 157 Z\"/>\n          <path class=\"g-strzalka\" d=\"M158 152 V36\"/><path class=\"g-grot\" d=\"M153 36 L158 28 L163 36 Z\"/>\n          <text class=\"g-sub\" x=\"240\" y=\"172\" data-i18n-en=\"left and right: the note\">w poziomie: nuta</text>\n          <text class=\"g-sub\" x=\"142\" y=\"94\" data-i18n-en=\"up and down: timbre and volume\" transform=\"rotate(-90 142 94)\">w pionie: barwa i głośność</text>\n          <rect class=\"g-box g-cicho\" x=\"8\" y=\"56\" width=\"116\" height=\"48\"/>\n          <text class=\"g-sub\" x=\"66\" y=\"78\" data-i18n-en=\"a finger\">palec</text>\n          <text class=\"g-sub\" x=\"66\" y=\"94\" data-i18n-en=\"or the capsule\">albo kapsel</text>\n          <path class=\"g-strzalka\" d=\"M126 80 H140\"/><path class=\"g-grot\" d=\"M140 75 L148 80 L140 85 Z\"/>\n          <rect class=\"g-box\" x=\"344\" y=\"56\" width=\"140\" height=\"48\"/>\n          <text class=\"g-sub\" x=\"414\" y=\"78\" data-i18n-en=\"sound\">dźwięk</text>\n          <text class=\"g-sub\" x=\"414\" y=\"94\" data-i18n-en=\"in the browser\">w przeglądarce</text>\n          <path class=\"g-strzalka\" d=\"M320 80 H334\"/><path class=\"g-grot\" d=\"M334 75 L342 80 L334 85 Z\"/>\n          <rect class=\"g-box g-cicho\" x=\"516\" y=\"44\" width=\"116\" height=\"72\"/>\n          <text class=\"g-sub\" x=\"574\" y=\"66\" data-i18n-en=\"MIDI · OSC\">MIDI · OSC</text>\n          <text class=\"g-sub\" x=\"574\" y=\"84\" data-i18n-en=\"Windows\">Windows</text>\n          <text class=\"g-sub\" x=\"574\" y=\"104\" data-i18n-en=\"not this way\">nie tędy</text>\n          <path class=\"g-strzalka g-kropkowana\" d=\"M486 80 H512\"/>\n          <path class=\"g-s1\" style=\"stroke-width:2.4\" d=\"M492 73 L506 87 M506 73 L492 87\"/>\n        </svg>\n        <figcaption data-i18n-en=\"The Synth plays to itself. To drive a music program with the same movement, use the MIDI or the OSC module.\">Synth gra u siebie. Żeby ten sam ruch sterował programem muzycznym, użyj modułu MIDI albo OSC.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Kliknij <b>Włącz i zagraj</b> tam, gdzie stoją pady. Ten jeden klik włącza moduł, odblokowuje dźwięk w przeglądarce i włącza granie z ruchu na pierwszym padzie.</li>\n        <li>Możesz też przestawić włącznik modułu na <b>Wł.</b> w pasku u góry ekranu, obok nazwy modułu. Ten klik również odblokowuje dźwięk.</li>\n        <li>Przeciągaj palcem albo myszą po padzie: <b>w poziomie</b> zmieniasz nutę, <b>w pionie</b> barwę i głośność.</li>\n        <li>Włącz <b>▶ Graj z ruchu</b> — teraz kursorem steruje kapsel. Każdy podłączony kapsel dostaje własną żabę i własny głos, więc możecie grać we dwoje.</li>\n        <li>Otwórz ustawienia pada przyciskiem „Ustawienia” na jego pasku i w zwijaku „Skala i nuty” ustaw <b>Tonika</b> i <b>Skala pada</b>: nuty wpadają w skalę, więc trudno zagrać fałszywie.</li>\n      </ul>\n      <h4>Możliwości — co można tu zrobić</h4>\n      <ul>\n        <li>Ustawienia pada otwiera przycisk „Ustawienia” na pasku pada. Na wierzchu stoją głośność, „Kto gra” i kapsle, a reszta w zwijakach z podsumowaniem: „Skala i nuty”, „Oś Y i efekty”, „Kiedy gra i dotyk” oraz „Wygląd pada”.</li>\n        <li><b>Brzmienie</b> — 35 wbudowanych dźwięków: Ribbit, Syntezator, Chip 8-bit, Struna, Trąbka, Przestrzeń, Bas, Organy, Gwizd, Marimba, Smyczki, Wobble, Dzwon, Kwas, Pianino elektryczne, Chórek, Pozytywka, Kosmos, Przester, Syrena, Klarnet, Robot, Pulsar, Hammond, Wokoder, Radio, Wiolonczela, Przypływ, Kalimba, Szkło, Kropla, Gitara basowa, Bańka, Ropucha i Szum. Listę rozwijasz nad padem, a własne dokładasz w zakładce <b>Brzmienia</b>.</li>\n        <li><b data-i18n-en=\"Programmed pads\">Pady zaprogramowane</b> <span data-i18n-en=\"— a saved melody or rhythm that plays by itself, in step with the shared tempo. The capsule does not steer them, an effects pad can.\">— zapisana melodia albo rytm, który gra sam, równo ze wspólnym tempem. Kapsel nimi nie steruje, pad efektów może.</span></li>\n        <li><b data-i18n-en=\"Sample\">Próbka</b><span data-i18n-en=\": in the “Sounds” tab, in the “Advanced” fold, a sound can play a recorded or loaded clip instead of a wave: drag the markers to pick the piece you want.\">: w zakładce „Brzmienia”, w zwijaku „Zaawansowane”, brzmienie może grać nagrany albo wczytany dźwięk zamiast fali. Przeciągasz znaczniki i wybierasz kawałek.</span></li>\n        <li>W zakładce „Brzmienia” oscylatory, filtr i obwiednia stoją w zwijaku „Kształt brzmienia”, a próbka, charakter i pętla testowa w „Zaawansowane” na dole.</li>\n        <li><b data-i18n-en=\"Pad background\">Tło pada</b> <span data-i18n-en=\"— the list beside the sound picks the pad’s background, which reacts to that pad’s sound.\">— lista obok brzmienia wybiera tło pada, które reaguje na jego dźwięk.</span></li>\n        <li><b data-i18n-en=\"Sound library\">Biblioteka dźwięków</b> <span data-i18n-en=\"(the “Sounds” tab) — here you change any sound and make your own. On the left is the list of every sound with a search box and the “All”, “Base”, “Custom” and “Changed” filters: ▶ on a row plays the sound without loading it, and a click on the row loads it for editing. The bar on top holds the emoji, the name, the kind badge and the volume, and the “unsaved changes” dot stays lit until you save the sound. “New” starts from the default settings, “⧉ Duplicate” makes your own copy.\">(zakładka „Brzmienia”) — tu zmieniasz każde brzmienie i tworzysz własne. Z lewej stoi lista wszystkich brzmień z wyszukiwarką i filtrami „Wszystkie”, „Bazowe”, „Własne” i „Zmienione”: ▶ w wierszu gra brzmienie bez wczytywania, a klik w wiersz wczytuje je do edycji. Pasek na górze trzyma emoji, nazwę, plakietkę rodzaju i głośność, a kropka „niezapisane zmiany” świeci, dopóki brzmienia nie zapiszesz. „Nowe” zaczyna od ustawień domyślnych, „⧉ Duplikuj” robi własną kopię.</span></li>\n        <li><b data-i18n-en=\"Oscilloscope lamp\">Lampa oscyloskopu</b> <span data-i18n-en=\"— only shows the sound; nothing is edited on it: the waveform runs as a ring round the dial, the spectrum glows as rays, and movement leaves trails, as on an old CRT screen. Beside it are “Test” (a short arpeggio), “Hold” (the note sounds while you hold it), “Continuous preview”, a level meter and “⤢ Enlarge”.\">— tylko pokazuje dźwięk, niczego się na niej nie edytuje: przebieg biegnie pierścieniem dookoła tarczy, widmo świeci promieniami, a ruch zostawia smugi jak na starym ekranie kineskopowym. Obok są „Testuj” (krótkie arpeggio), „Przytrzymaj” (nuta brzmi, dopóki trzymasz), „Podgląd ciągły”, wskaźnik poziomu i „⤢ Powiększ”.</span></li>\n        <li><b data-i18n-en=\"Wave editor\">Edytor fali</b> <span data-i18n-en=\"(the Oscillators card) — draw one period of the wave with a finger or the mouse, or switch to “Harmonics” and pull 16 bars like the drawbars of an organ. “Smooth” softens the tone, “Clear” starts again from a pure sine, and the wave you drew plays as “Custom” in the “Wave” list.\">(karta Oscylatory) — rysujesz palcem albo myszą jeden okres fali, a po przełączeniu na „Harmoniczne” ciągniesz 16 słupków jak suwaki w organach. „Wygładź” łagodzi barwę, „Wyczyść” zaczyna od czystego sinusa, a narysowana fala gra jako „Własna” na liście „Fala”.</span></li>\n        <li><b data-i18n-en=\"Equaliser\">Korektor</b> <span data-i18n-en=\"(the Filter card) — up to four bands over the live spectrum. Touching an empty spot adds a band, dragging a ring changes its frequency (left and right) and gain (up and down), and the mouse wheel or “Q −” and “Q +” its width. A double-click or “Remove band” removes a band, “Reset” removes them all.\">(karta Filtr) — do czterech pasm na tle żywego widma. Dotknięcie pustego miejsca dodaje pasmo, przeciągnięcie pierścienia zmienia częstotliwość (w poziomie) i wzmocnienie (w pionie), a kółko myszy albo „Q −” i „Q +” szerokość pasma. Dwuklik albo „Usuń pasmo” usuwa pasmo, „Wyzeruj” usuwa wszystkie.</span></li>\n        <li><b data-i18n-en=\"Envelope\">Obwiednia</b> <span data-i18n-en=\"(the Volume envelope card) — points to drag: the top of the attack, the end of the decay with the sustain level, and the end of the release; they move the knobs above the panel. The small rings halfway along the segments bend them: below zero a segment is sharper, above zero gentler, and a double-click straightens it. The amber ring is the filter envelope (amount and time). “Default shape” straightens every segment, “No filter envelope” sets it to zero.\">(karta Obwiednia głośności) — punkty do przeciągania: szczyt ataku, koniec zaniku z poziomem podtrzymania i koniec zwolnienia; przesuwają pokrętła nad panelem. Małe pierścienie w połowie odcinków je zginają: poniżej zera odcinek jest ostrzejszy, powyżej łagodniejszy, a dwuklik go prostuje. Bursztynowy pierścień to obwiednia filtra (wielkość i czas). „Domyślny kształt” prostuje wszystkie odcinki, „Bez obwiedni filtra” ją zeruje.</span></li>\n        <li><b data-i18n-en=\"Randomising\">Losowanie</b> <span data-i18n-en=\"— “🎲 Surprise me” in the bar rolls the whole sound, the custom wave, equaliser bands and envelope bends included, always within playable ranges; the volume stays. The 🎲 on a module card rolls only that module.\">— „🎲 Zaskocz mnie” w pasku losuje całe brzmienie, łącznie z falą własną, pasmami korektora i zgięciami obwiedni, zawsze w zakresach, które da się grać; głośność zostaje. 🎲 na karcie modułu losuje tylko ten moduł.</span></li>\n        <li><b>Zakres nut</b> — <b>Od nuty</b> (od której nuty zaczyna lewa krawędź) i <b>Oktawy</b> (ile oktaw mieści się na szerokość).</li>\n        <li><b>Przejścia</b> — trzy tryby: <b>⊓⊓ Skokowe</b> (nuta wskakuje na kolejny stopień skali), <b>〜 Płynne</b> (portamento — dźwięk zjeżdża między nutami, tym dłużej im większy skok) oraz <b>∿ Superpłynne</b> (bez skali i bez nut: cała szerokość pada to jedno pasmo wysokości, dźwięk idzie za palcem bez progów).</li>\n        <li><b>Efekty</b> — <b>Echo</b>, <b>Wibrato</b>, <b>Zatrzask</b> (gra dalej po puszczeniu), a w <b>Efekty pada:</b> m.in. <b>Jasność</b> i <b>Cięcie basu</b> z suwakami i włącznikiem.</li>\n        <li><b>Ruch, który słychać</b> — <b>🎳 Momentum</b> (rzuć żabę: szybuje dalej i gra) oraz <b>Velocity z ruchu</b> (im energiczniej, tym głośniej).</li>\n        <li><b>Dodaj pad grający</b>: kolejny niezależny instrument. Przyciski dodawania padów stoją w zwijaku „Zaawansowane” na dole ekranu. <b>Kapsel sterujący</b> wybierasz osobno dla każdego pada, a <b>Oś X</b> i <b>Oś Y</b> decydują, który ruch nim porusza.</li>\n        <li><b>Dodaj pad efektów</b> — powierzchnia XY, która nie gra nut, tylko kręci efektami wybranego pada grającego (pole <b>Steruje padem grającym</b> na górze karty — stoi tam także wtedy, gdy pad grający jest jeden).</li>\n        <li><b>Kiedy gra i dotyk</b>: warunki jak w wyzwalaczach, na przykład graj tylko przy wciśniętym przycisku. Możesz też użyć <b>Połącz z mapowaniem</b>.</li>\n        <li><b>Pełny ekran</b> — pad na cały ekran do grania na tablecie (wyjście klawiszem <code>Esc</code>).</li>\n      </ul>\n      <h4>💡 Wskazówki</h4>\n      <ul>\n        <li>Cisza mimo ruchu? Sprawdź włącznik modułu, <b>🔊 Głośność</b> i czy strona dostała już jedno kliknięcie (odblokowanie dźwięku).</li>\n        <li>Dźwięk „ucieka” za ręką — o to chodzi w <b>Drag dotyku</b>: mniejszy drag = kursor leci za palcem leniwiej.</li>\n        <li>Coś zawisło i brzęczy? <b>⏹ Ucisz zacięte dźwięki</b> w pasku nad padami ucisza wszystko natychmiast.</li>\n        <li>Do grania w duecie: dwa kapsle + <b>Zatrzask</b> na jednym z padów — jeden trzyma burdon, drugi gra melodię.</li>\n        <li><b data-i18n-en=\"Editing starts from the wave you had.\">Edycja zaczyna się od gotowej fali.</b> <span data-i18n-en=\"The first touch of the editor on a plain wave (Saw, Square, Triangle, Sine) starts from its shape and switches the “Wave” list to “Custom”, so there is no need to draw from scratch.\">Pierwsze dotknięcie edytora przy zwykłej fali (Piła, Kwadrat, Trójkąt, Sinus) zaczyna od jej kształtu i przełącza listę „Fala” na „Własna”, więc nie trzeba rysować od zera.</span></li>\n        <li><b data-i18n-en=\"Hear it straight away.\">Słychać od razu.</b> <span data-i18n-en=\"Turn on “Continuous preview” (the note comes back every moment with the current settings), or on a touch screen keep one finger on “Hold” and draw with another: a moment after each change the note sounds again.\">Włącz „Podgląd ciągły” (nuta wraca co chwilę z bieżącymi ustawieniami) albo na ekranie dotykowym jednym palcem trzymaj „Przytrzymaj”, a drugim rysuj: chwilę po każdej zmianie nuta zabrzmi od nowa.</span></li>\n        <li><b data-i18n-en=\"A bend of 0 is the usual shape.\">Zgięcie 0 to dotychczasowy kształt.</b> <span data-i18n-en=\"That is how the envelope sounded before bends existed, and how sounds without them still play. A double-click on a small ring or “Default shape” brings it back.\">Tak brzmiała obwiednia, zanim pojawiły się zgięcia, i tak dalej grają brzmienia bez nich. Dwuklik w mały pierścień albo „Domyślny kształt” do niego wraca.</span></li>\n      </ul>\n      \n      <h4>Konfiguracja i Biblioteka — kiedy trzeba kliknąć „Zapisz zmiany”</h4>\n      Pod-zakładka <b>Konfiguracja</b> to ustawienia tego modułu: co tu zmienisz, działa od razu, bez żadnego przycisku. Pod-zakładka <b>Biblioteka</b> to nazwane konfiguracje odłożone na później — i te zmieniają się dopiero wtedy, gdy klikniesz „Zapisz zmiany”. Właśnie dlatego przy nazwie zapala się bursztynowa kropka: w module wszystko już działa, w bibliotece jeszcze nie.\n      <h4>Uwagi</h4>\n      Pad jest <b>tylko lokalny</b>: nie wysyła MIDI, OSC ani klawiszy, więc możesz go używać nawet gdy główny przełącznik bezpieczeństwa jest wstrzymany. Pady i brzmienia zapisują się w pliku <code>Settings/ribbitflip_synth.json</code> obok aplikacji, więc każda przeglądarka na tym komputerze widzi te same. Do przeniesienia na inny komputer użyj zestawu z zakładki <b>Biblioteka</b>.<br>\n      <small style=\"color:var(--dim)\">🐸 Kursorem jest śpiewająca żaba — im wyżej trzymasz dźwięk, tym szerzej otwiera pysk.</small>"},
  {id:"czujnik",panel:"tab-czujnik",title:"Co pokazuje czujnik i jak ustawić osie 3D?",html:"<h4>Do czego służy ten ekran?</h4>\n      To „maszynownia” kapsla: surowe odczyty 6 kanałów IMU na żywo i strojenie osi 3D, z których korzysta cała reszta aplikacji (wyzwalacze, mysz/gałka, MIDI/OSC). Kanały CH0–2 to żyroskop, CH3–5 — akcelerometr (grawitacja ≈ <code>2048 LSB</code> na 1 g). Tu sprawdzasz, czy dane płyną, i ustawiasz, jak ruch kapsla przekłada się na osie filtra 3D (Pochylenie, Obrót, Pitch, Roll).\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 110\" role=\"img\" aria-label=\"Droga odczytu z czujnika: sześć surowych kanałów, przypisanie kanałów do osi, osie filtra 3D, moduły, które z nich korzystają.\">\n          <rect class=\"g-box\" x=\"8\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"77\" y=\"58\" data-i18n-en=\"6 IMU channels\">6 kanałów IMU</text>\n          <text class=\"g-sub\" x=\"77\" y=\"76\" data-i18n-en=\"CH0–2 gyro, CH3–5 accel.\">CH0–2 żyro, CH3–5 akcel.</text>\n          <rect class=\"g-box\" x=\"169\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"238\" y=\"58\" data-i18n-en=\"The axis setup\">Konfiguracja osi</text>\n          <text class=\"g-sub\" x=\"238\" y=\"76\" data-i18n-en=\"which channel feeds which axis\">który kanał zasila którą oś</text>\n          <path class=\"g-strzalka\" d=\"M150 61 H158\"/><path class=\"g-grot\" d=\"M158 56 L166 61 L158 66 Z\"/>\n          <rect class=\"g-box\" x=\"330\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"399\" y=\"58\" data-i18n-en=\"The 3D filter axes\">Osie filtra 3D</text>\n          <text class=\"g-sub\" x=\"399\" y=\"76\" data-i18n-en=\"Lean · Twist · Pitch · Roll\">Pochylenie · Obrót · Pitch · Roll</text>\n          <path class=\"g-strzalka\" d=\"M311 61 H319\"/><path class=\"g-grot\" d=\"M319 56 L327 61 L319 66 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"491\" y=\"34\" width=\"139\" height=\"54\"/>\n          <text class=\"g-txt\" x=\"560\" y=\"58\" data-i18n-en=\"Everything else\">Cała reszta</text>\n          <text class=\"g-sub\" x=\"560\" y=\"76\" data-i18n-en=\"triggers, mouse, MIDI, OSC\">wyzwalacze, mysz, MIDI, OSC</text>\n          <path class=\"g-strzalka\" d=\"M472 61 H480\"/><path class=\"g-grot\" d=\"M480 56 L488 61 L480 66 Z\"/>\n          <text class=\"g-sub\" x=\"320\" y=\"112\" data-i18n-en=\"A wrongly chosen channel breaks everything to the right of it — which is why this screen is set up once, at the start.\">Źle dobrany kanał psuje wszystko po prawej — dlatego ten ekran ustawia się raz, na początku.</text>\n        </svg>\n        <figcaption data-i18n-en=\"The “3D orientation” sphere at the top of the screen is the test: it has to repeat whatever the capsule does in your hand.\">Kula „Orientacja 3D” u góry ekranu jest sprawdzianem: ma powtarzać to, co robi kapsel w Twojej dłoni.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>Połącz kapsel na ekranie <b>Połączenie</b>, wróć tu i rusz nim. Kula „Orientacja 3D” ma się ruszać razem z kapslem, a liczby w karcie <b>Czujniki: 6 kanałów na żywo</b> (w „Zaawansowane” na dole ekranu) muszą się zmieniać.</li>\n        <li>Rozwiń zwijak „Osie 3D”, w nim „Mapa kanałów”, i ruszaj kapslem: dla każdej z 6 osi dobierz kanał (CH0–CH5) i w razie potrzeby zaznacz <b>odwróć</b>, aż kula w podglądzie <b>Orientacja 3D</b> u góry odda realne położenie.<br>\n          <small style=\"color:var(--dim)\">💡 Twist = obrót wokół osi kapsla; Pitch i Roll = pochylenie przód/tył i lewo/prawo.</small></li>\n        <li>Dopasuj suwak <b>Czułość filtra (gładko ↔ ostro)</b>, a potem <b>Przyspieszenie wychylenia (czułość osi 3D)</b> (oba w „Osie 3D” › „Zachowanie filtra 3D”). Efekt widzisz od razu na wykresie „Filtr 3D: osie” w „Zaawansowane”.</li>\n        <li>Gdy wszystko gra: w zwijaku „🎨 Presety osi” (w „Osie 3D”) wpisz nazwę w polu <b>nazwa presetu osi</b> i zapisz zestaw przyciskiem <b>Zapisz</b>, by wrócić do niego później.</li>\n      </ul>\n      <h4>Co tu można zrobić?</h4>\n      <ul>\n        <li>Na wierzchu stoi kula „Orientacja 3D” z przyciskami „⏸ Pauza”, „Wyśrodkuj” i „Steruj ręcznie” oraz pytanie „Kula kręci się odwrotnie?”. Strojenie trzyma zwinięty „Osie 3D”: mapa kanałów, dostrajanie sygnału, zachowanie filtra i presety osi. Wykresy kanałów, surowy strumień i status przycisków są w „Zaawansowane” na dole ekranu.</li>\n        <li><b>Czujniki: 6 kanałów na żywo</b> — surowe wartości LSB każdego kanału; auto-detekcja odróżnia grawitację/offset od ruchu.</li>\n        <li><b>Osie 3D</b> — mapowanie kanałów na osie (3× akcelerometr, 3× żyroskop) z opcją <b>odwróć</b>. Przycisk <b>Przywróć fabryczne osie</b> przywraca mapę fabryczną, a <b>Kopiuj konfigurację</b> kopiuje konfigurację do schowka.</li>\n        <li><b>Cały obraz jest odbity jak w lustrze</b> — zaznacz <b>włącz</b>, gdy ruch na podglądzie jest odbity względem rzeczywistości.</li>\n        <li><b>🎨 Presety osi:</b> — nazwane zestawy konfiguracji: wybierz z listy i kliknij <b>Wczytaj</b>; nowy zapisujesz przyciskiem <b>Zapisz</b>, a usuwasz ikoną kosza.</li>\n        <li><b>🧲 Kopiuj osie 3D z:</b> — przy co najmniej 2 kapslach wybierz inny Triki z listy i kliknij <b>⤵ Wczytaj z Triki</b>, by przenieść jego osie na bieżący kapsel.</li>\n        <li><b>Przyciski / status (0x21)</b> — 5-bajtowe pakiety statusu: <b>naciśnij / stuknij kapsel</b> i patrz, które bajty się podświetlają (B0 to nagłówek).</li>\n        <li><b>Surowy strumień (hex)</b> — bajty prosto z BLE (dowód, że dane są prawdziwe); wiersz <b>ostatni IMU:</b> pokazuje ostatni pakiet ruchu.</li>\n        <li>Pasek „⌖ klik” pod wykresem kanałów to naciśnięcia przycisku w czasie: początek paska to moment naciśnięcia, a jego długość to czas trzymania (w dłuższych wpisana jest liczba). Wskaźnik „LED” w lewym dolnym rogu podglądu „Orientacja 3D” świeci, kiedy aplikacja zapaliła diodę kapsla.</li>\n      </ul>\n      <h4>Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li>💡 <b>Czułość filtra (gładko ↔ ostro)</b> to reaktywność całego filtra 3D — steruje też wyjściami: gałką, myszą (filtr 3D), krzyżakiem, MIDI/OSC i wyzwalaczami.</li>\n        <li>💡 <b>Przyspieszenie wychylenia (czułość osi 3D)</b> (zakres 0,3–4×): powyżej 1× pełne wychylenie osiągasz mniejszym ruchem — wygodne przy delikatnych gestach.</li>\n        <li>💡 Kliknij liczbę obok suwaka, by wpisać wartość ręcznie (<code>Enter</code> = zatwierdź, <code>Esc</code> = anuluj).</li>\n        <li>💡 Każda z 6 osi musi mieć inny kanał — przy powtórce panel pokaże ostrzeżenie, a podgląd „szaleje”; kliknij wtedy <b>Przywróć fabryczne osie</b>, by wrócić do działającej mapy.</li>\n      </ul>\n      <h4>Uwagi</h4>\n      Ta zakładka niczego nie wysyła do Windows — to wyłącznie podgląd i strojenie, można eksperymentować bez ryzyka. Konfiguracja osi zapisuje się sama (lokalnie i na serwerze), osobno dla każdego Triki — nowy kapsel dziedziczy osie pierwszego. Obrót wokół osi kapsla liczony jest z żyroskopu i może z czasem dryfować — kliknij wtedy <b>Wyśrodkuj</b> w karcie <b>Orientacja 3D</b> na pasku u góry."},
  {id:"polaczenie",panel:"tab-polaczenie",title:"Jak sprawdzić połączenie i zadbać o baterię?",html:"<h4>Do czego służy ten ekran?</h4>\n      To zaplecze techniczne kapsla. Sprawdzasz tu, czy Triki jest połączony i czy płyną dane (karta <b>Połączenie z urządzeniem</b>), usypiasz go dla oszczędzania baterii, sterujesz diodą i surowymi komendami BLE oraz nagrywasz surowe próbki czujnika do pliku CSV.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 172\" role=\"img\" aria-label=\"Kapsel łączy się z aplikacją po Bluetooth i może być w jednym z trzech stanów: połączony, szukany albo zastąpiony symulacją.\">\n          <rect class=\"g-box\" x=\"8\" y=\"26\" width=\"180\" height=\"58\"/>\n          <text class=\"g-txt\" x=\"98\" y=\"50\" data-i18n-en=\"The Triki capsule\">Kapsel Triki</text>\n          <text class=\"g-sub\" x=\"98\" y=\"68\" data-i18n-en=\"a sensor and a battery\">czujnik + bateria</text>\n          <path class=\"g-strzalka\" d=\"M196 55 H242\"/><path class=\"g-grot\" d=\"M242 50 L250 55 L242 60 Z\"/>\n          <text class=\"g-sub\" x=\"223\" y=\"44\" data-i18n-en=\"BLE\">BLE</text>\n          <rect class=\"g-box\" x=\"258\" y=\"26\" width=\"180\" height=\"58\"/>\n          <text class=\"g-txt\" x=\"348\" y=\"50\" data-i18n-en=\"RibbitFlip\">RibbitFlip</text>\n          <text class=\"g-sub\" x=\"348\" y=\"68\" data-i18n-en=\"~50 Hz, IMU packets\">~50 Hz, pakiety IMU</text>\n          <path class=\"g-strzalka\" d=\"M446 55 H492\"/><path class=\"g-grot\" d=\"M492 50 L500 55 L492 60 Z\"/>\n          <rect class=\"g-box g-akcent\" x=\"508\" y=\"26\" width=\"124\" height=\"58\"/>\n          <text class=\"g-txt\" x=\"570\" y=\"50\" data-i18n-en=\"The modules\">Moduły</text>\n          <text class=\"g-sub\" x=\"570\" y=\"68\" data-i18n-en=\"all of them at once\">wszystkie naraz</text>\n          <rect class=\"g-box g-cicho\" x=\"8\" y=\"100\" width=\"200\" height=\"52\"/>\n          <text class=\"g-sub\" x=\"108\" y=\"122\" data-i18n-en=\"● Connected\">● Połączono</text>\n          <text class=\"g-sub\" x=\"108\" y=\"140\" data-i18n-en=\"the data is flowing\">dane płyną</text>\n          <rect class=\"g-box g-cicho\" x=\"220\" y=\"100\" width=\"200\" height=\"52\"/>\n          <text class=\"g-sub\" x=\"320\" y=\"122\" data-i18n-en=\"○ Searching…\">○ Szukam…</text>\n          <text class=\"g-sub\" x=\"320\" y=\"140\" data-i18n-en=\"the app is scanning BLE\">aplikacja skanuje BLE</text>\n          <rect class=\"g-box g-cicho\" x=\"432\" y=\"100\" width=\"200\" height=\"52\"/>\n          <text class=\"g-sub\" x=\"532\" y=\"122\" data-i18n-en=\"● Simulation\">● Symulacja</text>\n          <text class=\"g-sub\" x=\"532\" y=\"140\" data-i18n-en=\"synthetic data\">dane syntetyczne</text>\n        </svg>\n        <figcaption data-i18n-en=\"Before you start hunting for a fault in a module, check here: a rate of about 50 Hz and a packet counter that keeps rising.\">Zanim zaczniesz szukać błędu w module, sprawdź tutaj: częstotliwość ok. 50 Hz i rosnący licznik pakietów.</figcaption>\n      </figure>\n      <h4>Jak zacząć — krok po kroku</h4>\n      <ul>\n        <li>1. Spójrz na pole <b>Status</b>: <code>● Połączono</code> = kapsel strumieniuje, <code>○ Szukam…</code> = aplikacja skanuje BLE w poszukiwaniu kapsla, <code>● Symulacja</code> = dane syntetyczne.</li>\n        <li>2. W „Zaawansowane” › „Szczegóły połączenia” potwierdź, że dane płyną: <b>Częstotliwość</b> ma pokazywać ok. 50 Hz, a licznik <b>Pakiety IMU</b> powinien rosnąć.</li>\n        <li>3. Tryb pracy zmieniasz przełącznikiem <b>LIVE</b> / <b>Symulacja</b> w prawym górnym rogu ekranu — aplikacja restartuje się po potwierdzeniu przyciskiem <b>Przełącz i zrestartuj</b>.</li>\n        <li>4. Kończysz grać? Kliknij <b>Uśpij</b> — kapsel przestaje strumieniować i nie zużywa baterii; <b>▶ Wznów</b> budzi go z powrotem.</li>\n      </ul>\n      <h4>Co tu można zrobić?</h4>\n      <ul>\n        <li>Na wierzchu karty „Połączenie z urządzeniem” stoją status, siła sygnału (RSSI), bateria, „Uśpij” i „Dodaj kapsel”. Zwinięte „Nazwa i dioda” oraz „Oszczędzanie baterii” mają w nagłówku bieżące ustawienia, a „Zaawansowane” na dole ekranu trzyma szczegóły połączenia (adres, MTU, częstotliwość, przepływ, liczniki pakietów i czas sesji), częstotliwość strumienia, komendy urządzenia i nagrywanie CSV.</li>\n        <li><b>Wstrzymuj wyjścia przy bezczynności</b> — kapsel odłożony na bok przestaje sterować, a pierwszy ruch przywraca działanie od razu. Czas ustawiasz suwakiem <b>Po czasie</b> (od 5 sekund do 10 minut). Przydaje się, gdy odkładasz kapsel w trakcie pracy: kursor nie ucieka, klawisze nie lecą, a Ty nie musisz niczego klikać ani przed, ani po. Wstrzymanie z bezczynności jest oddzielne od ręcznego, spod przełącznika <b>⏻ Uzbrojone</b> — jedno nie kasuje drugiego, a pigułka kapsla mówi, które go trzyma. Usypianie kapsla (wyżej) oszczędza baterię, ale wybudzenie chwilę trwa; wstrzymanie przy bezczynności działa natychmiast w obie strony, za to baterii nie oszczędza, bo kapsel dalej nadaje.</li>\n        <li><b>Oszczędzanie baterii</b> — ręczne <b>Uśpij</b> / <b>▶ Wznów</b>, auto-uśpienie po X minutach bezczynności i rzadszy odczyt baterii (mniej zapytań przez Bluetooth). W „Zaawansowane” › <b>Częstotliwość strumienia</b> zmienisz pole <b>Komenda wybudzenia</b> — niższa częstotliwość = mniej prądu, ale wyzwalacze reagują wolniej; <b>↺ Domyślna (≈50 Hz)</b> przywraca standard.</li>\n        <li><b>LED / komendy urządzenia</b> — presety <b>LED ON</b> / <b>LED OFF</b> / <b>SLEEP</b> albo własna komenda: wybierasz <b>Charakterystyka (UUID zapisu)</b>, wpisujesz <b>Hex</b> (np. <code>01</code> = dioda świeci) i klikasz <b>▶ Wyślij</b>. Poniżej wynik wysyłki i log ostatnich komend.</li>\n        <li><b>Nagrywanie danych (CSV)</b> — zapis surowych próbek 6 kanałów + statusu do pliku: <b>Nagrywaj CSV</b> zaczyna, <b>⏹ Zatrzymaj nagrywanie</b> kończy, <b>Pobierz</b> zapisuje plik z kolumnami m.in. <code>ts</code>, <code>ch0…ch5</code>, <code>hex</code>.</li>\n      </ul>\n      <h4>Wskazówki i typowe zastosowania</h4>\n      <ul>\n        <li>💡 Czerwony licznik <code>● REC</code> przy przycisku <b>Pobierz</b> pokazuje liczbę nagranych próbek. Nagrywanie NIE zbiera danych od otwarcia strony — startuje dopiero po kliknięciu, a <b>Wyczyść</b> kasuje też nagranie.</li>\n        <li>💡 Odczyt <b>Bateria</b> jest orientacyjny — tanie moduły BLE potrafią pokazywać 100% niemal do końca, a potem szybko spadać.</li>\n        <li>💡 Tryb <b>Symulacja</b> to bezpieczny poligon: dane syntetyczne bez sprzętu, klawisze i MIDI nie wychodzą do Windows. Idealny do nauki obsługi i budowania mapowań bez kapsla pod ręką.</li>\n        <li>💡 Masz kilka kapsli? Statystyki i nagrywanie CSV dotyczą kapsla oglądanego w pasku <b>Kapsle Triki</b> nad podglądem.</li>\n      </ul>\n      <h4>Uwagi i bezpieczeństwo</h4>\n      <ul>\n        <li>Surowe komendy hex to narzędzie dla zaawansowanych — błędna komenda może np. zatrzymać strumień danych. Ratunek: <b>▶ Wznów</b> albo ponowne połączenie.</li>\n        <li>W trybie <b>Symulacja</b> komendy nie idą do urządzenia — wynik pokaże <code>○ symulacja</code>.</li>\n        <li>Przełączenie <b>LIVE</b> / <b>Symulacja</b> restartuje aplikację — nagranie CSV z pamięci przepada, więc najpierw kliknij <b>Pobierz</b>.</li>\n      </ul>"},
  {id:"konfiguracje",panel:"tab-konfiguracje",title:"Jak zapisywać i współdzielić zestawy?",html:"<h4>Co to jest zestaw?</h4>\n      Ustawienia pod jedną grę albo program, w jednym pliku. Niesie sekcje: <b>Wyzwalacze (Mapowanie)</b>, <b>Mysz i kontroler (sterowanie ruchem)</b>, <b>MIDI / OSC</b>, <b data-i18n-en=\"Scanner\">Skaner</b>, <b>Kalibracja osi 3D</b>, <b>Oszczędzanie baterii</b> i <b data-i18n-en=\"Synth: pads and sounds\">Synth: pady i dźwięki</b>, razem z informacją, których modułów używa. Zestawy leżą w <b>Bibliotece</b>, w katalogu <code>Library/Setups/</code> obok aplikacji. Osobno zapisujesz <b>Koło wyboru</b> (ma własne presety) i <b data-i18n-en=\"network services\">usługi sieciowe</b> (własny plik, czyli <b data-i18n-en=\"action pack\">paczka akcji</b>). Tokeny i hasła nie wchodzą do żadnego z nich: leżą w osobnym, zaszyfrowanym sejfie i zostają u Ciebie.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 252\" role=\"img\" aria-label=\"Co jedzie razem z zestawem, a co ma własny plik albo zostaje na tym komputerze.\">\n          <rect class=\"g-box g-akcent\" x=\"8\" y=\"30\" width=\"380\" height=\"214\"/>\n          <text class=\"g-txt\" x=\"198\" y=\"22\" data-i18n-en=\"A SETUP, one file\">ZESTAW, jeden plik</text>\n          <rect class=\"g-box\" x=\"24\" y=\"44\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"110\" y=\"65\" data-i18n-en=\"Triggers (Mapping)\">Wyzwalacze (Mapowanie)</text>\n          <rect class=\"g-box\" x=\"204\" y=\"44\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"290\" y=\"65\" data-i18n-en=\"Mouse and controller\">Mysz i kontroler</text>\n          <rect class=\"g-box\" x=\"24\" y=\"86\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"110\" y=\"107\" data-i18n-en=\"MIDI / OSC\">MIDI / OSC</text>\n          <rect class=\"g-box\" x=\"204\" y=\"86\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"290\" y=\"107\" data-i18n-en=\"Scanner\">Skaner</text>\n          <rect class=\"g-box\" x=\"24\" y=\"128\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"110\" y=\"149\" data-i18n-en=\"The 3D axis calibration\">Kalibracja osi 3D</text>\n          <rect class=\"g-box\" x=\"204\" y=\"128\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"290\" y=\"149\" data-i18n-en=\"Battery saving\">Oszczędzanie baterii</text>\n          <rect class=\"g-box\" x=\"114\" y=\"170\" width=\"172\" height=\"32\"/>\n          <text class=\"g-sub\" x=\"200\" y=\"191\" data-i18n-en=\"Synth: pads and sounds\">Synth: pady i dźwięki</text>\n          <text class=\"g-sub\" x=\"198\" y=\"234\" data-i18n-en=\"…plus which modules it uses\">…plus informacja, których modułów używa</text>\n          <text class=\"g-txt\" x=\"520\" y=\"22\" data-i18n-en=\"BESIDE IT, on its own\">OBOK, osobno</text>\n          <rect class=\"g-box g-cicho\" x=\"404\" y=\"30\" width=\"228\" height=\"60\"/>\n          <text class=\"g-sub\" x=\"518\" y=\"56\" data-i18n-en=\"The selection wheel\">Koło wyboru</text>\n          <text class=\"g-sub\" x=\"518\" y=\"74\" data-i18n-en=\"has presets of its own\">ma własne presety</text>\n          <rect class=\"g-box g-cicho\" x=\"404\" y=\"102\" width=\"228\" height=\"60\"/>\n          <text class=\"g-sub\" x=\"518\" y=\"128\" data-i18n-en=\"Network services\">Usługi sieciowe</text>\n          <text class=\"g-sub\" x=\"518\" y=\"146\" data-i18n-en=\"a separate file: an action pack\">osobny plik: paczka akcji</text>\n          <rect class=\"g-box g-cicho\" x=\"404\" y=\"174\" width=\"228\" height=\"60\"/>\n          <text class=\"g-sub\" x=\"518\" y=\"200\" data-i18n-en=\"The password safe\">Sejf z hasłami</text>\n          <text class=\"g-sub\" x=\"518\" y=\"218\" data-i18n-en=\"it stays with you\">zostaje u Ciebie</text>\n        </svg>\n        <figcaption data-i18n-en=\"A Setup sent to somebody carries the left-hand column. The right-hand one either has a file of its own or never leaves this computer.\">Zestaw wysłany komuś niesie lewą kolumnę. Prawa albo ma własny plik do wysłania, albo nie opuszcza tego komputera.</figcaption>\n      </figure>\n      <h4>Zestawy, które przyszły z aplikacją</h4>\n      <b>Biblioteka</b> zaczyna się od zestawów z plakietką „w aplikacji”. Nie zapisywał ich nikt u Ciebie, przyszły razem z programem, żeby kapsel robił coś sensownego od pierwszego uruchomienia. Wczytujesz je i pobierasz jak każdy inny, ale nie da się ich usunąć. Chcesz własną wersję? Wczytaj, przerób w zakładce Mapowanie i zapisz pod tą samą nazwą: od tej chwili Twoja wersja przykrywa oryginał, a skasowanie jej przywraca ten z aplikacji.\n      <h4>Weź gotowy od kogoś</h4>\n      Najszybsza droga do działającej konfiguracji jest cudza, więc zakładka zaczyna się od karty <b>Wymiana z innymi</b>: przycisk <b>Przeglądaj forum ↗</b> otwiera kanał #zestawy, a <b>Wczytaj plik lub odnośnik</b> otwiera jedno okno importu.\n      <ul>\n        <li>Do tego okna prowadzą trzy drogi: plik z dysku, wklejony odnośnik do pliku z posta albo upuszczenie pliku na okno aplikacji. O rodzaju decyduje zawartość: zestaw, zestaw na kilka kapsli, presety i paczka REST rozpoznają się same. Paczka REST pyta jeszcze, do której aplikacji ma wejść.</li>\n        <li>Zanim cokolwiek się zmieni, widzisz <b>podgląd bezpieczeństwa</b> (sekcja niżej) i to, czego zestaw wymaga poza aplikacją.</li>\n        <li>Zanim cokolwiek zostanie podmienione, aplikacja pyta i wypisuje, czego nie masz zapisanego. Masz trzy wyjścia: „Zapisz i wczytaj” (odkłada w Bibliotece to, co masz teraz, pod nazwą, którą podasz), „Wczytaj bez zapisywania” albo „Anuluj”.</li>\n        <li>Po każdym wczytaniu, także własnego zestawu z listy, toast daje <b>↶ Cofnij</b>.</li>\n      </ul>\n      <h4>Zapisz swój</h4>\n      <ul>\n        <li>Ustaw moduły na ich ekranach (Mapowanie, Mysz, MIDI, Skaner, Synth) i sprawdź, że działają.</li>\n        <li>Pasek pod listą w karcie <b>Biblioteka</b> przyjmuje nazwę (np. <code>Minecraft</code>). Program albo grę i krótki opis dopiszesz w zwijaku „Gra i opis” pod paskiem. Potem klikasz <b>Zapisz zestaw</b>.</li>\n        <li>Zapis nie pyta, co uwzględnić: zestaw z definicji jest całą konfiguracją.</li>\n        <li>Powrót do zestawu: znajdź go na liście i kliknij <b>Wczytaj</b>. Aplikacja zapyta o niezapisane zmiany, zastosuje wszystko i odświeży stronę.</li>\n        <li>💡 Jeden zestaw = jedna gra albo program.</li>\n      </ul>\n      <h4>Zestaw wczytany sam, gdy startujesz grę</h4>\n      W zwijaku „Gra i opis” pod paskiem zapisu, obok pola „dla programu/gry”, stoi pole „gra.exe”. Wpisujesz tam nazwę pliku gry, tak jak widzi ją Windows (na przykład eldenring.exe), a aplikacja pilnuje, które okno jest na wierzchu, i wczytuje ten zestaw sama, gdy gra się pojawi. Kilka nazw oddziel przecinkiem, gdy gra ma osobny launcher. Funkcję włączasz w zwijaku „Auto-zestawy wg gry” w tej zakładce; domyślnie jest wyłączona, bo sięganie do Twojej konfiguracji bez pytania to decyzja, którą podejmujesz Ty.\n      <ul>\n        <li>Gdy do jednej gry pasuje kilka zestawów, aplikacja nie zgaduje: pyta, którego użyć, i może zapamiętać odpowiedź. Zapamiętane pary „gra → zestaw” widzisz i kasujesz w tym samym zwijaku, przyciskiem ✕.</li>\n        <li>Wczytanie zmienia wyłącznie ustawienia. Żadna grupa wyjść nie włącza się sama, dokładnie jak przy wczytywaniu ręcznym; inaczej odpalenie gry zaczynałoby po cichu wysyłać.</li>\n        <li>Nazwa gry jedzie razem z plikiem, gdy dzielisz się zestawem, więc osoba, która go wczyta, dostaje też auto-wczytywanie.</li>\n      </ul>\n      <h4>Podziel się</h4>\n      <ul>\n        <li>Przy każdym miejscu zapisu stoi ten sam przycisk <b>Wymiana</b>: przy zapisie zestawu, przy presetach wyzwalaczy (Mapowanie), przy presetach osi (Czujnik) i w karcie aplikacji REST. Otwiera okno „Wymiana z innymi” z czterema wierszami: podziel się tym, przeglądaj forum, wczytaj plik lub odnośnik i jak to w ogóle działa.</li>\n        <li><b>Podziel się</b> uruchamia kreator posta: prowadzi przez nazwę, tagi do zaznaczenia oraz gotowy tytuł i treść do wklejenia na forum #zestawy. Plik dokładasz do posta jako załącznik.</li>\n        <li>W pierwszym kroku kreatora stoi <b>Zakres pliku: wszystkie sekcje</b> z przyciskiem <b>Zmień</b>. To jedyne miejsce, w którym decydujesz, czego plik ma nie nieść (np. bez padów Syntha).</li>\n        <li>Sam plik, bez posta, bierzesz ze stopki okna wymiany: <b>Pobierz plik .json</b>.</li>\n        <li>Podpisu nie wpisujesz: post wychodzi z Twojego konta na forum. Gdy poprawiasz cudzy zestaw, aplikacja sama dopisze „Na bazie” do posta i do pliku.</li>\n      </ul>\n      <h4>Kilka kapsli naraz</h4>\n      Gdy masz sparowane co najmniej dwa kapsle, pod paskiem zapisu pojawia się druga linia z własnym przyciskiem <b>Wymiana</b>. Zestaw na kilka kapsli niesie ustawienia aplikacji i konfigurację każdego kapsla w jednym pliku, a każdy kapsel ma w nim <b>rolę</b> („Kierowanie”, „Skok i strzał”), którą opisujesz w kreatorze. Osoba, która wczyta plik, przypisze do tych ról swoje kapsle. Bez ról trafiłyby po kolejności parowania, czyli losowo.\n      <h4>Co leży w Bibliotece</h4>\n      Jedna lista wszystkiego, co masz zapisane: zestawy, presety wyzwalaczy i presety osi 3D. Każda pozycja mówi, do czego jest, czyja jest i co zmieni po wczytaniu, a obok ma <b>Wczytaj</b>, <b>Pobierz</b> (zapis do pliku bez ruszania Twojej konfiguracji) i <b>Usuń</b>. Kopie zapisane przed wczytaniem trafiają tutaj, więc powrót do stanu sprzed cudzego pliku to jedno kliknięcie. Czym zestaw różni się od presetu, tłumaczy rozwijane <b>„Zestaw, preset, konfiguracja: co jest czym”</b> na górze tego poradnika.\n      <h4>Bezpieczeństwo importu (ważne)</h4>\n      <b>Nie importuj w ciemno cudzych plików.</b> Każdy import najpierw analizuje zawartość i pokazuje podgląd bezpieczeństwa: ✅ bezpieczne reguły (same klawisze do gry) i ⚠️ ryzykowne (makra / klawisze systemowe). Makro wykonuje <b>realne operacje na Twoim komputerze</b>: może naciskać klawisze, wpisywać komendy i otwierać programy. Nie ufasz źródłu? Wybierz <b>Wczytaj tylko bezpieczne</b>. Przycisk <b>⚠️ Rozumiem ryzyko, wczytaj wszystko</b> odblokuje się dopiero po zaznaczeniu <b>Wiem, co robię: ufam źródłu tego pliku</b>.<br>\n      <small style=\"color:var(--dim)\">💡 Wczytanie pyta, zanim nadpisze. Okno wymienia moduły, w których masz coś niezapisanego — osobno dla każdego kapsla — i pozwala to najpierw odłożyć w Bibliotece pod własną nazwą. Kopia nigdy nie nadpisuje istniejącego zestawu, więc wieczór spędzony na strojeniu osi nie znika przez jeden import. Gdy wszystko, czego zestaw dotyka, jest już zapisane, okno mówi to wprost i o zapis nie pyta.</small><br>\n      <small style=\"color:var(--dim)\">💡 Pod ostrzeżeniem aplikacja wypisuje, czego zestaw potrzebuje poza nią: sterownik ViGEmBus dla pada Xbox, loopMIDI dla wirtualnego portu MIDI. Od razu widać, czy to u Ciebie jest.</small><br>\n      <small style=\"color:var(--dim)\">💡 Zestaw nigdy nie uzbraja wyjść: wczytuje konfigurację modułów, ale ich włączniki zostawia tak, jak je zastał. Co autor miał włączone, widzisz przed wczytaniem: w oknie importu i w opisie zestawu w Bibliotece. Zaznacz tam „Wczytaj i od razu aktywuj zestaw”, a aplikacja włączy te moduły zaraz po wczytaniu; bez zaznaczenia powie o nich po wczytaniu i zostawi włączenie Tobie.</small><br>\n      <small style=\"color:var(--dim)\">💡 Przycisk mówi, co zrobi. Gdy po oknie idzie jeszcze jedno — wybór ról kapsli, pytanie o niezapisane zmiany — pisze na nim <b>Dalej</b>. <b>Wczytaj</b> widzisz wyłącznie na przycisku, który naprawdę wczytuje.</small>"},
  // KONFIGURACJA PROGRAMU — trzy ostatnie rozdziały poradnika „Zestawów", przeniesione tutaj
  // 2026-08-31 razem z kartami, które opisują (stop awaryjny, serwer MCP, zgłoszenie problemu).
  // Tekst przyjechał CO DO ZNAKU, więc pary EN sprzed przeprowadzki nadal trafiają — nowy jest
  // wyłącznie tytuł. Zdania „w tej zakładce" zostały prawdziwe: karty pojechały razem z nimi.
  {id:"ustawienia",panel:"tab-ustawienia",title:"Stop awaryjny, asystent AI i zgłoszenia",html:"<h4>🛑 Stop awaryjny<span class=\"gd-hk\" data-hkcombo=\"1\"></span></h4>\n      Gdy wyjście ucieknie, czyli kursor sam wędruje albo został wciśnięty klawisz, a na wierzchu jest gra, ten skrót wstrzymuje wszystkie kapsle naraz: klawisze, mysz, pad, MIDI i OSC. Działa globalnie, więc nie musisz trafić myszą w panel. Tylko zatrzymuje: wyjścia włączasz z powrotem sam, tymi samymi przełącznikami modułów. Kombinację zmienisz w karcie Stop awaryjny w tej zakładce, w zwijaku „Skrót awaryjny”, a aplikacja sprawdzi wybór, zanim go zapiszesz: czy nie zajął go już Windows albo inny program i czy nie koliduje z pisaniem. Prawy Alt (AltGr) nigdy nie uruchamia skrótu, więc pisanie polskich znaków jest bezpieczne z definicji.\n      <p data-i18n-en=\"When the window in front was started as administrator, Windows does not pass the hotkey on, so stop the outputs from the RibbitFlip icon menu in the system tray instead (the “Emergency stop” item).\">Gdy na wierzchu jest okno uruchomione jako administrator, Windows nie przekazuje skrótu, więc wtedy zatrzymaj wyjścia z menu ikony RibbitFlip w zasobniku (pozycja „Stop awaryjny”).</p>\n      <h4>🤖 Asystent AI może ułożyć zestaw (MCP)</h4>\n      Zestaw może też ułożyć za Ciebie asystent AI (np. Claude Code). Karta <b>Serwer MCP (asystenci AI)</b> w zwijaku „Zaawansowane” tej zakładki udostępnia lokalny punkt <code>/mcp</code>. Domyślnie jest wyłączony — włącznik działa od razu, a adres kopiujesz przyciskiem na karcie.\n      <p data-i18n-en=\"What the assistant can actually do with it — and it is more than writing a few rules:\">Co on właściwie może z tym zrobić — a jest tego więcej niż napisanie kilku reguł:</p>\n      <table class=\"g-tab\">\n        <thead><tr><th data-i18n-en=\"What it can do\">Co potrafi</th><th data-i18n-en=\"What that means in practice\">Na czym to polega</th></tr></thead>\n        <tbody>\n          <tr><th scope=\"row\" data-i18n-en=\"Read what you already have\">Przeczytać, co już masz</th><td data-i18n-en=\"version, simulation or real mode, whether the app is armed, and for every capsule: the connection, the battery, how many rules, which outputs are on, the wheel and the scanner, the MIDI and OSC targets, the names of your saved Setups\">wersję, tryb symulacji lub realny, uzbrojenie, a dla każdego kapsla: połączenie, baterię, liczbę reguł, włączone wyjścia, koło i skaner, cele MIDI i OSC, nazwy zapisanych zestawów</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Put together the controls for a game\">Ułożyć sterowanie do gry</th><td data-i18n-en=\"a whole Setup in one go — the rules, motion control, MIDI and OSC, the axes and the battery saving — applied to the capsule you name and saved\">cały zestaw naraz — reguły, sterowanie ruchem, MIDI i OSC, osie i oszczędzanie baterii — na wskazanym kapslu i od razu zapisany</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Change the triggers alone\">Zmienić same wyzwalacze</th><td data-i18n-en=\"add or replace rules without touching anything else; a repeated request corrects a rule instead of doubling it, so asking twice is safe\">dopisać albo podmienić reguły, nie ruszając reszty; powtórzona prośba poprawia regułę zamiast ją dublować, więc nic się nie psuje od proszenia dwa razy</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Set up the wheel and the scanner\">Ustawić koło wyboru i skaner</th><td data-i18n-en=\"these are the two modules a Setup does not carry: the slices and the dials of the wheel, the areas and the dials of the scanner, and loading a saved preset by name\">to dwa moduły, których zestaw nie niesie: wycinki i pokrętła koła, obszary i pokrętła skanera, a także wczytanie zapisanego presetu po nazwie</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Turn a screenshot into a scanner\">Zrobić skaner ze zrzutu gry</th><td data-i18n-en=\"you point at a screenshot file on this computer; the assistant turns it into views and the rectangles for the bar to travel, measured on that picture and stored as percentages of the screen\">wskazujesz plik ze zrzutem na tym komputerze, a asystent zamienia go na plansze i prostokąty do przejeżdżania, zmierzone na tym obrazku i zapisane w procentach ekranu</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Fit the scheme to a body\">Dopasować schemat do ciała</th><td data-i18n-en=\"you say in your own words what you cannot do; the assistant names the places that ask for more — a key to be held, a double click with shaky hands, a threshold beyond your range, a scanner with no way to stop it\">mówisz własnymi słowami, czego nie możesz, a asystent nazywa miejsca, które wymagają więcej: klawisz do trzymania, dwuklik przy drżeniu, próg poza zasięgiem ruchu, skaner bez możliwości zatrzymania</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Look it over without changing it\">Przejrzeć bez zmieniania</th><td data-i18n-en=\"how many rules there are, how many are risky, which output groups they use and a verdict for each one — a dry run that changes nothing\">ile jest reguł, ile ryzykownych, z których wyjść korzystają i werdykt dla każdej — przejście na sucho, które niczego nie zmienia</td></tr>\n          <tr><th scope=\"row\" data-i18n-en=\"Save and switch outputs\">Zapisać i przestawić wyjścia</th><td data-i18n-en=\"save a configuration as a named Setup in the library without applying it, switch the MIDI port, set the OSC host and port, arm or disarm\">zapisać konfigurację jako nazwany zestaw w bibliotece (bez stosowania), przestawić port MIDI, ustawić host i port OSC, uzbroić albo rozbroić</td></tr>\n        </tbody>\n      </table>\n      <p data-i18n-en=\"Every write also pokes the open panel, so you watch the rules appear as they are written — you do not have to take the assistant's word for what it did.\">Każdy zapis szturcha otwarty panel, więc reguły widzisz w chwili, w której powstają — nie musisz wierzyć asystentowi na słowo.</p>\n      <p data-i18n-en=\"Say it in your own words. These are real requests, not a syntax to learn:\">Mów własnymi słowami. To są prawdziwe prośby, a nie składnia do nauczenia:</p>\n      <ul>\n        <li>Podłączenie w Claude Code (domyślny port): <code>claude mcp add --transport http ribbitflip http://127.0.0.1:8770/mcp</code></li>\n        <li>Przykład — platformówka: <i>„Sterowanie: A/D — krok w bok, W/S — marsz, Spacja — unik. Przechył kapsla = ruch, puknięcie kapsla = unik.”</i></li>\n        <li>Przykład — wyścigi: <i>„Kierowanie A/D, gaz W, hamulec S, ręczny Spacja. Przechył steruje, puknięcie = ręczny. Zapisz jako zestaw «Wyścigi».”</i></li>\n        <li>Przykład — audyt: <i>„Pokaż, co mam skonfigurowane i które reguły są ryzykowne.”</i></li>\n        <li><span data-i18n-en=\"Example — a body that cannot hold anything:\">Przykład — ciało, które nic nie utrzyma:</span> <i data-i18n-en=\"“I can tap the capsule once, firmly, and that is about it. I cannot hold anything. Set it up so I can use the computer.”\">„Potrafię pewnie puknąć w kapsel raz i w zasadzie tyle. Nic nie utrzymam. Ustaw mi to tak, żebym mógł obsłużyć komputer.”</i></li>\n        <li><span data-i18n-en=\"Example — a scanner from a screenshot:\">Przykład — skaner ze zrzutu:</span> <i data-i18n-en=\"“Here is a screenshot of the game board (C:/zrzuty/plansza.png). Make me a scanner that walks the sixteen fields of the board and a second one for the action bar at the bottom.”\">„Oto zrzut planszy gry (C:/zrzuty/plansza.png). Zrób mi skaner, który jeździ po szesnastu polach planszy, i drugi na pasek akcji na dole.”</i></li>\n      </ul>\n\n      <h5 data-i18n-en=\"Where the assistant stops\">Gdzie asystent się zatrzymuje</h5>\n      <ul>\n        <li data-i18n-en=\"Four things can only be done by a person at the panel, and the assistant is told to say so out loud instead of quietly leaving them: recording a gesture, creating the virtual controller, the overlay windows and the emergency shortcut.\"><b data-i18n-en=\"Four things only a person can do\">Czterech rzeczy nie zrobi nikt poza człowiekiem przy panelu</b>, a asystent ma o tym powiedzieć wprost, zamiast po cichu je zostawić: nagranie gestu, utworzenie wirtualnego kontrolera, okna nakładek i skrót awaryjny.</li>\n        <li data-i18n-en=\"A rule with a macro, with the Windows key or with a system combination (Alt+F4, Alt+Tab, Ctrl+Alt+Del) is dropped and counted, not applied. This is the same gate the panel uses for a Setup sent by a stranger — because a movement mapped onto real system input is real system input. Everything goes through only after you say so.\"><b data-i18n-en=\"The safe mode is the default.\">Tryb bezpieczny jest domyślny.</b> Reguła z makrem, z klawiszem Windows albo z kombinacją systemową (Alt+F4, Alt+Tab, Ctrl+Alt+Del) zostaje odrzucona i policzona, a nie wczytana. To ta sama bramka, którą panel stawia zestawowi przysłanemu przez obcą osobę — bo ruch zmapowany na prawdziwy input systemowy JEST prawdziwym inputem. Wszystko przechodzi dopiero wtedy, gdy sam na to pozwolisz.</li>\n        <li data-i18n-en=\"Nothing leaves this computer. The assistant talks to a server listening on 127.0.0.1, and the endpoint refuses any request that came from a web page.\"><b data-i18n-en=\"Nothing leaves this computer.\">Nic nie wychodzi poza ten komputer.</b> Asystent rozmawia z serwerem nasłuchującym na <code>127.0.0.1</code>, a punkt <code>/mcp</code> odrzuca każde żądanie, które przyszło ze strony WWW.</li>\n        <li data-i18n-en=\"Being armed stays yours. However well the configuration is written, nothing reaches Windows while the app is disarmed.\"><b data-i18n-en=\"Being armed stays yours.\">Uzbrojenie zostaje przy Tobie.</b> Choćby konfiguracja była napisana idealnie, przy rozbrojonej aplikacji do Windows nie trafia nic.</li>\n      </ul>\n      Asystent pracuje domyślnie w trybie bezpiecznym (makra i klawisze systemowe odrzuca), a przełącznik <b>Uzbrojone</b> zawsze zostaje w Twoich rękach. Start z flagą <code>--no-mcp</code> blokuje MCP na całą sesję. Pełna instrukcja z listą narzędzi: plik <code>docs/MCP.md</code> w repozytorium.\n      <h4>🐞 Zgłoś problem</h4>\n      Gdy coś nie działa, nie zbieraj danych ręcznie: karta <b>Zgłoś problem</b> w tej zakładce buduje paczkę zip z konfiguracją i dziennikami, układa gotowy tytuł oraz treść wpisu i otwiera forum pomocy. Paczka ląduje w katalogu <code>Zgloszenia/</code> obok aplikacji, a przycisk <b>Pokaż w folderze</b> otwiera go w Eksploratorze; rozwijana lista mówi co do pliku, co jest w środku. Wysyłasz ją sam, bo wpis ma wyjść z Twojego konta: wtedy odpowiedź trafia do Ciebie, a wątek zostaje dla następnej osoby z tym samym problemem.<br>\n      <small style=\"color:var(--dim)\">💡 Prywatność: w paczce jest konfiguracja, nazwy zapisanych zestawów i dzienniki, a nie ma sejfu z hasłami, danych przeglądarki z okien nakładek, kluczy z usług sieciowych ani nazwy Twojego konta Windows.</small>"},
  // NAKŁADKA — poradnik dopisany 2026-08-31 razem z paskiem dwóch zakładek (rf-49p). Do tej pory
  // była to JEDYNA pozycja „Reszty" bez poradnika, więc jej zakładka „Informacje" świeciłaby
  // zdaniem „ten ekran nie ma jeszcze poradnika" — a ma o czym mówić najwięcej z całej piątki.
  {id:"skaner",panel:"tab-skaner",title:"Jak działa skaner ekranu?",html:"      Skaner jest dla kogoś, kto ma <b>jeden pewny ruch</b> — naciśnięcie kapsla, przechył, puknięcie — i nie ma jak prowadzić myszy. Po ekranie jedzie pasek, Ty go zatrzymujesz w odpowiedniej chwili, a skaner klika tam, gdzie pasek stanął. Wszystko, co niżej, służy jednej rzeczy: żeby ta chwila była wykonalna dla Twojej ręki.\n      <h4>Trzy kroki</h4>\n      <ul>\n        <li><b>Pasek rusza</b> — po Twoim sygnale albo po chwili postoju, którą sam ustawiasz. W trybie „Pasy” jedzie najpierw w dół, potem w bok (albo odwrotnie, jak wolisz).</li>\n        <li><b>Ty go zatrzymujesz</b> — przyciskiem <b>SYGNAŁ</b> na tej karcie albo kapslem. Pierwszy sygnał wybiera pas, drugi wskazuje na nim miejsce.</li>\n        <li><b>Skaner klika</b> — lewym, dwuklikiem, prawym albo tym, co wybierzesz. Pomyłkę cofa akcja „cofnij o krok”, a nie ponowne celowanie.</li>\n      </ul>\n      <h4>Czym go prowadzisz</h4>\n      Przyciski na tej karcie są do ustawiania. Naprawdę prowadzi go kapsel — zwykłą regułą z <b data-i18n-en=\"Mapping\">Mapowania</b>, w której zamiast klawisza wpisujesz akcję skanera:\n      <ul>\n        <li><code>scan:sygnal</code> — zatrzymaj pasek, wybierz.</li>\n        <li><code>scan:cofnij</code> — o krok wstecz, gdy pasek uciekł.</li>\n        <li><code>scan:stop</code> — przerwij i wróć do spoczynku.</li>\n        <li><code>scan:sekcja=2</code> — pokaż drugi skaner z tej konfiguracji.</li>\n        <li><code>scan:sekcja=nast</code> — następny skaner w bieżącej grupie. Jeden przycisk obsługuje wtedy cały widok gry.</li>\n      </ul>\n      Gotowe wyzwalacze, także takie bez przycisku (przytrzymanie, znieruchomienie, wychylenie), stoją w zwijaku <b>Czym sterujesz skanerem</b> po prawej. ⚠️ Przełącznik <b>modułu Skaner</b> w nagłówku modułu musi być włączony: bez niego żadna z tych akcji nie dochodzi.\n      <h4>Ekran, plansze, skanery — co jest czym</h4>\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 238\" role=\"img\" aria-label=\"Jeden ekran, na nim dwie plansze, a na każdej planszy swoje skanery\">\n          <rect class=\"g-box g-cicho\" x=\"8\" y=\"26\" width=\"624\" height=\"200\"/>\n          <text class=\"g-sub\" x=\"320\" y=\"18\" data-i18n-en=\"SCREEN — your monitor, e.g. 1920×1080\">EKRAN — Twój monitor, np. 1920×1080</text>\n          <rect class=\"g-box\" x=\"36\" y=\"50\" width=\"258\" height=\"156\"/>\n          <text class=\"g-txt\" x=\"165\" y=\"74\" data-i18n-en=\"View: game menu\">Plansza: Menu gry</text>\n          <rect class=\"g-s1\" x=\"56\" y=\"88\" width=\"218\" height=\"40\" rx=\"6\"/>\n          <text class=\"g-sub\" x=\"165\" y=\"113\" data-i18n-en=\"Scanner 1\">Skaner 1</text>\n          <rect class=\"g-s2\" x=\"56\" y=\"140\" width=\"126\" height=\"48\" rx=\"6\"/>\n          <text class=\"g-sub\" x=\"119\" y=\"169\" data-i18n-en=\"Scanner 2\">Skaner 2</text>\n          <rect class=\"g-box\" x=\"346\" y=\"50\" width=\"258\" height=\"156\"/>\n          <text class=\"g-txt\" x=\"475\" y=\"74\" data-i18n-en=\"View: gameplay\">Plansza: Rozgrywka</text>\n          <rect class=\"g-s1\" x=\"366\" y=\"88\" width=\"218\" height=\"40\" rx=\"6\"/>\n          <text class=\"g-sub\" x=\"475\" y=\"113\" data-i18n-en=\"Scanner 1\">Skaner 1</text>\n          <rect class=\"g-s3\" x=\"366\" y=\"140\" width=\"218\" height=\"48\" rx=\"6\"/>\n          <text class=\"g-sub\" x=\"475\" y=\"169\" data-i18n-en=\"Scanner 3\">Skaner 3</text>\n          <path class=\"g-strzalka g-kropkowana\" d=\"M274 108 H366\"/>\n        </svg>\n        <figcaption data-i18n-en=\"There is one screen. The views are its pictures. Scanner 1 works on both — which is why the assignment is held by the view, not by the scanner.\">Ekran jest jeden. Plansze to jego widoki. Skaner 1 pracuje na obu — dlatego przypisanie trzyma plansza, a nie skaner.</figcaption>\n      </figure>\n      Trzy słowa, które łatwo pomylić, bo wszystkie dotyczą tego, co widać:\n      <ul>\n        <li><b data-i18n-en=\"The screen\">Ekran</b> to Twój monitor. Wybierasz go w zwijaku <b>Gdzie skaner ma działać</b> — razem z wycinkiem, po którym pasek ma jeździć. Ekran jest zwykle jeden.</li>\n        <li><b data-i18n-en=\"A view\">Plansza</b> to jeden widok gry na tym ekranie: menu główne, plansza rozgrywki, panel opcji. To nie jest inny monitor, tylko inny obrazek na tym samym. Wgrywasz ją zrzutem ekranu po to, żeby obszar wyznaczać po prawdziwym obrazie gry, a nie na ślepo czterema liczbami.</li>\n        <li><b data-i18n-en=\"A scanner\">Skaner</b> to jedno gotowe ustawienie: obszar plus wszystkie pokrętła. Skanerów mieści się osiem i każdy ma swoją nazwę oraz kolor — „Plansza 4×4”, „Pasek narzędzi”, „Panel opcji”.</li>\n      </ul>\n      Plansza i skaner to nie to samo i na tym stoi cały pomysł: <b>ten sam skaner może pracować na kilku planszach</b> (skaner „cały ekran” przyda się wszędzie), a <b>jedna plansza może mieć kilka skanerów</b> (plansza, pasek akcji i okno czatu).\n      <h4>Co masz z tym zrobić</h4>\n      <ul>\n        <li><b>Zrób zrzut widoku gry</b> i wgraj go jako planszę: przyciskiem „Wgraj planszę…” w „Zaawansowane” › „Plansze”, upuszczeniem pliku na podgląd albo wklejeniem ze schowka.</li>\n        <li><b>Przeciągnij myszą po obrazku</b> — tak wyznaczasz obszar, w którym ten skaner ma jeździć. Liczby w zwijaku „Gdzie skaner ma działać” zmienią się same.</li>\n        <li><b>Nazwij skaner</b> w części „Edytujesz skaner” na dole zwijaka „Zaawansowane”. Nazwa wraca potem w podpowiedzi wyzwalacza i przy planszach.</li>\n        <li><b>Zaznacz, na których planszach ma pracować</b> : chipami <b>Pracuje na planszach</b> w tej samej części. Kropki przy nazwie planszy pokazują, ile skanerów już na niej stoi.</li>\n        <li><b>Powtórz dla kolejnego widoku gry</b>: nowa plansza, do niej nowe skanery albo te, które już masz.</li>\n        <li><b>W grze przełączasz je sam</b> — akcją <code>scan:sekcja=N</code> <span data-i18n-en=\"or\">albo</span> <code>scan:sekcja=nast</code> z kapsla, reguły lub wycinka koła wyboru.</li>\n      </ul>\n      ⚠️ Aplikacja nie widzi, co jest w tej chwili na ekranie gry, więc <b>plansze nie przełączają się same</b>. Są po to, żeby ustawiać obszary na prawdziwym obrazie i trzymać skanery w grupach — przełącza człowiek, jednym gestem.\n      <h4>Zrzut planszy skrótem</h4>\n      Planszę możesz zrobić bez wychodzenia z gry. Włącz <b>Zrzut planszy skrótem</b> (zwijak pod spisem plansz w „Zaawansowane”), a potem naciśnij <b>Alt + R</b> i cyfrę: RibbitFlip zrobi zdjęcie całego ekranu i wstawi je jako planszę o tym numerze.\n      <ul>\n        <li><b>Cyfra to numer planszy.</b> Jeśli plansza o tym numerze już jest, podmienia się sam obraz, a jej nazwa i przypisane skanery zostają. Jeśli jeszcze jej nie ma, dopisuje się na końcu spisu.</li>\n        <li><b>Nazwę bierze z okna gry</b>, więc nowa plansza nazywa się tak, jak gra, w którą grasz.</li>\n        <li><b>Nazwę wpiszesz od razu</b>: po zdjęciu kursor stoi już w polu nazwy planszy, więc wystarczy napisać „Menu główne” i nacisnąć Enter. Esc zostawia nazwę wziętą z okna gry.</li>\n        <li><b>Zaraz po zdjęciu</b> <span data-i18n-en=\"a window with handles stands over the game, so you set the area straight on the live picture, without leaving the game. That is what it does out of the box.\">nad grą staje okno z uchwytami, więc obszar ustawiasz od razu na żywym obrazie, bez wychodzenia z gry. Tak jest fabrycznie.</span></li>\n        <li><b>Co zaraz po zdjęciu</b>, wybierasz przełącznikiem <b>Po zrzucie</b>: <b>Nic</b> zostawia Cię w grze z samym powiadomieniem, <b>W podglądzie</b> wyciąga panel z otwartą planszą, a <b>Na pulpicie</b> stawia nad ekranem okno z uchwytami, którymi ustawisz obszar na żywym oknie gry.</li>\n        <li><b>Okno skanera nad pulpitem chowa się</b> na czas zdjęcia, więc na planszy go nie widać.</li>\n        <li><b>Prawy Alt (AltGr) nigdy nie uruchamia skrótu</b>, bo pisze polskie znaki i tylko to.</li>\n        <li>Przycisk „📸 Zrzut ekranu” w pasku plansz robi to samo bez skrótu: rozwija listę monitorów i fotografuje ten, który wskażesz, jako nową planszę. Ekran, na którym stoi panel, fotografuje się po 3 sekundach, żeby był czas na przejście do gry.</li>\n      </ul>\n      Skrót jest fabrycznie wyłączony, bo zapisuje pliki na dysku. Klawisze przed cyfrą, monitor i kapsel, do którego trafiają zrzuty, zmienisz w tej samej sekcji.\n      <h4>Pulpit testowy, grupy i rozdzielczość</h4>\n      <ul>\n        <li><b data-i18n-en=\"The test desktop\">Pulpit testowy</b> to pierwsza pozycja spisu: rysowany ekran z ikonami i okienkiem ustawień. Stoi tam zawsze, więc ćwiczyć możesz od pierwszej minuty, bez żadnego zrzutu. Widać na nim wszystkie skanery naraz, każdy w swoim kolorze.</li>\n        <li><b>Grupa</b> to plansza bez obrazka — sam spis skanerów pod wspólną nazwą. Przydaje się, gdy zdjęcia widoku nie masz albo nie potrzebujesz, a chcesz, żeby „następny skaner w grupie” chodził tylko po tych kilku.</li>\n        <li><b>Rozdzielczość</b> przy każdej pozycji mówi, z jakiego ekranu pochodzi obraz. Wgrany zrzut podaje ją sam, pulpit testowy zaczyna od rozmiaru Twojego monitora, a wpisany ręcznie zostaje zapamiętany — bo skaner przygotowuje się czasem pod inny ekran niż ten, przy którym się siedzi.</li>\n        <li>Gdy plansza ma inne proporcje niż ekran, na którym skaner pracuje, obraz w ramce jest rozciągnięty i celowanie po nim kłamie. Podpis pod podglądem mówi o tym wprost i podpowiada lekarstwo: wskazanie właściwego monitora w sekcji „Gdzie skaner ma działać”.</li>\n      </ul>\n      <h4>Trzy sposoby wskazywania</h4>\n      <ul>\n        <li><b>Pasy</b> — dwa paski wyznaczają punkt. Najbardziej przewidywalne i najlepsze na start.</li>\n        <li><b>Ćwiartki</b> — ekran dzieli się na pola i zawęża, aż zostanie jedno małe. Szybkie przy dużych przyciskach.</li>\n        <li><b>Radar</b> — najpierw kierunek, potem odległość od środka. Dobre tam, gdzie cele leżą wokół jednego miejsca.</li>\n      </ul>\n      <h4>Dwa narzędzia, które warto przejść raz</h4>\n      <ul>\n        <li><b>Zmierz czas reakcji</b> sprawdza, ile mija od Twojej decyzji do sygnału, i wpisuje to w pokrętło „Wyprzedzenie”. Skaner czyta wtedy pozycję sprzed tylu milisekund — czyli tę, którą naprawdę widziałeś.</li>\n        <li><b>Trening celności</b> stawia kilka celów i liczy trafienia. Oba narzędzia są w „Zaawansowane” › „Trening”. Po nim panel podpowiada, co zmienić: zwolnić pasek, pogrubić pasmo, wydłużyć czas pola.</li>\n      </ul>\n      <h4>Nad prawdziwym pulpitem</h4>\n      Różowy przycisk „Uruchom nad pulpitem” obok „SYGNAŁ” przenosi skaner z podglądu tej karty do okna nad prawdziwym pulpitem. Dopiero tam klika naprawdę. Ten sam wybór stoi w „Zaawansowane” › „Plansze” jako „Gdzie działa”: „W podglądzie” albo „Na pulpicie”. Pod podglądem stoi też „Wyśrodkuj kapsel”, gdy sterujesz przechyłem.\n      <ul>\n        <li>Okno nad pulpitem przepuszcza kliknięcia dalej i nie bierze skupienia, więc żaden klawisz do niego nie dojdzie — sterujesz nim kapslem i panelem.</li>\n        <li>Przy kilku monitorach okno staje nad każdym z nich, każde we własnej skali. Skaner pracuje na jednym: na tym, z którego jest plansza (zrzut zapamiętuje swój ekran), a bez planszy na głównym. Pasek skanera nie przechodzi z monitora na monitor.</li>\n        <li>Na pozostałych ekranach pasek edytora jest krótszy i mówi, że skaner pracuje gdzie indziej. Ramka narysowana na takim ekranie przenosi na niego ustawiany skaner, a przycisk „📸 Zrzut tego ekranu” robi z niego nową planszę.</li>\n        <li>Na dole ekranu stoi pasek edytora: ramka z uchwytami do ustawienia obszaru na żywym oknie gry oraz wybór skanera i grupy. Oczko chowa uchwyty i oddaje kliknięcia pulpitowi; sam obrys zostaje.</li>\n        <li><span data-i18n-en=\"In the corner stands the “What drives the scanner” window — add a ready-made movement for the signal, the step back and the stop, and the “Signal” button runs a trial: the bar crosses the real screen and shows where it would click, without clicking. A signal from the capsule works during a trial too, so you can try your own movement straight away. The window collapses to its title bar and moves with the mouse.\">W rogu stoi okienko „Czym sterujesz skanerem” — dokładasz w nim gotowy ruch do sygnału, cofania i zatrzymania, a przyciskiem „Sygnał” robisz próbę: pasek przejeżdża po prawdziwym ekranie i pokazuje, gdzie by kliknął, ale nie klika. W próbie działa też sygnał z kapsla, więc od razu sprawdzisz swój ruch. Okienko zwija się do paska tytułu i przesuwa myszą.</span></li>\n        <li>Skróty do zamknięcia nakładki i do awaryjnego wyłączenia wszystkiego wypisuje panel obok podglądu — dokładnie te, które masz ustawione.</li>\n      </ul>\n      <h4>Biblioteka</h4>\n      Całą konfigurację skanera — wszystkie skanery, plansze i przypisania — zapisujesz w zakładce <b>Biblioteka</b> tego modułu pod własną nazwą i wczytujesz na dowolny kapsel. Wiersz na liście mówi, ile skanerów i ile plansz niesie preset, i pokazuje miniaturę pierwszej planszy. Zrzuty plansz jadą w środku pliku, więc preset wysłany komuś otwiera się u niego z obrazami, na których ustawiano obszary — nie trzeba dosyłać ich osobno. <span data-i18n-en=\"The preset's description panel shows what loading it would change on the capsule, and an app set you reworked before the app improved it gets a “newer version” chip and an “Update from the app” button (untouched sets update themselves).\">Panel opisu presetu pokazuje, co zmieni jego wczytanie na kapslu, a zestaw z aplikacji, który przerobiłeś, zanim aplikacja go poprawiła, dostaje chip „jest nowsza wersja” i przycisk „Zaktualizuj z aplikacji” (nietknięte zestawy poprawiają się same).</span>"},
  {id:"wszystkie",panel:"tab-wszystkie",title:"Nakładki nad grą",html:"<h4>Do czego służy ten ekran?</h4>\n      <b>Do ustawiania nakładek</b> — małych okienek stojących NAD grą, które pokazują to, co robi kapsel, wtedy gdy panel jest schowany za pełnym ekranem. Wybierasz jedną z nich i widzisz obok, jak wygląda; wszystko, co zmienisz, widać od razu.\n      <figure class=\"g-fig\">\n        <svg viewBox=\"0 0 640 208\" role=\"img\" aria-label=\"Nakładki to małe okienka stojące nad grą na pełnym ekranie, wtedy gdy panel jest za nią schowany.\">\n          <rect class=\"g-box g-cicho\" x=\"96\" y=\"14\" width=\"300\" height=\"150\"/>\n          <text class=\"g-sub\" x=\"246\" y=\"32\" data-i18n-en=\"The RibbitFlip panel — hidden behind the game\">Panel RibbitFlipa — schowany za grą</text>\n          <rect class=\"g-box\" x=\"8\" y=\"46\" width=\"560\" height=\"150\"/>\n          <text class=\"g-txt\" x=\"288\" y=\"70\" data-i18n-en=\"A FULL-SCREEN GAME\">GRA NA PEŁNYM EKRANIE</text>\n          <rect class=\"g-box g-akcent\" x=\"28\" y=\"90\" width=\"150\" height=\"88\"/>\n          <text class=\"g-sub\" x=\"103\" y=\"112\" data-i18n-en=\"An overlay\">Nakładka</text>\n          <text class=\"g-sub\" x=\"103\" y=\"130\" data-i18n-en=\"the stick and the axes\">gałka i osie</text>\n          <text class=\"g-sub\" x=\"103\" y=\"154\" data-i18n-en=\"on the left, where\">po lewej, tam gdzie</text>\n          <text class=\"g-sub\" x=\"103\" y=\"170\" data-i18n-en=\"your eyes go anyway\">i tak wędruje wzrok</text>\n          <rect class=\"g-box g-akcent\" x=\"396\" y=\"90\" width=\"150\" height=\"88\"/>\n          <text class=\"g-sub\" x=\"471\" y=\"112\" data-i18n-en=\"An overlay\">Nakładka</text>\n          <text class=\"g-sub\" x=\"471\" y=\"130\" data-i18n-en=\"the button presses\">naciśnięcia</text>\n          <text class=\"g-sub\" x=\"471\" y=\"154\" data-i18n-en=\"and the triggers\">i wyzwalacze</text>\n          <text class=\"g-sub\" x=\"471\" y=\"170\" data-i18n-en=\"on the right\">po prawej</text>\n          <text class=\"g-sub\" x=\"288\" y=\"148\" data-i18n-en=\"the middle of the screen left free\">środek ekranu wolny</text>\n        </svg>\n        <figcaption data-i18n-en=\"One capsule can have several windows. Each has its own position, size, look and choice of what it shows.\">Jeden kapsel może mieć kilka okien. Każde ma własne położenie, rozmiar, wygląd i wybór tego, co pokazuje.</figcaption>\n      </figure>\n      <h4>Trzy zakładki na górze</h4>\n      <ul>\n        <li><b>Nakładka</b>: całe ustawianie wybranego okna w karcie „Ustawienia tego okna”. Na wierzchu stoi zawartość okna, a w zwijakach „Miejsce i wielkość” oraz „Wygląd tego okna” (motyw, obrys, przyciemnione tło, przezroczystość i rozmiary). Kafelki „Które okno ustawiasz” i nazwa okna są w „Zaawansowane” na dole ekranu.</li>\n        <li><b>Ściąga</b> — dawna zawartość tego ekranu: wszystkie kapsle obok siebie. To ona jest treścią okna nad grą.</li>\n        <li><b>Informacje</b>: ten poradnik.</li>\n      </ul>\n      Podgląd stoi nad kartą, więc masz go i przy zawartości, i przy wyglądzie. Przy wyborze motywu widać od razu, co się wybiera.\n      <h4>Jak ten ekran jest ułożony</h4>\n      Po lewej stoi <b>podgląd</b> i zostaje na miejscu, kiedy przewijasz, a po prawej jest wszystko, co się ustawia: zawartość, miejsce i wygląd. Na wąskim oknie podgląd przechodzi nad ustawienia, żeby obie rzeczy miały swoją szerokość.\n      <h4>Kafelki i podgląd</h4>\n      <ul>\n        <li>W „Zaawansowane” na dole ekranu stoi <b>kafelek na każde okno</b>, pogrupowany kapslami. Kafelek ma proporcję prawdziwego okna, szerokość idącą za jego szerokością i klocki tego, co w nim włączone — czyli mówi „ile ich jest i jak się mają do siebie”. Pod każdym stoi wymiar w pikselach.</li>\n        <li>Po lewej stoi <b>podgląd wybranego okna</b>: ta sama strona, którą program postawi nad grą, w prawdziwym rozmiarze, tylko pomniejszona. Nie jest rysunkiem nakładki obok nakładki — jest nią, oglądaną przez lupę.</li>\n        <li><b>Tło podglądu</b> przełącza umowną ciemną i jasną grę. Nad grą nakładka nie ma żadnego tła — wycina je Windows — więc to jedyny sposób, żeby sprawdzić, czy wygląd i obrys będą czytelne nad tym, w co grasz.</li>\n        <li>Okno <b>koła przy kursorze</b> też ma tu swój kafelek, choć w pasku wyżej go nie ma: nigdzie nie stoi i nie ma rogu do ciągnięcia, ale ma wygląd i tu się go wybiera.</li>\n      </ul>\n      <h4>Co jest w oknie i w jakiej kolejności</h4>\n      W zakładce „Nakładka”, w kolumnie <b>Zawartość</b>, stoi jeden wiersz na każdy element: uchwyt do przeciągania, oko i nazwa. <b>Przeciągnij uchwyt</b> (albo naciśnij na nim strzałkę w górę lub w dół), żeby zmienić kolejność — okno przestawia się razem z listą. <b>Kliknij wiersz</b>, a rozwinie się to, co dotyczy tylko jego: rozmiar i szczegóły. Otwarty jest zawsze jeden.\n      <ul>\n        <li><b>Wyzwalacze</b> — opis reguły, liczniki odpaleń i wykres aktywacji. Wykres nie jest osobnym elementem: jest wierszem w tej liście, więc bez niej nie ma czego rysować.</li>\n        <li><b>Orientacja</b> — liczby pod kulą (nachylenie i obrót).</li>\n        <li><b>Naciśnięcia</b> — długość naciśnięcia liczbą i paski ostatnich sekund.</li>\n        <li><b>Nagłówek</b> — etykieta kapsla i słowo o stanie połączenia.</li>\n        <li><b>Koło wyboru</b> — spis wycinków pod rysunkiem.</li>\n      </ul>\n      Wiersz modułu, w którym nic nie masz wprowadzone — ani jednej reguły, pustego koła, wyłączonego sterowania ruchem — jest <b>wygaszony i podpisany „pusto”</b>. Nie znika: najedź, a powie, czego mu brakuje i gdzie się to dopisuje. Zapali się sam, gdy tylko coś tam powstanie.<ul>\n      </ul>\n      W szufladzie ⚙ samego okna zostają same elementy z suwakami — szczegóły ustawia się tutaj, bo pasek nad grą jest szeroki na jedną kolumnę.\n      <h4>Wielkość okna</h4>\n      Nie ustawia się jej w pikselach — okno mierzy się samo. <b>Szerokość</b> idzie za suwakami „Szerokość” i „Rozmiar całości” ze zwijaka „Wygląd tego okna” (pierwszy mówi, ile miejsca w poziomie ma treść, a drugi, jak duże ma być wszystko), a <b>wysokość</b> za tym, co w oknie włączone: wyłącz orientację, a okno skróci się o nią. Dlatego nie ma już ani rogu do ciągnięcia, ani pól z liczbami, ani proporcji. Powód jest praktyczny: nadmiarowego marginesu nad grą nie widać (tło jest wycięte), ale on <b>łapie kliknięcia</b>, więc okno większe od swojej treści zabiera grze kawałek ekranu za darmo.\n      <h4>Podgląd w prawdziwym oknie</h4>\n      Przełącznik pod podglądem otwiera ustawiane okno <b>naprawdę</b>, na ekranie. Warto go zostawić włączonego: <b>przezroczystość robi Windows</b>, a nie strona, więc miniatura może ją tylko udawać. Okno otwarte w ten sposób zamyka się samo przy zmianie kafelka i przy wyjściu z tej zakładki — a okno, które postawiłeś świadomie, zostaje nietknięte.\n      <h4>Nowa nakładka i szablony</h4>\n      Na końcu kafelków każdego kapsla stoi <b>＋ nowa nakładka</b>. Poza kopią bieżącej masz tam gotowce na jedną rzecz: <b>tylko kontroler</b> (pasek 16:9), <b>tylko koło wyboru</b>, <b>tylko wyzwalacze</b> (słupek przy boku) i <b>tylko orientacja</b>. Każdy z nich to zwykła nakładka z ustawionym z góry rozmiarem i zawartością, więc dalej zmienisz w niej wszystko.\n      <h4>Ściąga wszystkich kapsli</h4>\n      <ul>\n        <li>Kolumna na kapsel: połączenie, tryb ruchu, wirtualny pad, koło wyboru i lista wyzwalaczy z licznikami. Reguła, której warunek jest właśnie spełniony, zapala się na żywo — to jest podgląd dla grającego, a nie kolejne miejsce do klikania.</li>\n        <li><b>Podgląd</b> przełącza między <b>Kompakt</b> i <b>Szczegóły</b>: w szczegółach przy każdej regule stoi jej warunek i wykres ostatnich sekund, w kompakcie sam skrót. <b>Orientacja</b> wybiera, czy kapsel rysuje się jako kula 3D, czy jako płaski inklinometr 2D.</li>\n        <li><b>🪟 Otwórz w oknie</b> otwiera tę samą ściągę jako osobne okno przeglądarki — na drugi monitor albo na telefon w tej samej sieci. To ten sam adres z dopiskiem <code>?view=overview</code>, więc nie potrzebuje reszty panelu.</li>\n      </ul>\n      <h4>Nakładka nad grą</h4>\n      <ul>\n        <li><b>Pokaż nad grą</b> przy kapslu otwiera okienko nad każdym innym oknem, a <b>Dołóż okno</b> dokłada kolejne. Jeden kapsel może mieć ich kilka, bo tak się ich używa: gałkę po lewej, tam gdzie i tak wędruje wzrok, naciśnięcia i wyzwalacze po prawej, środek ekranu wolny. Każde okno ma własne położenie, rozmiar, wygląd i wybór tego, co pokazuje.</li>\n        <li>Okno przeciągasz za <b>górny pasek</b> — i to jedyna rzecz, którą się w nim ustawia ręcznie. Miejsce ustawisz też <b>suwakami X i Y</b> w zakładce „Nakładka”, nie ruszając okna: suwak biegnie po Twoich ekranach, a pole obok przyjmuje dokładną liczbę.</li>\n        <li><b>Pasek okna</b> da się wyłączyć. Nad grą zostaje wtedy sama treść — bez uchwytu, pinezki, ⚙ i ✕ — i żaden kawałek nakładki nie łapie już myszy. Takie okno przesuwasz suwakami w zakładce „Nakładka”, zamykasz przyciskiem w nagłówku karty „Ustawienia tego okna”, a pasek włączasz z powrotem tym samym przełącznikiem, bo w samym oknie nie ma już czego kliknąć.</li>\n        <li><b>Okienko nie ma tła</b>: tam, gdzie nic nie narysowano, widać grę i tam też trafiają kliknięcia. Można też przepuścić przez nie wszystkie kliknięcia — pasek zostaje wtedy klikalny, więc wyłączysz to w tym samym miejscu, w którym włączyłeś.</li>\n        <li><b>Pinezka</b> obok ⚙ trzyma okno na wierzchu i jednocześnie mówi, czy się to udaje: przekreślona na czerwono znaczy, że okno miało być na wierzchu, ale coś je stamtąd zrzuciło.</li>\n        <li>Te same okna otwierasz ikoną dwóch okienek przy kapslu w prawej kolumnie (ta dotyczy wszystkich nakładek tego kapsla naraz) oraz z ikony w zasobniku Windows.</li>\n      </ul>\n      <h4>Układy nakładek</h4>\n      Rozstawienie okienek jest <b>nazwaną konfiguracją</b>, dokładnie tak jak preset w module: pasek <b>Układ</b> pod nagłówkiem zapisuje bieżące rozmieszczenie, przywraca zapisane i kopiuje je gdzie indziej. Układ należy do aplikacji, a nie do kapsla, i nie niesie tego, czy okna są otwarte — otwierasz je sam.\n      <h4>Uwagi</h4>\n      Ta zakładka niczego nie wysyła do Windows: pokazuje to, co robią moduły. Gra w trybie <b>pełnoekranowym wyłącznym</b> zasłania każdą nakładkę — przełącz ją na „okno bez ramki”. Każde okienko jest tylko do odczytu, więc nic w nim nie zapiszesz i nie popsujesz."},
];

/* SPIS ROZDZIAŁÓW NAD KAŻDYM PORADNIKIEM (2026-09-20).

   SKĄD TO SIĘ WZIĘŁO: poradniki wszystkich modułów miały być ciekawsze i bardziej zrozumiałe,
   z formatowaniem i czymś, co ułatwia poruszanie się po nich.

   Poradniki są długie z powodu, który się nie zmieni: opisują moduł, a nie ekran. Najkrótszy ma
   2,7 tys. znaków, najdłuższy 18 tys. — i do tej pory jedyną drogą do rozdziału „Skróty" na końcu
   było przewinięcie wszystkiego nad nim. Spis rozdziałów powstaje z nagłówków, które w poradniku
   już są, więc dokłada się SAM do każdego — także do poradnika Mapowania, który jest pisany
   wprost w rf-34 i nie przechodzi przez tablicę niżej.

   ⚠️ TEKST CHIPA TO TEN SAM WĘZEŁ, CO NAGŁÓWEK — kopiujemy `textContent`, więc walker i18n
   dopasuje go tym samym kluczem, co nagłówek. Gdyby chip składał napis z kawałków („1. " + tytuł),
   klucza by nie było i po angielsku zostałby polski. */
const RF_GUIDE_TOC_I18N={
 "Rozdziały tego poradnika":"The chapters of this guide",
 "↑ Wróć do spisu rozdziałów":"↑ Back to the chapter list",
};
try{ Object.assign(I18N_EN,RF_GUIDE_TOC_I18N); }catch(e){ /* i18n jeszcze nie ma */ }

/* `scroll-margin-top` na celu (05-macro-tabs.css) odsuwa go spod paska górnego; ruch gładki tylko
   wtedy, gdy system go nie wyłączył. */
function _rfGuideSkocz(cel,blysk){
  if(!cel)return;
  const plynnie=!window.matchMedia||!window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  cel.scrollIntoView({block:"start",behavior:plynnie?"smooth":"auto"});
  if(blysk){cel.classList.remove("g-blysk");void cel.offsetWidth;cel.classList.add("g-blysk");}
}

function rfGuideToc(body,id){
  if(!body||body.querySelector(":scope > .g-toc"))return;
  const naglowki=Array.from(body.querySelectorAll(":scope > h4"));
  if(naglowki.length<3)return;            // przy dwóch rozdziałach spis jest dłuższy niż treść
  const nav=document.createElement("nav");
  nav.className="g-toc";
  nav.id="gtoc-"+id;
  nav.setAttribute("aria-labelledby","gtoct-"+id);
  const tyt=document.createElement("div");
  tyt.className="g-toc-tyt";tyt.id="gtoct-"+id;
  tyt.appendChild(document.createTextNode("Rozdziały tego poradnika"));
  nav.appendChild(tyt);
  const ol=document.createElement("ol");
  ol.className="g-toc-lista";
  naglowki.forEach(function(h,i){
    if(!h.id)h.id="g-"+id+"-"+(i+1);
    const li=document.createElement("li");
    const b=document.createElement("button");
    b.type="button";b.className="g-toc-poz";
    b.setAttribute("data-do",h.id);
    const nr=document.createElement("span");
    nr.className="g-toc-nr";nr.setAttribute("aria-hidden","true");
    nr.appendChild(document.createTextNode(String(i+1)+"."));
    const tx=document.createElement("span");
    tx.className="g-toc-tx";
    // ⚠️ TEKST POZYCJI TO KOPIA `textContent` NAGŁÓWKA, w jednym kawałku — walker i18n dopasowuje
    // całe węzły, więc kopia tłumaczy się tym samym kluczem co nagłówek. Numer stoi OBOK, we
    // własnym węźle: gdyby wjechał do napisu („1. Czyje jest koło"), klucza by nie było.
    tx.appendChild(document.createTextNode(h.textContent));
    // …a gdy nagłówek tłumaczy się ATRYBUTEM, a nie słownikiem, kopia musi wziąć ten atrybut ze
    // sobą. Bez tego rozdział dopisany z `data-i18n-en` stoi po polsku w angielskim spisie —
    // złapane na żywo na rozdziale „Koło razem ze skanerem ekranu".
    const ov = h.getAttribute("data-i18n-en");
    if(ov)tx.setAttribute("data-i18n-en",ov);
    b.appendChild(nr);b.appendChild(tx);li.appendChild(b);ol.appendChild(li);
  });
  nav.appendChild(ol);
  nav.addEventListener("click",function(ev){
    const c=ev.target.closest("[data-do]");if(!c)return;
    _rfGuideSkocz(document.getElementById(c.getAttribute("data-do")),true);
  });
  body.insertBefore(nav,body.firstChild);
  // Powrót na górę po przeczytaniu ostatniego rozdziału. Przy poradniku długim na osiemnaście
  // tysięcy znaków droga w drugą stronę to inaczej przewinięcie całości kółkiem.
  const stopka=document.createElement("div");
  stopka.className="g-toc-wroc";
  const wroc=document.createElement("button");
  wroc.type="button";
  wroc.appendChild(document.createTextNode("↑ Wróć do spisu rozdziałów"));
  wroc.addEventListener("click",function(){_rfGuideSkocz(nav,false);});
  stopka.appendChild(wroc);
  body.appendChild(stopka);
}

/* OSTRZEŻENIA I WSKAZÓWKI WIDOCZNE Z JEDNEGO SPOJRZENIA (2026-09-20).

   Style `.g-uwaga` i `.g-tip` istniały od rana, ale nic ich nie zakładało: żeby z nich skorzystać,
   piszący poradnik musiałby pamiętać o klasie przy każdym punkcie zaczynającym się od ⚠️. Tutaj
   robi to kod — po PIERWSZYM ZNAKU treści, bo to jedyna cecha, która w tych punktach naprawdę jest.

   ⚠️ Klasa ląduje na ELEMENCIE, nie na tekście: węzły tekstowe zostają co do znaku, więc żadna para
   PL→EN się nie zrywa. Ostrzeżenia stojące w ŚRODKU zdania („…po prawej. ⚠️ Przełącznik…") celowo
   zostają zwykłym tekstem — wyróżnienie ich wymagałoby rozcięcia węzła, czyli zgubienia tłumaczenia
   całego akapitu, a i tak są tam wtrąceniem, nie osobną myślą. */
const RF_GUIDE_MARKERY={"⚠":"g-uwaga","⛔":"g-uwaga","\u{1f4a1}":"g-tip"};
function rfGuideCallouts(body){
  if(!body)return;
  for(const el of body.querySelectorAll("li,p")){
    if(el.closest(".g-toc"))continue;     // spis rozdziałów to nawigacja, nie treść
    if(el.classList.contains("g-uwaga")||el.classList.contains("g-tip"))continue;
    // Pierwszy ZNACZĄCY znak całego punktu — nie pierwszego węzła: <li>⚠️ <b>Tekst</b></li>
    // i <li><b>⚠️ Tekst</b></li> to dla czytającego to samo.
    const t=(el.textContent||"").trim();
    if(!t)continue;
    const kl=RF_GUIDE_MARKERY[Array.from(t)[0]];
    if(kl)el.classList.add(kl);
  }
}

function initGuides(){
  // ŚCIĄGA `?view=overview` NIE DOSTAJE PORADNIKÓW. Komentarz niżej mówił, że nie ma tam paneli —
  // to nieprawda: panele są, tylko wszystkie POZA `tab-wszystkie` chowa arkusz
  // (13-dialogs-overview.css). Do 2026-08-31 nie miało to znaczenia, bo jedyny widoczny panel był
  // jedyną pozycją bez poradnika. Odkąd ma swój, prepend wsadzałby zwinięty poradnik na samą górę
  // widoku, który istnieje po to, żeby stać na drugim monitorze i pokazywać wyłącznie ściągę.
  // Reszta i tak jest tam niewidoczna, więc budowanie dziesięciu drzew DOM na zapas nie ma po co.
  const _cheat=document.body.classList.contains("overview-only");
  for(const g of RF_GUIDES){
    if(_cheat)continue;
    const panel=document.getElementById(g.panel);
    if(!panel||document.getElementById("guide-"+g.id))continue;
    const d=document.createElement("details");d.className="mapwiki";d.id="guide-"+g.id;
    const s=document.createElement("summary");
    const ic=document.createElement("span");ic.className="rfic guide-ic";ic.setAttribute("aria-hidden","true");
    s.appendChild(ic);s.appendChild(document.createTextNode(g.title));   // separate text node -> exact-match i18n works
    const b=document.createElement("div");b.className="mapwiki-body";b.innerHTML=g.html;
    d.appendChild(s);d.appendChild(b);
    panel.insertBefore(d,panel.firstChild);                             // stays on top: modules append their cards below
    // Guides always start collapsed; drop any open-state key an older version may have left behind.
    try{localStorage.removeItem("ribbitflip.guide."+g.id);}catch(e){}
  }
  /* Spis rozdziałów dla WSZYSTKICH poradników na stronie, nie tylko tych z tablicy wyżej —
     poradnik Mapowania powstaje w rf-34 i tamtędy nie przechodzi, a jest najdłuższy z tych,
     które czyta się na początku. Szukamy po klasie, bo to jedyna cecha wspólna obu dróg. */
  if(!_cheat)for(const body of document.querySelectorAll(".mapwiki > .mapwiki-body")){
    const d=body.parentNode;
    rfGuideToc(body,(d.id||"guide-mapowanie").replace(/^guide-/,""));
    rfGuideCallouts(body);
  }
  // The setups guide names the emergency combination in a heading. It used to say "Alt + R + F"
  // in the text itself, which is a lie the moment somebody changes it — so the heading carries an
  // empty [data-hkcombo] slot and rf-39j fills it with whatever the hotkey actually is, here and
  // on every later change.
  try{ if(typeof rfHotkeyFillSpots==="function")rfHotkeyFillSpots(); }catch(e){}
  // Same reasoning for the number of built-in templates: the guide used to say "13" in its own
  // text, which stopped being true the first time a template was added and nobody noticed for
  // two of them. The sentence now carries an empty [data-packn] slot, filled from the catalogue.
  try{
    const n=(typeof REST_PACKS!=="undefined"&&Array.isArray(REST_PACKS))?REST_PACKS.length:0;
    if(n)for(const el of document.querySelectorAll("[data-packn]"))el.textContent=String(n);
  }catch(e){}
}
